                self.sqk_fav.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToContents)
                self.sqk_fav.currentIndexChanged.connect(self.request_sqk)
                pick.addWidget(self.sqk_fav)
