        for key, label in ALERT_MATCHES.items():
            self.match.addItem(label, key)
        self.text = QLineEdit()
        self.text.setPlaceholderText("e.g. Sheriff East Dispatch, TGID:44002, 162.5500, UID:3235996")
        self.text.returnPressed.connect(self.add_rule)
        add_btn = QPushButton("ADD RULE")
        add_btn.clicked.connect(self.add_rule)
        for w in (self.field, self.match):
            add.addWidget(w)
        add.addWidget(self.text, 1)
        add.addWidget(add_btn)
        layout.addLayout(add)
        self.table = QTableWidget(0, 4)
        self.table.setHorizontalHeaderLabels(["On", "Field", "Match", "Text"])
        self.table.horizontalHeader().setStretchLastSection(True)
        self.table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        self.table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.itemChanged.connect(self.rule_toggled)
