        def note(form, text):
            lab = make_label(text)
            lab.setWordWrap(True)
            lab.linkActivated.connect(open_in_browser)      # not KDE's default: it may be a snap
            set_css(lab, "color:#a5bdd2;")
            form.addRow(lab)

        self.boxes = {}
        box = QGroupBox("ntfy")
        f = QFormLayout(box)
        note(f, "Install the free <b>ntfy</b> app (Android or iPhone), tap +, and subscribe to the "
                "topic below. Anyone who knows the topic name can read it, so keep the random one.")
