        note.setWordWrap(True)
        set_css(note, "color:#a5bdd2;")
        f.addRow(note)
        self.boxes["udp"] = box
        box = QGroupBox("PHONE OR DEVICE (TCP)")
        f = QFormLayout(box)
        self.tcp_host = QLineEdit(str(g.setting("tcp_host", "")))
        self.tcp_host.setPlaceholderText("phone's address, e.g. 192.168.1.50")
        f.addRow("Address", self.tcp_host)
        self.tcp_port = QSpinBox()
        self.tcp_port.setRange(1, 65535)
        self.tcp_port.setValue(int(g.setting("tcp_port", 11123) or 11123))
        f.addRow("Port", self.tcp_port)
