        self.max_minutes.setRange(0, 120)
        self.max_minutes.setSuffix(" min (0 = only by distance)")
        self.max_minutes.setValue(int(g.setting("max_minutes", 10)))
        f.addRow("…or at least every", self.max_minutes)
