# ---- Plasma widget (1.1.84) ------------------------------------------------------------------------------
# The Scanner Information panel for a KDE Plasma 6 widget (plasma-widget/, installed by the .deb).
# The Monitor keeps the scanner's port, so the widget asks the Monitor: a small server on
# 127.0.0.1 (random port), with a token. Port and token go in ~/SDS100Monitor/widget.json (only
# you can read it), which the widget reads when it can't reach the Monitor.
WIDGET_FILE = DATA_DIR / "widget.json"
WIDGET_ID = "com.github.jmlynchjr.sds100monitor"
WIDGET_ACTIONS = {"channel_hold": "channel_hold", "scan": "scan", "avoid": "avoid_now",
                  "unavoid": "unavoid_now"}
WIDGET_COMPACT = ("Channel", "Frequency", "System", "Department", "Site", "Talkgroup", "Unit ID",
                  "Mode", "RSSI")


def widget_state(monitor):
    """What the widget shows: the panel's lines as you set them up (labels, colours and the
    conditional colours already worked out), plus a few plain values for the panel line."""
    layout = getattr(monitor, "info_layout_now", None) or default_info_layout()
    values = monitor.info_now()
    panel, styles = info_styles(layout, values)
    lines = [{"label": line["label"] if line["show_label"] else "", "text": info_text(line, values),
              "fg": fg, "bg": bg, "size": line["size"], "bold": line["bold"]}
             for line, (fg, bg) in zip(layout["lines"], styles)]
    modes = getattr(monitor, "modes_window", None)
    mode_text = modes.state_text if modes is not None else ""
    last = getattr(monitor, "last_avoided", None)
    return {"version": VERSION, "connected": bool(getattr(monitor, "connected", False)),
            "receiving": bool(getattr(monitor, "reception", None)),
            "panel_bg": panel, "lines": lines,
            "values": {k: str(values.get(k, "") or "") for k in WIDGET_COMPACT},
            "special_mode": mode_text if mode_text and not mode_text.startswith("Scanner:") else "",
            "can_hold": bool(getattr(monitor, "current_channel_index", None)
                             and getattr(monitor, "current_channel_type", None)),
            "last_avoided": last[2] if last else "",
            # v1.1.93: today so far (worked out every 2 minutes while the widget asks)
            "today": today_text(stats.for_widget()) if (stats := getattr(monitor, "today_stats", None)) else []}


def today_stats(day, gap=600, min_calls=3, unit_names=None, unit_title=uid_label, now=None, recent=600):
    """Today so far, for the Plasma widget (v1.1.93): {calls, incidents, going_on [(start "HH:MM", type,
    headline, units)], last_alert {time, kind, title, text} or None}. Incidents "going on" had a call in the
    last `recent` seconds."""
    now = now or datetime.now()
    recs = receptions_with_units(day)
    going, count = [], 0
    if recs:
        before = (datetime.strptime(day, "%Y-%m-%d") - timedelta(days=1)).strftime("%Y-%m-%d")
        hubs = find_hubs(recs + receptions_with_units(before), unit_names)
        for inc in build_incidents(recs, hubs, gap=gap, min_calls=min_calls, edits=load_incident_edits(day)):
            if inc["hidden"]:
                continue
            count += 1
            if (now - inc["end"]).total_seconds() <= recent:
                summary = summarize_incident(inc, None, (), unit_title)
                going.append((inc["start"].strftime("%H:%M"), summary["type"], summary["headline"], len(inc["units"])))
    alerts = [a for a in read_alert_log(day) if a[1] != "test"]
    last = alerts[-1] if alerts else None
    return {"day": day, "calls": len(recs), "incidents": count, "going_on": going[-3:],
            "last_alert": ({"time": last[0][11:16], "kind": ALERT_KIND_LABELS.get(last[1], last[1]),
                            "title": last[2], "text": last[3]} if last else None)}


def today_text(stats):
    """The widget's lines for today, as plain text (also what tests check)."""
    if not stats:
        return []
    lines = [f"Today: {stats['calls']:,} calls • {stats['incidents']} incident{'s' if stats['incidents'] != 1 else ''}"
             + (f" ({len(stats['going_on'])} going on)" if stats["going_on"] else "")]
    for start, kind, headline, units in stats["going_on"]:
        lines.append(f"▶ {start} {INCIDENT_TYPE_LABELS.get(kind, 'Other')}: {headline}")
    if stats["last_alert"]:
        a = stats["last_alert"]
        lines.append(f"Last alert {a['time']}: {a['title']}" + (f" — {a['text']}" if a["text"] else ""))
    return lines


class TodayStats(QObject):
    """Works out today_stats() every 2 minutes in a worker thread, while the widget is asking (v1.1.93)."""
    computed = pyqtSignal(object)
    kick = pyqtSignal()                            # from the widget server's thread: start a computation

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.data = None
        self.kick.connect(lambda: self.tick(force=True))
        self.asked = 0.0                           # time.monotonic() of the widget's last question
        self.busy = False
        self.last_run = float("-inf")      # v1.1.101: not 0 — right after boot, monotonic time is small
        self.computed.connect(self.store)
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.tick)
        self.timer.start(20000)

    def wanted(self):
        return self.asked > 0 and time.monotonic() - self.asked < 300

    def tick(self, force=False):
        if self.busy or not (force or self.wanted()):
            return
        if not force and time.monotonic() - self.last_run < 115:
            return
        self.busy, self.last_run = True, time.monotonic()
        s = self.monitor.settings
        gap, min_calls = int(s.value("incidents/gap", 10)) * 60, int(s.value("incidents/min_calls", 3))
        names, title = self.monitor.unit_names, self.monitor.unit_title
        day = datetime.now().strftime("%Y-%m-%d")

        def work():
            try:
                self.computed.emit(today_stats(day, gap, min_calls, names, title))
            except Exception:                      # never let the widget stop monitoring
                self.computed.emit(None)
        threading.Thread(target=work, daemon=True).start()

    def store(self, data):
        self.busy = False
        if data is not None:
            self.data = data

    def for_widget(self):
        """Called by the widget server: note the question, start a first computation, return the last result."""
        first = not self.wanted()
        self.asked = time.monotonic()
        if first:
            self.kick.emit()                       # queued to the main thread
        return self.data


class WidgetServer(QObject):
    """Serves widget_state() to the Plasma widget and takes its Hold / Scan / Avoid presses."""
    control_requested = pyqtSignal(str)

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.token = os.urandom(16).hex()
        self.httpd = None
        self.control_requested.connect(self.control)

    @property
    def enabled(self):
        return str(self.monitor.settings.value("widget/enabled", "true")).lower() == "true"

    def set_enabled(self, on):
        self.monitor.settings.setValue("widget/enabled", "true" if on else "false")
        self.start() if on else self.shutdown()

    def control(self, action):
        if action in WIDGET_ACTIONS:
            self.monitor.control(WIDGET_ACTIONS[action])

    def start(self):
        if self.httpd is not None or not self.enabled:
            return
        srv = self

        class H(BaseHTTPRequestHandler):
            def log_message(self, *a):
                pass

            def send(self, code, body):
                data = json.dumps(body).encode()
                self.send_response(code)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(data)))
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                self.wfile.write(data)

            def authorized(self):
                q = parse_qs(urlparse(self.path).query)
                given = self.headers.get("X-Token") or (q.get("t") or [""])[0]
                return hmac.compare_digest(given, srv.token)

            def do_GET(self):
                if not self.authorized():
                    return self.send(403, {"error": "forbidden"})
                if urlparse(self.path).path == "/api/state":
                    try:
                        return self.send(200, widget_state(srv.monitor))
                    except Exception as exc:          # never take the Monitor down for the widget
                        return self.send(500, {"error": str(exc)})
                self.send(404, {"error": "not found"})

            def do_POST(self):
                if not self.authorized():
                    return self.send(403, {"error": "forbidden"})
                u = urlparse(self.path)
                action = (parse_qs(u.query).get("a") or [""])[0]
                if u.path == "/api/control" and action in WIDGET_ACTIONS:
                    srv.control_requested.emit(action)
                    return self.send(200, {"ok": True})
                self.send(400, {"error": "bad request"})

        try:
            port = int(self.monitor.settings.value("widget/port", 0) or 0)
            self.httpd = ThreadingHTTPServer(("127.0.0.1", port), H)
        except (OSError, ValueError) as exc:
            self.httpd = None
            print(f"Plasma widget server not started: {exc}", file=sys.stderr)
            return
        threading.Thread(target=self.httpd.serve_forever, daemon=True).start()
        self.write_file()

    def write_file(self):
        try:
            DATA_DIR.mkdir(parents=True, exist_ok=True)
            tmp = WIDGET_FILE.with_suffix(".tmp")
            fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
            with os.fdopen(fd, "w") as f:
                json.dump({"port": self.httpd.server_address[1], "token": self.token,
                           "pid": os.getpid(), "version": VERSION}, f)
            os.chmod(tmp, 0o600)
            os.replace(tmp, WIDGET_FILE)
        except OSError as exc:
            print(f"Plasma widget file not written: {exc}", file=sys.stderr)

    def shutdown(self):
        if self.httpd is not None:
            self.httpd.shutdown()
            self.httpd.server_close()
            self.httpd = None
        try:
            if WIDGET_FILE.exists() and json.loads(WIDGET_FILE.read_text()).get("pid") == os.getpid():
                WIDGET_FILE.unlink()
        except (OSError, ValueError):
            pass


def plasma_widget_installed():
    """Where the widget is installed (system-wide by the .deb, or for you), or None."""
    for base in (Path("/usr/share/plasma/plasmoids"),
                 Path.home() / ".local/share/plasma/plasmoids"):
        if (base / WIDGET_ID / "metadata.json").exists():
            return base / WIDGET_ID
    return None


class MapServer(QObject):
    """Serves the map page and its data on 127.0.0.1 (random port, token)."""
    play_requested = pyqtSignal(str, str)

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.token = os.urandom(16).hex()
        self.httpd = None
        self.busy = ""
        self.focus_key = None
        self.play_requested.connect(self.play)

    def data(self, hours, focus=None):
        now = datetime.now()
        since = (now - timedelta(hours=hours)).strftime("%Y-%m-%d %H:%M:%S")
        days = [d for d in place_days() if d >= since[:10]]
        rows = []
        for day in days:
            rows += [r for r in read_places(day) if r[0] >= since and r[11] != "hidden"]
        if focus and not any(place_key(r) == focus for r in rows):
            # A place picked from an older incident: show it too, outside the chosen hours.
            rows += [r for r in read_places(focus[0][:10]) if place_key(r) == focus]
        rows.sort(key=lambda r: r[0], reverse=True)
        names = self.monitor.unit_names
        places = []
        focus_index = None
        for r in rows:
            units = ", ".join(f"{names.display(k) or uid_label(k)}" for k in units_in(r[5]))
            try:
                lat, lon = float(r[8]), float(r[9])
            except ValueError:
                lat = lon = None
            if focus and place_key(r) == focus:
                focus_index = len(places)
            places.append({"time": r[0], "day": r[0][:10], "channel": r[3], "talkgroup": r[4],
                           "units": units, "place": r[6], "kind": r[7], "lat": lat, "lon": lon,
                           "found_as": r[10], "status": r[11], "file": r[12], "transcript": r[13]})
        gps = self.monitor.gps.position() if getattr(self.monitor, "gps", None) else None
        scanner = getattr(self.monitor.gps, "scanner_location", None)
        rng = getattr(self.monitor.gps, "scanner_range", None)
        return {"now": now.strftime("%Y-%m-%d %H:%M:%S"), "places": places, "focus": focus_index,
                "gps": {"lat": gps[0], "lon": gps[1]} if gps else None,
                "scanner": {"lat": scanner[0], "lon": scanner[1], "range_miles": rng or 0} if scanner else None,
                "busy": self.busy}

    def play(self, day, name):
        path = AUDIO_DIR / day / Path(name).name
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", day) and path.exists():
            QDesktopServices.openUrl(QUrl.fromLocalFile(str(path)))

    def start(self):
        if self.httpd is not None:
            return self.url()
        srv = self
        page = MAP_HTML.replace("__TOKEN__", self.token)

        class H(BaseHTTPRequestHandler):
            def log_message(self, *a):
                pass

            def send(self, code, body, ctype="application/json"):
                data = body if isinstance(body, bytes) else json.dumps(body).encode()
                self.send_response(code)
                self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(data)))
                self.send_header("Cache-Control", "no-store")
                self.end_headers()
                self.wfile.write(data)

            def authorized(self):
                q = parse_qs(urlparse(self.path).query)
                given = self.headers.get("X-Token") or (q.get("t") or [""])[0]
                return hmac.compare_digest(given, srv.token)

            def do_GET(self):
                u = urlparse(self.path)
                if not self.authorized():
                    return self.send(403, {"error": "forbidden"})
                if u.path == "/":
                    return self.send(200, page.encode(), "text/html; charset=utf-8")
                if u.path == "/api/data":
                    q = parse_qs(u.query)
                    try:
                        hours = max(1, min(24 * 90, int((q.get("hours") or ["24"])[0])))
                    except ValueError:
                        hours = 24
                    focus = srv.focus_key
                    srv.focus_key = None
                    try:
                        return self.send(200, srv.data(hours, focus))
                    except Exception as exc:
                        return self.send(500, {"error": str(exc)})
                self.send(404, {"error": "not found"})

            def do_POST(self):
                if not self.authorized():
                    return self.send(403, {"error": "forbidden"})
                if urlparse(self.path).path == "/api/play":
                    try:
                        body = json.loads(self.rfile.read(int(self.headers.get("Content-Length") or 0)) or b"{}")
                        srv.play_requested.emit(str(body.get("day", "")), str(body.get("file", "")))
                        return self.send(200, {"ok": True})
                    except ValueError:
                        return self.send(400, {"error": "bad request"})
                self.send(404, {"error": "not found"})

        self.httpd = ThreadingHTTPServer(("127.0.0.1", int(self.monitor.settings.value("places/map_port", 0) or 0)), H)
        threading.Thread(target=self.httpd.serve_forever, daemon=True).start()
        return self.url()

    def url(self):
        return f"http://127.0.0.1:{self.httpd.server_address[1]}/?t={self.token}"

    def shutdown(self):
        if self.httpd is not None:
            self.httpd.shutdown()
            self.httpd.server_close()
            self.httpd = None


def open_in_browser(url):
    """Open a URL, preferring a browser that isn't a snap (the snap Firefox
    can't always reach pages served on this computer)."""
    import shlex
    env = os.environ.get("BROWSER")
    candidates = [shlex.split(env.split(":")[0])] if env else []
    for cmd in ("/usr/lib/firefox/firefox", "firefox", "firefox-esr", "chromium", "chromium-browser",
                "google-chrome", "brave-browser"):
        path = cmd if cmd.startswith("/") and os.access(cmd, os.X_OK) else shutil.which(cmd)
        if path:
            real = os.path.realpath(path)
            snap = real.startswith("/snap/") or "/snap/bin/" in path
            if not snap and os.path.getsize(real) < 16384:
                try:
                    with open(real, "rb") as f:
                        head = f.read(16384)
                    snap = head.startswith(b"#!") and (b"/snap/bin/" in head or b"snap run" in head)
                except OSError:
                    pass
            if not snap:
                candidates.append([path])
    for argv in candidates:
        try:
            subprocess.Popen(argv + [url], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL, start_new_session=True)
            return True
        except OSError:
            continue
    return QDesktopServices.openUrl(QUrl(url))


class PlacesWindow(QWidget):
    """Tools → Maps → Places and Map…"""
    COLUMNS = ["Time", "Place heard", "Found as", "Status", "Channel", "Units", "Transcript"]

    def __init__(self, monitor):
        super().__init__(monitor)
        analysis_window(self, monitor, "Places and Map", "places/geometry", (1150, 700))
        self.monitor = monitor
        self.finder = monitor.places_finder
        self.rows = []
        layout = QVBoxLayout(self)
        intro = make_label("Addresses, intersections and your landmarks heard in transcripts, looked up on "
                       "OpenStreetMap. Give your area so streets are found in the right town; with GPS on, "
                       "places near you are preferred.")
        intro.setWordWrap(True)
        layout.addWidget(intro)
        top = QHBoxLayout()
        self.area_label = make_label("Area")
        top.addWidget(self.area_label)
        self.area = QLineEdit(str(self.finder.setting("area", "")))
        self.area.setPlaceholderText("Town or county, state, e.g. Hagerstown, MD")
        self.area.editingFinished.connect(self.save_area)
        top.addWidget(self.area, 1)
        self.radius_label = make_label("within")
        top.addWidget(self.radius_label)
        self.radius = QSpinBox()
        self.radius.setRange(5, 300)
        self.radius.setSuffix(" km")
        self.radius.setValue(int(float(self.finder.setting("radius_km", 40))))
        self.radius.valueChanged.connect(lambda v: monitor.settings.setValue("places/radius_km", v))
        top.addWidget(self.radius)
        self.auto = QCheckBox("Find places in new transcripts")
        self.auto.setChecked(self.finder.auto)
        self.auto.toggled.connect(lambda on: monitor.settings.setValue("places/auto", "true" if on else "false"))
        top.addWidget(self.auto)
        for w in (self.area_label, self.area, self.radius_label, self.radius, self.auto):
            w.hide()                   # v1.2.0: in Settings → GPS and maps (kept here, hidden, in step)
        place_settings = QPushButton("SETTINGS…")
        place_settings.setToolTip("Your area, how far to look, and finding places in new transcripts")
        place_settings.clicked.connect(lambda: self.monitor.open_settings("maps"))
        top.addWidget(place_settings)
        top.addStretch(1)
        marks = QPushButton("LANDMARKS…")
        marks.setToolTip("Local names to recognise, e.g. the high school, with their position")
        marks.clicked.connect(self.edit_landmarks)
        top.addWidget(marks)
        open_map = QPushButton("OPEN MAP")
        set_css(open_map, "QPushButton{background:#2167b1;color:white;font-weight:700;padding:6px 12px;border-radius:6px;}")
        open_map.clicked.connect(lambda: self.open_map())
        top.addWidget(open_map)
        layout.addLayout(top)
        bar = QHBoxLayout()
        bar.addWidget(make_label("Day"))
        self.days = QComboBox()
        self.days.currentIndexChanged.connect(self.load_day)
        bar.addWidget(self.days)
        scan = QPushButton("FIND PLACES IN THIS DAY'S TRANSCRIPTS")
        scan.clicked.connect(self.scan_day)
        bar.addWidget(scan)
        self.status = QLabel()
        set_css(self.status, "color:#a5bdd2;")
        bar.addWidget(self.status, 1)
        layout.addLayout(bar)
        self.table = unit_table(self.COLUMNS)
        stretch_last(self.table)
        self.table.cellDoubleClicked.connect(lambda r, _c: self.show_on_map(r))
        self.table.customContextMenuRequested.connect(self.menu)
        layout.addWidget(self.table, 1)
        hint = make_label("Double-click a place to show it on the map. Right-click to play the call, correct "
                      "the position, or hide a mistaken place. Map data © OpenStreetMap contributors.")
        hint.setWordWrap(True)
        set_css(hint, "color:#a5bdd2;")
        layout.addWidget(hint)
        self.finder.found.connect(self.place_found)
        self.finder.status.connect(self.show_status)

    def open(self):
        self.reload()
        restore_window(self, self.monitor)

    def save_settings(self, settings):
        if self.geometry_restored:
            settings.setValue(self.geometry_key, self.saveGeometry())

    def save_area(self):
        self.monitor.settings.setValue("places/area", self.area.text().strip())
        self.finder.area_bias = None

    def show_status(self, text):
        set_text(self.status, text)
        self.monitor.map_server.busy = text

    def reload(self):
        current = self.days.currentText()
        days = sorted(set(place_days()) | {p.name for p in AUDIO_DIR.glob("????-??-??") if p.is_dir()}
                      if AUDIO_DIR.exists() else set(place_days()), reverse=True)
        self.days.blockSignals(True)
        self.days.clear()
        self.days.addItems(days)
        if current in days:
            self.days.setCurrentText(current)
        self.days.blockSignals(False)
        self.load_day()

    def load_day(self, *_):
        day = self.days.currentText()
        self.rows = sorted(read_places(day), key=lambda r: r[0], reverse=True) if day else []
        names = self.monitor.unit_names
        fill_table(self.table, [[r[0][11:], r[6], r[10] or "—", r[11], r[3],
                                 ", ".join(names.display(k) or uid_label(k) for k in units_in(r[5])),
                                 r[13]] for r in self.rows])
        self.table.resizeRowsToContents()

    def place_found(self, row):
        if row[0][:10] == self.days.currentText():
            self.load_day()
        elif self.days.findText(row[0][:10]) < 0:
            self.days.insertItem(0, row[0][:10])

    def row_at(self, r):
        index = table_row_index(self.table, r)
        return self.rows[index] if index is not None and index < len(self.rows) else None

    def open_map(self, focus=None):
        url = self.monitor.map_server.start()
        self.monitor.map_server.focus_key = focus
        if not open_in_browser(url):
            QMessageBox.information(self, "Map", f"Open this address in your browser:\n{url}")

    def show_on_map(self, r):
        row = self.row_at(r)
        if row is not None:
            self.open_map(place_key(row))

    def scan_day(self):
        day = self.days.currentText()
        if not day:
            return
        n = self.finder.scan_day(day)
        set_text(self.status, f"Checking {n} transcripts for places…" if n else "No transcripts that day.")

    def menu(self, point):
        index = table_row_index(self.table, point)
        if index is None or index >= len(self.rows):
            return
        row = self.rows[index]
        menu = QMenu(self)
        menu.addAction("Show on Map", lambda: self.open_map(place_key(row)))
        path = AUDIO_DIR / row[0][:10] / row[12]
        if path.exists():
            menu.addAction("Play Call", lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(str(path))))
        if row[8] and row[9]:
            menu.addAction("Open in OpenStreetMap",
                           lambda: open_in_browser(f"https://www.openstreetmap.org/?mlat={row[8]}&mlon={row[9]}#map=17/{row[8]}/{row[9]}"))
            menu.addAction("Copy Position", lambda: copy_text(f"{row[8]}, {row[9]}"))
        menu.addAction("Correct Position…", lambda: self.correct(row))
        if row[11] != "hidden":
            menu.addAction("Not a Place (hide)", lambda: self.set_status(row, "hidden"))
        else:
            menu.addAction("Show Again", lambda: self.set_status(row, "corrected" if row[8] else "not found"))
        if row[6]:
            menu.addAction("Add as Landmark…", lambda: self.add_landmark(row))
        menu.exec(self.table.viewport().mapToGlobal(point))

    def correct(self, row):
        text, ok = QInputDialog.getText(self, "Correct position",
                                        f"Latitude, longitude for \"{row[6]}\" (e.g. 39.6418, -77.7200).\n"
                                        "Tip: right-click the spot on openstreetmap.org → Show address.",
                                        text=f"{row[8]}, {row[9]}" if row[8] else "")
        if not ok:
            return
        m = re.match(r"\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$", text)
        if not m or not (-90 <= float(m.group(1)) <= 90 and -180 <= float(m.group(2)) <= 180):
            QMessageBox.warning(self, "Correct position", "Enter latitude, longitude as two numbers.")
            return
        new = list(row)
        new[8], new[9], new[11] = f"{float(m.group(1)):.6f}", f"{float(m.group(2)):.6f}", "corrected"
        new[10] = new[10] or row[6]
        save_place(new)
        self.load_day()

    def set_status(self, row, status):
        new = list(row)
        new[11] = status
        save_place(new)
        self.load_day()

    def add_landmark(self, row):
        name, ok = QInputDialog.getText(self, "Add landmark", "Name as it's said on the radio:", text=row[6])
        if not ok or not name.strip():
            return
        pos = f"{row[8]}, {row[9]}" if row[8] else ""
        pos, ok = QInputDialog.getText(self, "Add landmark", "Latitude, longitude:", text=pos)
        if ok and parse_landmarks(f"x = {pos}"):
            text = str(self.finder.setting("landmarks", "")).rstrip()
            self.monitor.settings.setValue("places/landmarks", (text + "\n" if text else "") + f"{name.strip()} = {pos}")

    def edit_landmarks(self):
        text, ok = QInputDialog.getMultiLineText(
            self, "Landmarks",
            "Local names said on the radio, one per line as  Name = latitude, longitude\n"
            "e.g.  North High School = 39.6512, -77.7134\n"
            "Saved places from Scanner Tools → Location are included automatically.",
            str(self.finder.setting("landmarks", "")))
        if ok:
            self.monitor.settings.setValue("places/landmarks", text.strip())


# ---- Antenna Test (v1.1.36) ----------------------------------------------------
# Tools → Antenna Test…: step through saved reference signals, sample each one,
# and compare labelled sessions ("Antenna A", "roof mount") side by side.
#
# Readings come from GSI (RSSI, signal bars, squelch, digital decode) and, for a
# P25 site, from the scanner's own Analyze → System Status (Signal S and Decode
# Quality Q). None of this is calibrated; it is meant for A/B comparison with
# the same scanner, coax and place.
ANTENNA_DIR = DATA_DIR / "antenna_tests"
ANTENNA_REFS_FILE = ANTENNA_DIR / "references.json"
ANTENNA_KINDS = {
    # kind: (label, default seconds, description)
    "site": ("P25 site (control channel)", 120,
             "A trunked site, sampled with the scanner's Analyze → System Status: "
             "Decode Quality (Q) and Signal (S). For a simulcast system Q is the number "
             "that matters. An optional voice window then holds the site and counts calls."),
    "continuous": ("Continuous signal", 90,
                   "A signal that is always on, such as NOAA weather radio. Every reading "
                   "during the hold is used."),
    "bursty": ("Bursty / repeater (DMR, conventional)", 1200,
               "A repeater that is idle between transmissions, such as a VHF DMR repeater. "
               "Only readings taken while a signal is present are used, and transmissions "
               "are counted. Needs a long window (15–30 minutes)."),
    "noise": ("Noise floor (an empty frequency)", 60,
              "A frequency with nothing on it. Shows how much noise the antenna picks up "
              "in that band: lower is better."),
}
ANTENNA_KIND_ORDER = ("site", "continuous", "bursty", "noise")
NOAA_FREQS = (162.400, 162.425, 162.450, 162.475, 162.500, 162.525, 162.550)
ANTENNA_SETTLE_S = 3.0          # readings ignored right after reaching a reference
ANTENNA_TUNE_TIMEOUT_S = 15.0   # give up on a reference the scanner doesn't reach
ANTENNA_SITE_TIMEOUT_S = 30.0   # v1.1.114: Analyze → System Status can take longer to lock on to a site
ANTENNA_TX_GAP_S = 1.5          # a gap shorter than this doesn't end a transmission
ANTENNA_DIGITAL = {"P25", "DMR", "CAP", "CON", "DT3", "XPT", "NX9", "NX4", "NXD"}
ANTENNA_COLORS = ("#3d8fd6", "#e6a65a", "#52dc95", "#b48cf0", "#ff7b7b", "#8bd6f2",
                  "#d6c95a", "#c0c8d4")
# Sample rows: [seconds since start, RSSI dBm|None, bars|None, squelch open 0/1,
#               Q|None, S|None, digital decode 0/1, phase "m" (main) / "v" (voice)]
S_T, S_RSSI, S_SIG, S_OPEN, S_Q, S_S, S_DEC, S_PHASE = range(8)

# metric: (label, unit, direction (+1 higher is better), threshold, relative)
# The threshold is the smallest difference reported as real; relative ones are
# a fraction of the average value (counts and times vary with traffic).
ANTENNA_METRICS = {
    "q_med": ("Decode quality Q (median)", "", 1, 5, False),
    "q_p10": ("Decode quality Q (worst 10%)", "", 1, 5, False),
    "s_med": ("Signal S (median)", "", 1, 5, False),
    "rssi_med": ("RSSI (median)", "dBm", 1, 2, False),
    "rssi_spread": ("RSSI spread, p90 − p10 (fading)", "dB", -1, 2, False),
    "sig_avg": ("Signal bars (average of 4)", "", 1, 0.5, False),
    "tx": ("Transmissions heard", "", 1, 0.2, True),
    "active_s": ("Time with signal present", "s", 1, 0.2, True),
    "decoded_pct": ("Decoded while signal present", "%", 1, 10, False),
    "calls": ("Voice calls heard", "", 1, 0.2, True),
    "call_rssi": ("RSSI during calls (median)", "dBm", 1, 2, False),
    "noise_med": ("Noise RSSI (median)", "dBm", -1, 2, False),
    "open_pct": ("Time a signal was present", "%", -1, 5, False),
}
ANTENNA_KIND_METRICS = {
    "site": ("q_med", "q_p10", "s_med", "rssi_med", "calls", "call_rssi", "decoded_pct"),
    "continuous": ("rssi_med", "rssi_spread", "sig_avg"),
    "bursty": ("rssi_med", "tx", "active_s", "decoded_pct"),
    "noise": ("noise_med", "open_pct"),
}
ANTENNA_SUMMARY_HEADERS = (
    ["Session", "Label", "Notes", "Started", "Reference", "Type", "Frequency (MHz)",
     "Site index", "Status", "Samples"]
    + [ANTENNA_METRICS[k][0] + (f" ({ANTENNA_METRICS[k][1]})" if ANTENNA_METRICS[k][1] else "")
       for k in ANTENNA_METRICS]
    + ["Notes on result"])
ANTENNA_SAMPLE_HEADERS = ["Session", "Label", "Reference", "Type", "Phase", "Seconds",
                          "RSSI (dBm)", "Signal bars", "Squelch open", "Decode quality Q",
                          "Signal S", "Digital decode"]


def antenna_band(mhz):
    """A short band name for a frequency in MHz, for grouping in the results."""
    if mhz is None:
        return "—"
    for low, high, name in ((25, 54, "Low band"), (108, 137, "Airband"), (137, 174, "VHF"),
                            (174, 225, "VHF high"), (225, 400, "Military air"),
                            (400, 512, "UHF"), (758, 806, "700"), (806, 870, "800"),
                            (894, 960, "900"), (1240, 1300, "1.2 GHz")):
        if low <= mhz < high:
            return name
    return "—"


def antenna_default_kind(mhz):
    return "continuous" if mhz is not None and 162.39 <= mhz <= 162.56 else "bursty"


def antenna_ref_key(ref):
    """What makes two references the same signal, across sessions."""
    if ref.get("kind") == "site":
        return ("site", str(ref.get("site_index", "")))
    mhz = ref.get("mhz")
    return (ref.get("kind"), round(float(mhz), 4) if mhz is not None else None)


def antenna_ref_target(ref):
    if ref.get("kind") == "site":
        name = ref.get("site_name") or "site"
        return f"{name} (site index {ref.get('site_index', '?')})"
    mhz = ref.get("mhz")
    return f"{mhz:.4f} MHz" if mhz is not None else "—"


def antenna_ref_seconds(ref):
    seconds = int(ref.get("seconds") or ANTENNA_KINDS.get(ref.get("kind"), ("", 90))[1])
    voice = int(ref.get("voice_seconds") or 0) if ref.get("kind") == "site" else 0
    return seconds, voice


def antenna_estimate_s(refs):
    """Rough run length: sampling time plus tuning and settling overhead."""
    total = 0
    for ref in refs:
        seconds, voice = antenna_ref_seconds(ref)
        total += seconds + 8 + (voice + 6 if voice else 0)
    return total


def antenna_duration_text(seconds):
    seconds = int(round(seconds))
    if seconds < 60:
        return f"{seconds} s"
    minutes, sec = divmod(seconds, 60)
    if minutes < 60:
        return f"{minutes} min {sec:02d} s" if sec else f"{minutes} min"
    hours, minutes = divmod(minutes, 60)
    return f"{hours} h {minutes:02d} min"


def percentile(values, frac):
    """Linear-interpolated percentile (frac 0..1) of a list of numbers, or None."""
    values = sorted(v for v in values if v is not None)
    if not values:
        return None
    pos = (len(values) - 1) * frac
    low = int(math.floor(pos))
    high = min(low + 1, len(values) - 1)
    return values[low] + (values[high] - values[low]) * (pos - low)


def antenna_active(row, kind):
    """Signal present in a sample: squelch open, or (except in a voice window)
    at least one signal bar, for repeaters that stay muted on undecoded audio."""
    if row[S_OPEN]:
        return True
    return kind != "voice" and (row[S_SIG] or 0) >= 1


def antenna_transmissions(rows, poll_s, kind="bursty"):
    """(start, end) seconds of each transmission found in sample rows."""
    spans = []
    for row in sorted(rows, key=lambda r: r[S_T]):
        if not antenna_active(row, kind):
            continue
        t = row[S_T]
        if spans and t - spans[-1][1] <= ANTENNA_TX_GAP_S + poll_s:
            spans[-1][1] = t
        else:
            spans.append([t, t])
    # Each reading stands for one polling interval of signal.
    return [(start, end + poll_s) for start, end in spans]


def antenna_summary(result, poll_s=0.5):
    """Metrics for one reference in one session: {metric key: value}."""
    kind = result.get("kind")
    samples = result.get("samples") or []
    main = [s for s in samples if s[S_PHASE] == "m"]
    voice = [s for s in samples if s[S_PHASE] == "v"]
    m = {}

    def rssi(rows):
        return [s[S_RSSI] for s in rows if s[S_RSSI] is not None]

    if kind == "bursty":
        active = [s for s in main if antenna_active(s, kind)]
        r = rssi(active)
        if r:
            m["rssi_med"] = percentile(r, 0.5)
        if main:
            spans = antenna_transmissions(main, poll_s, kind)
            m["tx"] = len(spans)
            m["active_s"] = round(sum(e - b for b, e in spans), 1)
        if active:
            m["decoded_pct"] = 100.0 * sum(1 for s in active if s[S_DEC]) / len(active)
    elif kind == "noise":
        r = rssi(main)
        if r:
            m["noise_med"] = percentile(r, 0.5)
        if main:
            m["open_pct"] = 100.0 * sum(1 for s in main if antenna_active(s, kind)) / len(main)
    else:
        r = rssi(main)
        if r:
            m["rssi_med"] = percentile(r, 0.5)
            if len(r) >= 5:
                m["rssi_spread"] = percentile(r, 0.9) - percentile(r, 0.1)
        bars = [s[S_SIG] for s in main if s[S_SIG] is not None]
        if bars:
            m["sig_avg"] = sum(bars) / len(bars)
        if kind == "site":
            q = [s[S_Q] for s in main if s[S_Q] is not None]
            if q:
                m["q_med"] = percentile(q, 0.5)
                m["q_p10"] = percentile(q, 0.1)
            s_values = [s[S_S] for s in main if s[S_S] is not None]
            if s_values:
                m["s_med"] = percentile(s_values, 0.5)
            if voice:
                m["calls"] = len(antenna_transmissions(voice, poll_s, "voice"))
                active = [s for s in voice if s[S_OPEN]]
                cr = rssi(active)
                if cr:
                    m["call_rssi"] = percentile(cr, 0.5)
                if active:
                    m["decoded_pct"] = 100.0 * sum(1 for s in active if s[S_DEC]) / len(active)
    return m


def antenna_result_notes(result, metrics):
    notes = []
    if result.get("message"):
        notes.append(result["message"])
    if result.get("att"):
        notes.append("Attenuator was on for part of this reading")
    kind = result.get("kind")
    if kind == "bursty" and result.get("status") == "ok" and metrics.get("tx", 0) < 3:
        notes.append("Few transmissions heard; a longer window gives a fairer comparison")
    if kind == "site" and result.get("status") == "ok" and "q_med" not in metrics:
        notes.append("No System Status readings (Q/S) arrived")
    if kind in ("continuous", "noise") and result.get("status") == "ok" and \
            not any(s[S_RSSI] is not None for s in result.get("samples") or []):
        notes.append("The scanner reported no RSSI here; only signal bars were recorded")
    return notes


def antenna_format(metric, value):
    if value is None:
        return "—"
    unit = ANTENNA_METRICS[metric][1]
    if unit == "dBm":
        return f"{value:.1f} dBm"
    if unit == "dB":
        return f"{value:.1f} dB"
    if unit == "%":
        return f"{value:.0f}%"
    if unit == "s":
        return antenna_duration_text(value)
    if metric in ("tx", "calls"):
        return f"{int(value)}"
    if metric == "sig_avg":
        return f"{value:.2f}"
    return f"{value:.0f}"


def antenna_delta_text(metric, delta):
    unit = ANTENNA_METRICS[metric][1]
    sign = "+" if delta >= 0 else "−"
    size = abs(delta)
    if unit in ("dBm", "dB"):
        return f"{sign}{size:.1f} dB"
    if unit == "%":
        return f"{sign}{size:.0f} pts"
    if unit == "s":
        return f"{sign}{antenna_duration_text(size)}"
    if metric == "sig_avg":
        return f"{sign}{size:.2f}"
    return f"{sign}{size:.0f}"


def antenna_threshold(metric, values):
    _label, _unit, _direction, threshold, relative = ANTENNA_METRICS[metric]
    if relative:
        present = [v for v in values if v is not None]
        mean = sum(present) / len(present) if present else 0
        return max(2.0, threshold * mean)
    return threshold


def antenna_session_name(session):
    started = session.get("started", "")
    try:
        stamp = datetime.fromisoformat(started).strftime("%m-%d %H:%M")
    except ValueError:
        stamp = started
    return f"{session.get('label') or 'Unlabelled'} · {stamp}"


def antenna_compare(sessions, poll_s=0.5):
    """Rows comparing sessions, oldest first.

    Returns (rows, drift). Each row: {"key", "name", "kind", "metric", "values",
    "threshold", "best", "verdict"}; "best" is the index of the clearly best
    session or None. drift maps (ref key, metric) to the largest difference
    between sessions that share a label (the same antenna run twice), which is
    how much the readings moved on their own."""
    sessions = sorted(sessions, key=lambda s: s.get("started", ""))
    refs = {}
    summaries = []
    for session in sessions:
        by_key = {}
        for result in session.get("results", []):
            key = antenna_ref_key(result.get("ref", {}))
            refs.setdefault(key, (result.get("ref", {}).get("name") or antenna_ref_target(
                result.get("ref", {})), result.get("kind")))
            if result.get("samples"):
                by_key[key] = antenna_summary(result, session.get("poll_s", poll_s))
        summaries.append(by_key)
    drift = {}
    labels = defaultdict(list)
    for i, session in enumerate(sessions):
        labels[(session.get("label") or "").strip().casefold()].append(i)
    for key, (_name, kind) in refs.items():
        for metric in ANTENNA_KIND_METRICS.get(kind, ()):
            worst = None
            for members in labels.values():
                values = [summaries[i].get(key, {}).get(metric) for i in members]
                values = [v for v in values if v is not None]
                if len(values) >= 2:
                    spread = max(values) - min(values)
                    worst = spread if worst is None else max(worst, spread)
            if worst is not None:
                drift[(key, metric)] = worst
    rows = []
    for key, (name, kind) in refs.items():
        for metric in ANTENNA_KIND_METRICS.get(kind, ()):
            values = [summaries[i].get(key, {}).get(metric) for i in range(len(sessions))]
            present = [(i, v) for i, v in enumerate(values) if v is not None]
            if not present:
                continue
            threshold = max(antenna_threshold(metric, values), drift.get((key, metric), 0))
            direction = ANTENNA_METRICS[metric][2]
            best = None
            verdict = ""
            if len(present) >= 2:
                ranked = sorted(present, key=lambda p: p[1] * direction, reverse=True)
                top, runner = ranked[0], ranked[1]
                # Sessions with the same label as the top one don't count as rivals.
                top_label = (sessions[top[0]].get("label") or "").strip().casefold()
                rivals = [p for p in ranked[1:]
                          if (sessions[p[0]].get("label") or "").strip().casefold() != top_label]
                if rivals:
                    runner = rivals[0]
                    gap = abs(top[1] - runner[1])
                    if gap > threshold:
                        best = top[0]
                        verdict = (f"{sessions[top[0]].get('label') or 'Unlabelled'} by "
                                   f"{antenna_delta_text(metric, gap).lstrip('+')}")
                    else:
                        verdict = "≈ no clear difference"
                else:
                    verdict = "same label only"
            rows.append({"key": key, "name": name, "kind": kind, "metric": metric,
                         "values": values, "threshold": threshold, "best": best,
                         "verdict": verdict})
    return rows, drift


def antenna_load_refs():
    try:
        data = json.loads(ANTENNA_REFS_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return []
    refs = [r for r in data.get("references", []) if isinstance(r, dict)
            and r.get("kind") in ANTENNA_KINDS]
    for i, ref in enumerate(refs):
        ref.setdefault("id", f"r{i + 1}")
        ref.setdefault("enabled", True)
    return refs


def antenna_save_refs(refs):
    ANTENNA_DIR.mkdir(parents=True, exist_ok=True)
    tmp = ANTENNA_REFS_FILE.with_suffix(".tmp")
    tmp.write_text(json.dumps({"format": 1, "references": refs}, indent=1), encoding="utf-8")
    tmp.replace(ANTENNA_REFS_FILE)


def antenna_session_path(session_id):
    return ANTENNA_DIR / f"session_{session_id}.json"


def antenna_save_session(session):
    ANTENNA_DIR.mkdir(parents=True, exist_ok=True)
    path = antenna_session_path(session["id"])
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(session, separators=(",", ":")), encoding="utf-8")
    tmp.replace(path)


def antenna_load_sessions():
    sessions = []
    if not ANTENNA_DIR.is_dir():
        return sessions
    for path in sorted(ANTENNA_DIR.glob("session_*.json")):
        try:
            session = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(session, dict) and session.get("id"):
            sessions.append(session)
    sessions.sort(key=lambda s: s.get("started", ""))
    return sessions


def antenna_snapshot_stats(frames):
    """Average 240-bin trace (per-bin median of the frames) and its levels."""
    trace = [int(round(percentile([f[i] for f in frames], 0.5))) for i in range(GRAPH_BINS)]
    return {"trace": trace, "floor": percentile(trace, 0.5),
            "p90": percentile(trace, 0.9), "peak": max(trace)}


class AntennaTester(QObject):
    """Runs an antenna test: tunes each reference, collects readings, saves the
    session. Fed by the Monitor with every GSI report, Analyze XML, reply and
    waterfall frame."""
    changed = pyqtSignal()
    result_done = pyqtSignal(dict)
    finished = pyqtSignal(dict)
    snapshot_done = pyqtSignal(dict)
    message = pyqtSignal(str)

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.session = None
        self.plan = []
        self.index = -1
        self.result = None
        self.phase = "idle"
        self.phase_until = 0.0
        self.deadline = 0.0
        self.sample_start = 0.0
        self.sample_end = 0.0
        self.in_analyze = False
        self.resume_after = True
        self.last_status = None          # (Q, S, monotonic time) from System Status
        self.last_gsi = {}
        self.live = {}
        self.snap = None
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.tick)
        self.timer.start(250)
        monitor.scanner_output.connect(self.reply)

    # ---- state -----------------------------------------------------------
    @property
    def running(self):
        return self.session is not None

    @property
    def capturing(self):
        return self.snap is not None

    def current_ref(self):
        return self.plan[self.index] if 0 <= self.index < len(self.plan) else None

    def poll_s(self):
        return max(0.1, getattr(self.monitor, "active_poll_ms", 500) / 1000)

    def progress(self):
        """(overall fraction, step fraction, step text) for the window."""
        if not self.running or not self.plan:
            return 0.0, 0.0, ""
        now = time.monotonic()
        total = antenna_estimate_s(self.plan) or 1
        done = antenna_estimate_s(self.plan[:max(0, self.index)])
        ref = self.current_ref()
        step = 0.0
        text = ""
        if ref is not None:
            seconds, voice = antenna_ref_seconds(ref)
            if self.phase in ("sample", "voice"):
                length = max(1.0, self.sample_end - self.sample_start)
                step = min(1.0, (now - self.sample_start) / length)
                left = max(0, self.sample_end - now)
                text = ("Voice window" if self.phase == "voice" else "Sampling") + \
                    f": {antenna_duration_text(left)} left"
                done += (seconds + 8) * (step if self.phase == "sample" else 1)
                if self.phase == "voice":
                    done += (voice + 6) * step
            else:
                text = {"prep": "Preparing…", "tune": "Waiting for the scanner…",
                        "settle": "Settling…", "voice_prep": "Holding the site…"}.get(
                            self.phase, self.phase)
        return min(1.0, done / total), step, text

    # ---- running ---------------------------------------------------------
    def start(self, refs, label, notes, resume=True):
        if self.running or not refs:
            return False
        if not self.monitor.connected:
            self.message.emit("Connect to the scanner first.")
            return False
        now = datetime.now()
        fix = getattr(self.monitor.gps, "last_fix", None) if hasattr(self.monitor, "gps") else None
        session_id = now.strftime("%Y%m%d_%H%M%S")
        n = 1
        while antenna_session_path(session_id).exists():
            n += 1
            session_id = now.strftime("%Y%m%d_%H%M%S") + f"_{n}"
        self.session = {
            "format": 1, "id": session_id, "label": label.strip(),
            "notes": notes.strip(), "started": now.isoformat(timespec="seconds"),
            "ended": "", "version": VERSION, "poll_s": self.poll_s(),
            "location": ({"lat": fix["lat"], "lon": fix["lon"]}
                         if fix and fix.get("lat") is not None else None),
            "results": [], "snapshots": []}
        self.plan = [dict(r) for r in refs]
        self.index = -1
        self.in_analyze = False
        self.resume_after = resume
        self.next_ref()
        return True

    def stop(self):
        if not self.running:
            return
        if self.result is not None:
            self.result["status"] = "stopped"
            self.result["message"] = "Stopped before the reading finished"
        self.finish(stopped=True)

    def connection_changed(self, connected):
        if not connected and self.running:
            if self.result is not None:
                self.result["status"] = "connection lost"
                self.result["message"] = "The scanner disconnected during this reading"
            self.finish(stopped=True, send=False)
        if not connected and self.snap is not None:
            self.end_snapshot(None, "The scanner disconnected.")
        self.changed.emit()

    def shutdown(self):
        if self.running:
            self.stop()

    def set_phase(self, phase, until=0.0):
        self.phase = phase
        self.phase_until = until
        self.changed.emit()

    def next_ref(self):
        self.close_result()
        self.index += 1
        ref = self.current_ref()
        if ref is None:
            self.finish()
            return
        seconds, voice = antenna_ref_seconds(ref)
        self.result = {"ref": ref, "kind": ref["kind"], "status": "running", "message": "",
                       "started": datetime.now().isoformat(timespec="seconds"),
                       "seconds_planned": seconds, "voice_planned": voice,
                       "att": False, "samples": []}
        self.live = {}
        self.last_status = None
        now = time.monotonic()
        if ref["kind"] == "site" or self.in_analyze:
            # Analyze needs scan mode, and QSH isn't accepted from Analyze.
            self.monitor.queue("JPM,SCN_MODE,4294967295")
            self.in_analyze = False
            self.set_phase("prep", now + 3.0)
        else:
            self.set_phase("prep", now)

    def begin_tune(self):
        ref = self.current_ref()
        now = time.monotonic()
        self.deadline = now + (ANTENNA_SITE_TIMEOUT_S if ref["kind"] == "site" else ANTENNA_TUNE_TIMEOUT_S)
        # The phase is set first, so a reply that comes straight back is seen.
        self.set_phase("tune")
        if ref["kind"] == "site":
            command = f"AST,SYSTEM_STATUS,{ref.get('site_index')}"
            self.in_analyze = True
            self.monitor.queue(command)
            self.monitor.command_reply("QUEUED: " + command + " (Antenna Test)")
        else:
            self.monitor.tune_frequency(float(ref["mhz"]))

    def begin_sampling(self):
        seconds, _voice = antenna_ref_seconds(self.current_ref())
        now = time.monotonic()
        self.sample_start = now
        self.sample_end = now + seconds
        self.set_phase("sample")

    def begin_voice(self):
        self.monitor.queue("JPM,SCN_MODE,4294967295")
        self.in_analyze = False
        self.set_phase("voice_prep", time.monotonic() + 2.5)

    def tick(self):
        now = time.monotonic()
        if self.snap is not None and now > self.snap["deadline"]:
            self.end_snapshot(None, f"Only {len(self.snap['frames'])} waterfall frames arrived "
                                    "in 20 seconds. Is the scanner in waterfall mode?")
        if not self.running:
            return
        ref = self.current_ref()
        if ref is None:
            return
        if self.phase == "prep" and now >= self.phase_until:
            self.begin_tune()
        elif self.phase == "tune" and now >= self.deadline:
            self.result["status"] = "not reached"
            self.result["message"] = ("The scanner didn't confirm " + antenna_ref_target(ref)
                                      + f" within {ANTENNA_SITE_TIMEOUT_S if ref['kind'] == 'site' else ANTENNA_TUNE_TIMEOUT_S:.0f} s"
                                      + (": Analyze → System Status gave no readings for that site index"
                                         if ref["kind"] == "site" else ""))
            self.next_ref()
        elif self.phase == "settle" and now >= self.phase_until:
            self.begin_sampling()
        elif self.phase == "sample" and now >= self.sample_end:
            _seconds, voice = antenna_ref_seconds(ref)
            if ref["kind"] == "site" and voice:
                self.begin_voice()
            else:
                self.result["status"] = "ok"
                self.next_ref()
        elif self.phase == "voice_prep" and now >= self.phase_until:
            command = f"HLD,SITE,{ref.get('site_index')},"
            _seconds, voice = antenna_ref_seconds(ref)
            self.sample_start = now
            self.sample_end = now + voice
            self.set_phase("voice")
            self.monitor.queue(command)
            self.monitor.command_reply("QUEUED: " + command + " (Antenna Test voice window)")
        elif self.phase == "voice" and now >= self.sample_end:
            self.result["status"] = "ok"
            self.next_ref()
        self.changed.emit()

    def close_result(self):
        if self.result is None or self.session is None:
            return
        result = self.result
        self.result = None
        if result["status"] == "running":
            result["status"] = "stopped"
        result["ended"] = datetime.now().isoformat(timespec="seconds")
        self.session["results"].append(result)
        self.save()
        self.result_done.emit(result)

    def finish(self, stopped=False, send=True):
        self.close_result()
        session = self.session
        if session is None:
            return
        session["ended"] = datetime.now().isoformat(timespec="seconds")
        session["stopped"] = stopped
        self.save()
        if send and (self.resume_after or self.in_analyze):
            # Analyze is always left, even when the scanner should stay put.
            self.monitor.queue("JPM,SCN_MODE,4294967295")
        self.session = None
        self.plan = []
        self.index = -1
        self.in_analyze = False
        self.set_phase("idle")
        self.finished.emit(session)

    def save(self):
        try:
            antenna_save_session(self.session)
        except OSError as exc:
            self.message.emit(f"Couldn't save the antenna test: {exc}")

    # ---- input from the Monitor ------------------------------------------
    def reply(self, text):
        if not self.running:
            return
        ref = self.current_ref()
        if ref is None:
            return
        if self.phase == "tune" and ref["kind"] == "site" and text.startswith("REPLY: AST,"):
            body = text[len("REPLY: AST,"):].strip()
            if body.endswith(("NG", "ERR")) or ",ERR" in body:
                self.in_analyze = False
                self.result["status"] = "refused"
                self.result["message"] = (f"The scanner refused System Status (AST,{body}). "
                                          "Is the site index right, and is the site in a "
                                          "monitored Favorites List?")
                self.next_ref()
        elif self.phase == "voice" and text.startswith("REPLY: HLD,"):
            body = text[len("REPLY: HLD,"):].strip()
            if body.endswith(("NG", "ERR")):
                self.result["message"] = ("The scanner refused to hold the site (HLD,"
                                          f"{body}); calls on that site were counted while "
                                          "scanning instead")

    def analyze_xml(self, xml):
        if not self.running:
            return
        try:
            root = ET.fromstring(xml)
        except ET.ParseError:
            return
        for element in root.iter("SystemStatus"):
            self.take_status(element)

    def take_status(self, element):
        def number(*names):
            try:
                return max(0, min(100, int(float(xml_attr(element, *names)))))
            except ValueError:
                return None
        q, s = number("Quality"), number("Signal")
        if q is not None or s is not None:
            self.last_status = (q, s, time.monotonic())
            ref = self.current_ref()
            if self.phase == "tune" and ref is not None and ref["kind"] == "site":
                self.set_phase("settle", time.monotonic() + ANTENNA_SETTLE_S)

    def gsi(self, root):
        """Every GSI report: remember the scanner's state, take a reading."""
        prop = root.find("Property")
        channel = next((node for tag in ("ConvFrequency", "TGID", "TrunkingChannel",
                                         "SrchFrequency")
                        if (node := root.find(tag)) is not None), None)
        freq = channel.attrib.get("Freq", "") if channel is not None else ""
        site_freq = root.find("SiteFrequency")
        if not freq.strip() and site_freq is not None:
            freq = site_freq.attrib.get("Freq", "")
        site = root.find("Site")
        system = root.find("System")

        def get(node, key):
            return node.attrib.get(key, "").strip() if node is not None else ""
        try:
            rssi = int(get(prop, "Rssi"))
            if rssi == -999:
                rssi = None
        except ValueError:
            rssi = None
        sig = get(prop, "Sig")
        sig = min(4, int(sig)) if sig.isdigit() else None
        p25 = get(prop, "P25Status")
        info = {
            "mhz": parse_mhz(freq), "name": get(channel, "Name"), "mod": get(channel, "Mod"),
            "site_index": get(site, "Index"), "site_name": get(site, "Name"),
            "system": get(system, "Name"),
            "site_mhz": parse_mhz(get(site_freq, "Freq")) if site_freq is not None else None,
            "rssi": rssi, "sig": sig, "open": get(prop, "Mute").lower() == "unmute",
            "decoded": p25 in ANTENNA_DIGITAL, "att": get(prop, "Att") not in ("", "Off"),
            "p25": p25,
        }
        self.last_gsi = info
        status = root.find("SystemStatus")
        if self.running and status is not None:
            self.take_status(status)
        if not self.running:
            return
        ref = self.current_ref()
        if ref is None:
            return
        now = time.monotonic()
        if self.phase == "tune" and ref["kind"] != "site":
            if info["mhz"] is not None and abs(info["mhz"] - float(ref["mhz"])) < 0.0005:
                self.set_phase("settle", now + ANTENNA_SETTLE_S)
            return
        if self.phase not in ("sample", "voice"):
            return
        if self.phase == "voice" and ref.get("site_index") and info["site_index"] and \
                info["site_index"] != str(ref["site_index"]):
            return          # scanning something else (site hold refused)
        q = s = None
        if ref["kind"] == "site" and self.phase == "sample" and self.last_status \
                and now - self.last_status[2] < 3:
            q, s = self.last_status[0], self.last_status[1]
        row = [round(now - self.sample_start, 2), rssi, sig, 1 if info["open"] else 0,
               q, s, 1 if info["decoded"] else 0, "v" if self.phase == "voice" else "m"]
        self.result["samples"].append(row)
        if info["att"]:
            self.result["att"] = True
        self.live = {"rssi": rssi, "sig": sig, "open": info["open"], "q": q, "s": s,
                     "count": len(self.result["samples"])}

    # ---- waterfall snapshot ----------------------------------------------
    def capture_snapshot(self, session_id, frames=20):
        if self.snap is not None or self.running:
            return False
        if not getattr(self.monitor, "waterfall_active", False):
            self.message.emit("Put the scanner in waterfall mode first (View → Waterfall…).")
            return False
        fields = {k: w.text() for k, w in self.monitor.wf_fields.items()}
        self.snap = {"session": session_id, "want": int(frames), "frames": [],
                     "deadline": time.monotonic() + 20, "fields": fields}
        self.monitor.update_graph_polling()
        self.changed.emit()
        return True

    def graph_frame(self, values):
        if self.snap is None or len(values) != GRAPH_BINS:
            return
        self.snap["frames"].append(list(values))
        if len(self.snap["frames"]) >= self.snap["want"]:
            self.end_snapshot(self.snap)

    def end_snapshot(self, snap, error=None):
        current = self.snap
        self.snap = None
        self.monitor.update_graph_polling()
        if snap is None or error:
            self.message.emit(error or "Waterfall snapshot cancelled.")
            self.changed.emit()
            return
        fields = current["fields"]
        stats = antenna_snapshot_stats(current["frames"])
        record = dict(stats, time=datetime.now().isoformat(timespec="seconds"),
                      frames=len(current["frames"]),
                      center=fields.get("Center", "—"), span=fields.get("Span", "—"),
                      range=fields.get("Range", "—"), gain=fields.get("Gain", "—"),
                      step=fields.get("Step", "—"))
        path = antenna_session_path(current["session"])
        try:
            session = json.loads(path.read_text(encoding="utf-8"))
            session.setdefault("snapshots", []).append(record)
            antenna_save_session(session)
        except (OSError, ValueError) as exc:
            self.message.emit(f"Couldn't save the snapshot: {exc}")
            self.changed.emit()
            return
        self.snapshot_done.emit(session)
        self.message.emit(f"Waterfall snapshot saved to {antenna_session_name(session)}: "
                          f"noise floor {record['floor']:.0f}, 90th percentile "
                          f"{record['p90']:.0f} (raw waterfall units).")
        self.changed.emit()


class GroupedBarChart(QWidget):
    """Horizontal grouped bars: one group per reference, one bar per session."""

    def __init__(self):
        super().__init__()
        self.groups, self.series, self.metric = [], [], None
        self.setMinimumHeight(220)
        self.setMouseTracking(True)
        self.bars = []

    def set_data(self, metric, series, groups):
        """series: session names; groups: [(reference name, [value or None per series])]."""
        self.metric, self.series, self.groups = metric, list(series), list(groups)
        self.setMinimumHeight(max(220, 60 + len(self.groups) * (len(self.series) * 16 + 14)))
        self.update()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, tc("#1c2530"))
        self.bars = []
        values = [v for _n, vals in self.groups for v in vals if v is not None]
        if not self.metric or not values:
            p.setPen(tc("#a5bdd2"))
            p.drawText(QRectF(0, 0, w, h), Qt.AlignmentFlag.AlignCenter,
                       "Tick two or more sessions to compare them")
            return
        label, unit, direction, _t, _r = ANTENNA_METRICS[self.metric]
        p.setPen(tc("#e9eef5"))
        p.setFont(tf("Sans", 11, QFont.Weight.Bold))
        better = "higher is better" if direction > 0 else "lower is better"
        p.drawText(QRectF(10, 4, w - 20, 20), Qt.AlignmentFlag.AlignLeft,
                   f"{label} — {better}")
        # Legend
        p.setFont(tf("Sans", 9))
        x = 10
        for i, name in enumerate(self.series):
            color = tc(ANTENNA_COLORS[i % len(ANTENNA_COLORS)])
            p.fillRect(QRectF(x, 30, 12, 12), color)
            p.setPen(tc("#c8d7e8"))
            text_w = p.fontMetrics().horizontalAdvance(name) + 22
            p.drawText(QRectF(x + 16, 26, text_w, 20), Qt.AlignmentFlag.AlignVCenter, name)
            x += text_w + 6
        low, high = min(values), max(values)
        # dBm readings are negative: start the bars a little below the weakest.
        base = min(0.0, low - max(3.0, (high - low) * 0.25)) if low < 0 else 0.0
        top = high if high > base else base + 1
        label_w = min(240, int(w * 0.32))
        bar_h = 14
        y = 54
        avail = w - label_w - 100
        for name, vals in self.groups:
            block = len(self.series) * (bar_h + 2)
            p.setPen(tc("#c8d7e8"))
            p.drawText(QRectF(6, y, label_w - 12, block),
                       Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter,
                       p.fontMetrics().elidedText(name, Qt.TextElideMode.ElideRight, label_w - 14))
            for i, value in enumerate(vals):
                by = y + i * (bar_h + 2)
                if value is None:
                    p.setPen(tc("#6c7787"))
                    p.drawText(QRectF(label_w, by, 120, bar_h), Qt.AlignmentFlag.AlignVCenter,
                               "no reading")
                    continue
                length = max(2.0, avail * (value - base) / (top - base))
                rect = QRectF(label_w, by, length, bar_h)
                p.fillRect(rect, tc(ANTENNA_COLORS[i % len(ANTENNA_COLORS)]))
                p.setPen(tc("#e9eef5"))
                p.drawText(QRectF(label_w + length + 4, by, 96, bar_h),
                           Qt.AlignmentFlag.AlignVCenter, antenna_format(self.metric, value))
                self.bars.append((QRectF(0, by, w, bar_h), f"{name} — {self.series[i]}",
                                  antenna_format(self.metric, value)))
            y += block + 14

    def mouseMoveEvent(self, event):
        for rect, label, value in self.bars:
            if rect.contains(event.position()):
                QToolTip.showText(event.globalPosition().toPoint(), f"{label}: {value}", self)
                return
        QToolTip.hideText()


class TraceChart(QWidget):
    """Overlaid waterfall snapshot traces (raw levels 0–255)."""

    def __init__(self):
        super().__init__()
        self.traces, self.range_text = [], ""
        self.setMinimumHeight(200)

    def set_data(self, traces, range_text=""):
        self.traces, self.range_text = list(traces), range_text
        self.update()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, tc("#11161d"))
        if not self.traces:
            p.setPen(tc("#a5bdd2"))
            p.drawText(QRectF(0, 0, w, h), Qt.AlignmentFlag.AlignCenter,
                       "No waterfall snapshots in the ticked sessions")
            return
        values = [v for _n, t in self.traces for v in t]
        low, high = max(0, min(values) - 5), min(255, max(values) + 5)
        if high <= low:
            high = low + 1
        left, right, top, bottom = 34, w - 8, 26, h - 20
        p.setPen(QPen(tc("#2a3a4d"), 1))
        for frac in (0.25, 0.5, 0.75):
            yy = bottom - (bottom - top) * frac
            p.drawLine(QPointF(left, yy), QPointF(right, yy))
        p.setFont(tf("Sans", 8))
        p.setPen(tc("#8fa3b8"))
        p.drawText(QRectF(0, top - 6, left - 4, 12), Qt.AlignmentFlag.AlignRight, f"{high:.0f}")
        p.drawText(QRectF(0, bottom - 6, left - 4, 12), Qt.AlignmentFlag.AlignRight, f"{low:.0f}")
        p.drawText(QRectF(left, bottom + 2, right - left, 16), Qt.AlignmentFlag.AlignCenter,
                   self.range_text)
        x = left
        for i, (name, trace) in enumerate(self.traces):
            color = tc(ANTENNA_COLORS[i % len(ANTENNA_COLORS)])
            p.setPen(QPen(color, 1.6))
            n = len(trace)
            points = [QPointF(left + (right - left) * j / max(1, n - 1),
                              bottom - (bottom - top) * (v - low) / (high - low))
                      for j, v in enumerate(trace)]
            p.drawPolyline(QPolygonF(points))
            p.fillRect(QRectF(x, 8, 12, 10), color)
            p.setPen(tc("#c8d7e8"))
            tw = p.fontMetrics().horizontalAdvance(name) + 20
            p.drawText(QRectF(x + 15, 4, tw, 16), Qt.AlignmentFlag.AlignVCenter, name)
            x += tw + 8


class AntennaRefDialog(QDialog):
    """Add or edit one reference signal."""

    def __init__(self, parent, ref=None):
        super().__init__(parent)
        self.setWindowTitle("Reference signal")
        self.ref = dict(ref or {"kind": "continuous", "enabled": True})
        form = QFormLayout(self)
        self.name = QLineEdit(self.ref.get("name", ""))
        self.name.setPlaceholderText("e.g. NOAA Greenville, Palmetto 800 Greenville simulcast")
        form.addRow("Name", self.name)
        self.kind = QComboBox()
        for kind in ANTENNA_KIND_ORDER:
            self.kind.addItem(ANTENNA_KINDS[kind][0], kind)
        self.kind.setCurrentIndex(max(0, ANTENNA_KIND_ORDER.index(self.ref.get("kind", "continuous"))))
        form.addRow("Type", self.kind)
        self.description = QLabel()
        self.description.setWordWrap(True)
        set_css(self.description, "color:#a5bdd2;")
        form.addRow(self.description)
        self.freq = QLineEdit(f"{self.ref['mhz']:.4f}" if self.ref.get("mhz") else "")
        self.freq.setPlaceholderText("MHz, e.g. 162.5500")
        self.freq_label = make_label("Frequency")
        form.addRow(self.freq_label, self.freq)
        self.site_index = QLineEdit(str(self.ref.get("site_index", "")))
        self.site_index.setPlaceholderText("Use ADD CURRENT SITE while the scanner is on the site")
        self.site_label = make_label("Site index")
        form.addRow(self.site_label, self.site_index)
        self.seconds = QSpinBox()
        self.seconds.setRange(20, 7200)
        self.seconds.setSingleStep(30)
        self.seconds.setSuffix(" s")
        self.seconds.setValue(int(self.ref.get("seconds") or ANTENNA_KINDS[self.ref["kind"]][1]))
        form.addRow("Sample time", self.seconds)
        self.voice = QSpinBox()
        self.voice.setRange(0, 3600)
        self.voice.setSingleStep(60)
        self.voice.setSuffix(" s")
        self.voice.setSpecialValueText("Off")
        self.voice.setValue(int(self.ref.get("voice_seconds") or 0))
        self.voice.setToolTip("After System Status, hold the site this long and count voice calls "
                              "and how many were decoded. Traffic varies, so treat it as "
                              "supporting evidence.")
        self.voice_label = make_label("Voice window")
        form.addRow(self.voice_label, self.voice)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok
                                   | QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(self.check)
        buttons.rejected.connect(self.reject)
        form.addRow(buttons)
        self.kind.currentIndexChanged.connect(self.kind_changed)
        self.kind_changed(initial=True)

    def current_kind(self):
        return ANTENNA_KIND_ORDER[max(0, self.kind.currentIndex())]

    def kind_changed(self, _index=None, initial=False):
        kind = self.current_kind()
        site = kind == "site"
        for widget in (self.freq, self.freq_label):
            widget.setVisible(not site)
        for widget in (self.site_index, self.site_label, self.voice, self.voice_label):
            widget.setVisible(site)
        set_text(self.description, ANTENNA_KINDS[kind][2])
        if not initial:
            self.seconds.setValue(ANTENNA_KINDS[kind][1])

    def check(self):
        kind = self.current_kind()
        ref = dict(self.ref, kind=kind, name=self.name.text().strip(),
                   seconds=self.seconds.value())
        if kind == "site":
            index = self.site_index.text().strip()
            if not index.isdigit():
                QMessageBox.warning(self, "Reference signal",
                                    "Enter the site index (a number). The easiest way is "
                                    "ADD CURRENT SITE while the scanner is on that site.")
                return
            ref["site_index"] = index
            ref["voice_seconds"] = self.voice.value()
            ref.pop("mhz", None)
        else:
            try:
                ref["mhz"] = Monitor.validate_mhz(self.freq.text())
            except ValueError as exc:
                QMessageBox.warning(self, "Reference signal", str(exc))
                return
            ref.pop("voice_seconds", None)
        if not ref["name"]:
            ref["name"] = antenna_ref_target(ref)
        self.ref = ref
        self.accept()


class AntennaTestWindow(QWidget):
    """Tools → Antenna Test…: references, runs and comparison."""

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.tester = monitor.antenna_test
        analysis_window(self, monitor, "Antenna Test", "antenna/geometry", (1180, 820))
        self.refs = antenna_load_refs()
        self.sessions = []
        layout = QVBoxLayout(self)
        intro = make_label("Compare antennas, mounts or positions on the same signals. Readings "
                       "are not calibrated, so compare runs made with the same scanner, coax "
                       "and place, close together in time.")
        intro.setWordWrap(True)
        set_css(intro, "color:#a5bdd2;")
        layout.addWidget(intro)
        self.tabs = QTabWidget()
        self.tabs.addTab(self.build_refs_tab(), "References")
        self.tabs.addTab(self.build_run_tab(), "Run")
        self.tabs.addTab(self.build_compare_tab(), "Compare")
        layout.addWidget(self.tabs, 1)
        self.feedback = make_label("")
        self.feedback.setWordWrap(True)
        layout.addWidget(self.feedback)
        self.tester.changed.connect(self.update_run)
        self.tester.result_done.connect(self.result_done)
        self.tester.finished.connect(self.run_finished)
        self.tester.snapshot_done.connect(lambda _s: self.load_sessions())
        self.tester.message.connect(self.say)
        self.fill_refs()
        self.load_sessions()
        self.update_run()
        # Waterfall state and snapshot progress change outside a run too.
        self.idle_timer = QTimer(self)
        self.idle_timer.timeout.connect(
            lambda: self.update_run() if self.isVisible() and not self.tester.running else None)
        self.idle_timer.start(1000)

    # ---- helpers ---------------------------------------------------------
    def open(self):
        restore_window(self, self.monitor)
        self.update_run()

    def save_settings(self, settings):
        if self.geometry_restored:
            settings.setValue(self.geometry_key, self.saveGeometry())

    def say(self, text, tone=None):
        colors = {"ok": "#7ee3a5", "bad": "#ff9e91"}
        set_text(self.feedback, text)
        set_css(self.feedback, f"color:{colors.get(tone, '#c9d6e6')};")

    @staticmethod
    def button(label, tip, slot, color="#344d71"):
        b = QPushButton(label)
        b.setToolTip(tip)
        b.setMinimumHeight(34)
        set_css(b, f"QPushButton {{background:{color}; color:white; font-weight:700;"
            " border-radius:6px; padding:6px 12px;}"
            "QPushButton:hover {border:2px solid #dceeff;}"
            "QPushButton:disabled {background:#414750;color:#9ca4b0;}")
        b.clicked.connect(lambda checked=False: slot())
        return b

    # ---- references --------------------------------------------------------
    def build_refs_tab(self):
        tab = QWidget()
        v = QVBoxLayout(tab)
        note = make_label("Ticked references are measured in this order on every run. Include "
                      "weak and medium signals, not only strong ones: strong signals max out "
                      "the reading and hide differences.")
        note.setWordWrap(True)
        set_css(note, "color:#a5bdd2;")
        v.addWidget(note)
        self.ref_table = QTableWidget(0, 6)
        self.ref_table.setHorizontalHeaderLabels(
            ["Use", "Name", "Type", "Frequency / site", "Band", "Time"])
        self.ref_table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        self.ref_table.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.ref_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.ref_table.setAlternatingRowColors(True)
        self.ref_table.horizontalHeader().setStretchLastSection(True)
        self.ref_table.setColumnWidth(0, 46)
        self.ref_table.setColumnWidth(1, 300)
        self.ref_table.setColumnWidth(2, 250)
        self.ref_table.setColumnWidth(3, 230)
        self.ref_table.itemChanged.connect(self.ref_item_changed)
        self.ref_table.cellDoubleClicked.connect(lambda row, _c: self.edit_ref(row))
        v.addWidget(self.ref_table, 1)
        row1 = QHBoxLayout()
        row1.addWidget(self.button("ADD CURRENT SITE", "Add the trunked site the scanner is on "
                                   "now (scan or hold on it first)", self.add_current_site,
                                   "#1b8a5a"))
        row1.addWidget(self.button("ADD CURRENT FREQUENCY", "Add the frequency the scanner is "
                                   "on now (NOAA or a DMR repeater, for example)",
                                   self.add_current_freq, "#1b8a5a"))
        row1.addWidget(self.button("ADD NOAA…", "Add a NOAA weather radio frequency",
                                   self.add_noaa))
        row1.addWidget(self.button("ADD…", "Add any reference by hand", self.add_ref))
        row1.addStretch(1)
        v.addLayout(row1)
        row2 = QHBoxLayout()
        row2.addWidget(self.button("EDIT…", "Edit the selected reference",
                                   lambda: self.edit_ref(self.ref_table.currentRow())))
        row2.addWidget(self.button("▲ UP", "Measure earlier", lambda: self.move_ref(-1)))
        row2.addWidget(self.button("▼ DOWN", "Measure later", lambda: self.move_ref(1)))
        row2.addWidget(self.button("REMOVE", "Remove the selected reference", self.remove_ref,
                                   "#8a3b3b"))
        row2.addStretch(1)
        self.estimate_label = make_label("")
        set_css(self.estimate_label, "font-weight:650;")
        row2.addWidget(self.estimate_label)
        v.addLayout(row2)
        return tab

    def fill_refs(self):
        table = self.ref_table
        table.blockSignals(True)
        table.setRowCount(len(self.refs))
        for r, ref in enumerate(self.refs):
            use = QTableWidgetItem()
            use.setFlags(Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled
                         | Qt.ItemFlag.ItemIsSelectable)
            use.setCheckState(Qt.CheckState.Checked if ref.get("enabled", True)
                              else Qt.CheckState.Unchecked)
            table.setItem(r, 0, use)
            seconds, voice = antenna_ref_seconds(ref)
            time_text = antenna_duration_text(seconds) + (
                f" + {antenna_duration_text(voice)} voice" if voice else "")
            band = ref.get("band") if ref["kind"] == "site" else antenna_band(ref.get("mhz"))
            for c, text in enumerate((ref.get("name") or antenna_ref_target(ref),
                                      ANTENNA_KINDS[ref["kind"]][0], antenna_ref_target(ref),
                                      band or "—", time_text), start=1):
                table.setItem(r, c, QTableWidgetItem(text))
        table.blockSignals(False)
        enabled = self.enabled_refs()
        set_text(self.estimate_label, f"{len(enabled)} of {len(self.refs)} ticked • about "
            f"{antenna_duration_text(antenna_estimate_s(enabled))} per run")
        if hasattr(self, "run_estimate"):
            self.update_run()

    def enabled_refs(self):
        return [r for r in self.refs if r.get("enabled", True)]

    def save_refs(self):
        try:
            antenna_save_refs(self.refs)
        except OSError as exc:
            self.say(f"Couldn't save the references: {exc}", "bad")
        self.fill_refs()

    def ref_item_changed(self, item):
        if item.column() == 0 and 0 <= item.row() < len(self.refs):
            self.refs[item.row()]["enabled"] = item.checkState() == Qt.CheckState.Checked
            self.save_refs()

    def new_id(self):
        used = {r.get("id") for r in self.refs}
        n = len(self.refs) + 1
        while f"r{n}" in used:
            n += 1
        return f"r{n}"

    def add(self, ref):
        key = antenna_ref_key(ref)
        if any(antenna_ref_key(r) == key for r in self.refs):
            self.say(f"{antenna_ref_target(ref)} is already in the list.", "bad")
            return
        ref["id"] = self.new_id()
        ref.setdefault("enabled", True)
        self.refs.append(ref)
        self.save_refs()
        self.ref_table.selectRow(len(self.refs) - 1)
        self.say(f"Added {ref['name']}.", "ok")

    def add_ref(self):
        dialog = AntennaRefDialog(self)
        if dialog.exec():
            self.add(dialog.ref)

    def edit_ref(self, row):
        if not 0 <= row < len(self.refs):
            return
        dialog = AntennaRefDialog(self, self.refs[row])
        if dialog.exec():
            self.refs[row] = dialog.ref
            self.save_refs()
            self.ref_table.selectRow(row)

    def move_ref(self, step):
        row = self.ref_table.currentRow()
        new = row + step
        if 0 <= row < len(self.refs) and 0 <= new < len(self.refs):
            self.refs[row], self.refs[new] = self.refs[new], self.refs[row]
            self.save_refs()
            self.ref_table.selectRow(new)

    def remove_ref(self):
        row = self.ref_table.currentRow()
        if 0 <= row < len(self.refs):
            ref = self.refs[row]
            if QMessageBox.question(self, "Remove reference",
                                    f"Remove {ref.get('name')}?\n\nSaved sessions keep "
                                    "their readings.") == QMessageBox.StandardButton.Yes:
                del self.refs[row]
                self.save_refs()

    def add_current_site(self):
        info = self.tester.last_gsi
        if not self.monitor.connected or not info:
            self.say("Connect to the scanner and let it reach the site first.", "bad")
            return
        index = info.get("site_index", "")
        if not index.isdigit():
            self.say("The scanner isn't on a trunked site right now. Scan or hold on the "
                     "Greenville simulcast site, then try again.", "bad")
            return
        name = " — ".join(x for x in (info.get("system"), info.get("site_name")) if x)
        ref = {"kind": "site", "name": name or f"Site {index}", "site_index": index,
               "site_name": info.get("site_name", ""), "system": info.get("system", ""),
               "band": antenna_band(info.get("site_mhz")) if info.get("site_mhz") else "",
               "seconds": ANTENNA_KINDS["site"][1], "voice_seconds": 0}
        dialog = AntennaRefDialog(self, ref)
        if dialog.exec():
            dialog.ref.update({k: ref[k] for k in ("site_name", "system", "band")})
            self.add(dialog.ref)

    def add_current_freq(self):
        info = self.tester.last_gsi
        mhz = info.get("mhz") if info else None
        if not self.monitor.connected or mhz is None:
            self.say("The scanner isn't reporting a frequency. Hold on the channel first.", "bad")
            return
        channel = self.monitor.fields["Channel"].text() if "Channel" in self.monitor.fields else ""
        mod = (info.get("mod") or "").upper()
        kind = antenna_default_kind(mhz)
        name = channel if channel not in ("", "—") else f"{mhz:.4f} MHz"
        if mod:
            name += f" ({mod})"
        ref = {"kind": kind, "name": name, "mhz": mhz, "seconds": ANTENNA_KINDS[kind][1]}
        dialog = AntennaRefDialog(self, ref)
        if dialog.exec():
            self.add(dialog.ref)

    def add_noaa(self):
        items = [f"{f:.3f} MHz" for f in NOAA_FREQS]
        choice, ok = QInputDialog.getItem(
            self, "Add NOAA", "NOAA frequency (use the one your weather radio or the "
            "scanner's Weather scan picks up):", items, 0, False)
        if ok:
            mhz = NOAA_FREQS[items.index(choice)]
            self.add({"kind": "continuous", "name": f"NOAA {mhz:.3f}", "mhz": mhz,
                      "seconds": ANTENNA_KINDS["continuous"][1]})

    # ---- run ---------------------------------------------------------------
    def build_run_tab(self):
        tab = QWidget()
        v = QVBoxLayout(tab)
        form = QFormLayout()
        self.label_box = QComboBox()
        self.label_box.setEditable(True)
        self.label_box.lineEdit().setPlaceholderText("e.g. Antenna A, Stock antenna, Roof mount 20 ft")
        form.addRow("Label", self.label_box)
        self.notes = QLineEdit()
        self.notes.setPlaceholderText("Antenna, height, coax, location: anything that differs "
                                      "between runs")
        form.addRow("Notes", self.notes)
        self.resume_box = QCheckBox("Return the scanner to scanning when the run ends")
        self.resume_box.setChecked(
            str(self.monitor.settings.value("antenna/resume", "true")).lower() == "true")
        self.resume_box.toggled.connect(
            lambda on: self.monitor.settings.setValue("antenna/resume", on))
        form.addRow("", self.resume_box)
        v.addLayout(form)
        tips = make_label(
            "<b>For a fair comparison:</b> attenuator off • same coax, adapters and spot • "
            "don't touch the scanner during a run • run each antenna back to back • "
            "<b>finish by running the first antenna again with the same label</b>: the "
            "Compare tab uses the difference between those two runs to tell real "
            "differences from conditions drifting.")
        tips.setWordWrap(True)
        tips.setTextFormat(Qt.TextFormat.RichText)
        set_css(tips, "color:#a5bdd2;")
        v.addWidget(tips)
        buttons = QHBoxLayout()
        self.start_btn = self.button("▶ START RUN", "Measure every ticked reference in order",
                                     self.start_run, "#1b8a5a")
        self.stop_btn = self.button("■ STOP", "Stop now; readings so far are kept",
                                    self.tester.stop, "#bd6b23")
        self.skip_btn = self.button("SKIP ▶▶", "Keep what this reference has so far and move on",
                                    self.skip_ref)
        for b in (self.start_btn, self.stop_btn, self.skip_btn):
            buttons.addWidget(b)
        buttons.addStretch(1)
        self.run_estimate = make_label("")
        buttons.addWidget(self.run_estimate)
        v.addLayout(buttons)
        self.run_label = make_label("Not running")
        set_css(self.run_label, "font-size:17px;font-weight:700;color:#e6a65a;")
        v.addWidget(self.run_label)
        self.overall_bar = QProgressBar()
        self.overall_bar.setRange(0, 1000)
        self.overall_bar.setFormat("Run %p%")
        v.addWidget(self.overall_bar)
        self.step_bar = QProgressBar()
        self.step_bar.setRange(0, 1000)
        self.step_bar.setFormat("")
        v.addWidget(self.step_bar)
        self.live_label = make_label("")
        set_css(self.live_label, "font-size:15px;font-weight:650;")
        v.addWidget(self.live_label)
        self.run_table = QTableWidget(0, 4)
        self.run_table.setHorizontalHeaderLabels(["Reference", "Status", "Readings", "Result"])
        self.run_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.run_table.setAlternatingRowColors(True)
        self.run_table.setColumnWidth(0, 300)
        self.run_table.setColumnWidth(1, 120)
        self.run_table.setColumnWidth(2, 80)
        stretch_last(self.run_table)
        v.addWidget(self.run_table, 1)
        snap = QGroupBox("Waterfall noise-floor snapshot")
        sv = QVBoxLayout(snap)
        help_text = make_label(
            "Shows the whole band at once: a raised floor with no more signal means the "
            "antenna (or its location) is picking up noise. Put the scanner in waterfall mode "
            "first (View → Waterfall…), and use the same center, span and RF gain for every "
            "antenna. Levels are the scanner's raw waterfall units, not dBm.")
        help_text.setWordWrap(True)
        set_css(help_text, "color:#a5bdd2;")
        sv.addWidget(help_text)
        sh = QHBoxLayout()
        self.snap_state = make_label("")
        sh.addWidget(self.snap_state, 1)
        sh.addWidget(make_label("Frames"))
        self.snap_frames = QSpinBox()
        self.snap_frames.setRange(5, 200)
        self.snap_frames.setValue(20)
        sh.addWidget(self.snap_frames)
        sh.addWidget(make_label("Add to"))
        self.snap_session = QComboBox()
        self.snap_session.setMinimumWidth(260)
        sh.addWidget(self.snap_session)
        self.snap_btn = self.button("CAPTURE SNAPSHOT", "Average the waterfall over the frames "
                                    "and add it to the chosen session", self.capture_snapshot)
        sh.addWidget(self.snap_btn)
        sv.addLayout(sh)
        v.addWidget(snap)
        return tab

    def start_run(self):
        refs = self.enabled_refs()
        if not refs:
            self.say("Tick at least one reference on the References tab.", "bad")
            return
        label = self.label_box.currentText().strip()
        if not label:
            self.say("Give the run a label (for example “Antenna A”) so it can be compared.",
                     "bad")
            return
        if self.tester.start(refs, label, self.notes.text(), self.resume_box.isChecked()):
            self.run_table.setRowCount(0)
            self.say(f"Running “{label}”: {len(refs)} references, about "
                     f"{antenna_duration_text(antenna_estimate_s(refs))}.", "ok")
        self.update_run()

    def skip_ref(self):
        t = self.tester
        if t.running and t.result is not None:
            t.result["status"] = "ok" if t.result["samples"] else "skipped"
            t.result["message"] = "Skipped early"
            t.next_ref()

    def update_run(self):
        t = self.tester
        running = t.running
        connected = self.monitor.connected
        self.start_btn.setEnabled(connected and not running and not t.capturing)
        self.stop_btn.setEnabled(running)
        self.skip_btn.setEnabled(running and t.phase in ("sample", "voice", "tune", "settle"))
        self.label_box.setEnabled(not running)
        self.notes.setEnabled(not running)
        enabled = self.enabled_refs()
        set_text(self.run_estimate, f"{len(enabled)} references • about "
                                  f"{antenna_duration_text(antenna_estimate_s(enabled))}")
        overall, step, text = t.progress()
        self.overall_bar.setValue(int(overall * 1000))
        self.step_bar.setValue(int(step * 1000))
        self.step_bar.setFormat(text)
        ref = t.current_ref()
        if running and ref is not None:
            set_text(self.run_label, f"{t.session['label']} — {t.index + 1} of {len(t.plan)}: "
                                   f"{ref.get('name')}")
            set_css(self.run_label, "font-size:17px;font-weight:700;color:#52dc95;")
            live = t.live
            parts = []
            if live.get("q") is not None:
                parts.append(f"Q {live['q']}")
            if live.get("s") is not None:
                parts.append(f"S {live['s']}")
            if live.get("rssi") is not None:
                parts.append(f"RSSI {live['rssi']} dBm")
            if live.get("sig") is not None:
                parts.append(f"bars {live['sig']}/4")
            if live:
                parts.append("signal present" if live.get("open") else "squelch closed")
                parts.append(f"{live.get('count', 0)} readings")
            set_text(self.live_label, "   •   ".join(parts) if parts else "Waiting for readings…")
            self.show_partial(ref)
        else:
            set_text(self.run_label, "Not running" if connected else "Not running — connect "
                                   "to the scanner first")
            set_css(self.run_label, "font-size:17px;font-weight:700;color:#e6a65a;")
            set_text(self.live_label, "")
        wf = getattr(self.monitor, "waterfall_active", False)
        if t.capturing:
            set_text(self.snap_state, f"Capturing… {len(t.snap['frames'])} of {t.snap['want']} frames")
        elif wf:
            f = self.monitor.wf_fields
            set_text(self.snap_state, f"Waterfall active: center {f['Center'].text()} • span "
                                    f"{f['Span'].text()} • gain {f['Gain'].text()}")
        else:
            set_text(self.snap_state, "Waterfall mode not detected")
        self.snap_btn.setEnabled(connected and wf and not running and not t.capturing
                                 and self.snap_session.count() > 0)

    def result_text(self, result, poll_s):
        metrics = antenna_summary(result, poll_s)
        keys = ANTENNA_KIND_METRICS.get(result.get("kind"), ())
        parts = [f"{ANTENNA_METRICS[k][0].split(' (')[0]} {antenna_format(k, metrics[k])}"
                 for k in keys if k in metrics]
        notes = antenna_result_notes(result, metrics)
        return " • ".join(parts + notes) or "No readings"

    def set_run_row(self, row, result, poll_s):
        if row >= self.run_table.rowCount():
            self.run_table.setRowCount(row + 1)
        status = result.get("status", "")
        values = (result["ref"].get("name") or antenna_ref_target(result["ref"]), status,
                  str(len(result.get("samples") or [])), self.result_text(result, poll_s))
        color = ("#7ee3a5" if status == "ok" else "#e6a65a" if status in ("running", "stopped")
                 else "#ff9e91")
        for c, text in enumerate(values):
            item = QTableWidgetItem(text)
            if c == 1:
                item.setForeground(tc(color))
            self.run_table.setItem(row, c, item)

    def show_partial(self, ref):
        t = self.tester
        if t.result is not None:
            self.set_run_row(t.index, t.result, t.poll_s())

    def result_done(self, result):
        session = self.tester.session
        if session is not None:
            self.set_run_row(len(session["results"]) - 1, result, session.get("poll_s", 0.5))

    def run_finished(self, session):
        for i, result in enumerate(session.get("results", [])):
            self.set_run_row(i, result, session.get("poll_s", 0.5))
        self.load_sessions(select=session["id"])
        stopped = session.get("stopped")
        ok = sum(1 for r in session.get("results", []) if r.get("status") == "ok")
        labels = {(s.get("label") or "").casefold() for s in self.sessions}
        tip = ""
        if len(self.sessions) >= 2 and len(labels) < len(self.sessions):
            tip = " A repeated label is in the list, so Compare can check for drift."
        elif len(self.sessions) >= 2:
            tip = (" Tip: when you've tried every antenna, swap the first one back and run it "
                   "again with the same label.")
        self.say(("Run stopped" if stopped else "Run finished") +
                 f": {ok} of {len(session.get('results', []))} references measured and saved."
                 + tip, "bad" if stopped else "ok")
        self.update_run()

    def capture_snapshot(self):
        session_id = self.snap_session.currentData()
        if session_id and self.tester.capture_snapshot(session_id, self.snap_frames.value()):
            self.say("Capturing the waterfall…")
        self.update_run()

    # ---- compare -----------------------------------------------------------
    def build_compare_tab(self):
        tab = QWidget()
        outer = QHBoxLayout(tab)
        splitter = QSplitter(Qt.Orientation.Horizontal)
        left = QWidget()
        lv = QVBoxLayout(left)
        lv.setContentsMargins(0, 0, 0, 0)
        lv.addWidget(make_label("Sessions (tick the ones to compare)"))
        self.session_list = QListWidget()
        self.session_list.itemChanged.connect(lambda _i: self.refresh_compare())
        lv.addWidget(self.session_list, 1)
        grid = QGridLayout()
        grid.addWidget(self.button("RENAME…", "Change the selected session's label and notes",
                                   self.rename_session), 0, 0)
        grid.addWidget(self.button("DELETE…", "Delete the selected session", self.delete_session,
                                   "#8a3b3b"), 0, 1)
        grid.addWidget(self.button("EXPORT SUMMARY…", "One CSV row per session and reference "
                                   "(ticked sessions)", self.export_summary), 1, 0)
        grid.addWidget(self.button("EXPORT READINGS…", "Every reading of the ticked sessions",
                                   self.export_samples), 1, 1)
        grid.addWidget(self.button("OPEN FOLDER", "Where antenna tests are saved",
                                   lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(
                                       str(ANTENNA_DIR)))), 2, 0)
        grid.addWidget(self.button("RELOAD", "Read the saved sessions again",
                                   self.load_sessions), 2, 1)
        lv.addLayout(grid)
        splitter.addWidget(left)
        right_split = QSplitter(Qt.Orientation.Vertical)
        top = QWidget()
        tv = QVBoxLayout(top)
        tv.setContentsMargins(0, 0, 0, 0)
        self.compare_table = QTableWidget(0, 3)
        self.compare_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.compare_table.setAlternatingRowColors(True)
        self.compare_table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        self.compare_table.itemSelectionChanged.connect(self.compare_row_selected)
        tv.addWidget(self.compare_table, 1)
        self.compare_note = make_label("")
        self.compare_note.setWordWrap(True)
        set_css(self.compare_note, "color:#a5bdd2;")
        tv.addWidget(self.compare_note)
        right_split.addWidget(top)
        chart_box = QWidget()
        cv = QVBoxLayout(chart_box)
        cv.setContentsMargins(0, 0, 0, 0)
        ch = QHBoxLayout()
        ch.addWidget(make_label("Chart"))
        self.metric_choice = QComboBox()
        self.metric_choice.currentIndexChanged.connect(self.draw_chart)
        ch.addWidget(self.metric_choice, 1)
        cv.addLayout(ch)
        self.chart = GroupedBarChart()
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setWidget(self.chart)
        cv.addWidget(scroll, 1)
        right_split.addWidget(chart_box)
        snaps = QWidget()
        nv = QVBoxLayout(snaps)
        nv.setContentsMargins(0, 0, 0, 0)
        nh = QHBoxLayout()
        nh.addWidget(make_label("Waterfall snapshots"))
        self.snap_choice = QComboBox()
        self.snap_choice.currentIndexChanged.connect(self.draw_traces)
        nh.addWidget(self.snap_choice, 1)
        nv.addLayout(nh)
        self.snap_table = QTableWidget(0, 7)
        self.snap_table.setHorizontalHeaderLabels(
            ["Session", "Center", "Span", "RF gain", "Noise floor", "90th percentile", "Peak"])
        self.snap_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.snap_table.setMaximumHeight(130)
        stretch_last(self.snap_table)
        nv.addWidget(self.snap_table)
        self.trace_chart = TraceChart()
        nv.addWidget(self.trace_chart, 1)
        right_split.addWidget(snaps)
        right_split.setStretchFactor(0, 3)
        right_split.setStretchFactor(1, 3)
        right_split.setStretchFactor(2, 2)
        splitter.addWidget(right_split)
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 4)
        outer.addWidget(splitter)
        return tab

    def load_sessions(self, select=None):
        checked = set(self.checked_ids()) if self.session_list.count() else set()
        if select:
            checked.add(select)
        self.sessions = antenna_load_sessions()
        self.session_list.blockSignals(True)
        self.session_list.clear()
        for session in reversed(self.sessions):
            ok = sum(1 for r in session.get("results", []) if r.get("status") == "ok")
            text = antenna_session_name(session) + f" — {ok} measured"
            if session.get("snapshots"):
                text += f", {len(session['snapshots'])} snapshot(s)"
            if session.get("notes"):
                text += f"\n    {session['notes']}"
            item = QListWidgetItem(text)
            item.setData(Qt.ItemDataRole.UserRole, session["id"])
            item.setFlags(item.flags() | Qt.ItemFlag.ItemIsUserCheckable)
            item.setCheckState(Qt.CheckState.Checked if session["id"] in checked
                               else Qt.CheckState.Unchecked)
            self.session_list.addItem(item)
        self.session_list.blockSignals(False)
        current = self.snap_session.currentData()
        self.snap_session.clear()
        for session in reversed(self.sessions):
            self.snap_session.addItem(antenna_session_name(session), session["id"])
        if current:
            i = self.snap_session.findData(current)
            if i >= 0:
                self.snap_session.setCurrentIndex(i)
        labels = []
        for session in reversed(self.sessions):
            label = session.get("label") or ""
            if label and label not in labels:
                labels.append(label)
        text = self.label_box.currentText()
        self.label_box.clear()
        self.label_box.addItems(labels)
        self.label_box.setCurrentText(text)
        self.refresh_compare()
        self.update_run()

    def checked_ids(self):
        ids = []
        for i in range(self.session_list.count()):
            item = self.session_list.item(i)
            if item.checkState() == Qt.CheckState.Checked:
                ids.append(item.data(Qt.ItemDataRole.UserRole))
        return ids

    def checked_sessions(self):
        ids = set(self.checked_ids())
        return [s for s in self.sessions if s["id"] in ids]

    def selected_session(self):
        item = self.session_list.currentItem()
        if item is None:
            return None
        sid = item.data(Qt.ItemDataRole.UserRole)
        return next((s for s in self.sessions if s["id"] == sid), None)

    def refresh_compare(self):
        sessions = sorted(self.checked_sessions(), key=lambda s: s.get("started", ""))
        self.compare_sessions = sessions
        rows, drift = antenna_compare(sessions) if sessions else ([], {})
        self.compare_rows = rows
        table = self.compare_table
        headers = ["Reference", "Measure"] + [antenna_session_name(s) for s in sessions] + ["Best"]
        table.setColumnCount(len(headers))
        table.setHorizontalHeaderLabels(headers)
        table.setRowCount(len(rows))
        last_name = None
        for r, row in enumerate(rows):
            name = row["name"] if row["name"] != last_name else ""
            last_name = row["name"]
            metric = row["metric"]
            direction = ANTENNA_METRICS[metric][2]
            cells = [name, ANTENNA_METRICS[metric][0] + (" ↓" if direction < 0 else "")]
            base_i = next((i for i, v in enumerate(row["values"]) if v is not None), None)
            for i, value in enumerate(row["values"]):
                text = antenna_format(metric, value)
                if value is not None and base_i is not None and i != base_i:
                    text += f"  ({antenna_delta_text(metric, value - row['values'][base_i])})"
                cells.append(text)
            cells.append(row["verdict"])
            for c, text in enumerate(cells):
                item = QTableWidgetItem(text)
                if c == 0:
                    item.setFont(tf("Sans", 10, QFont.Weight.Bold))
                session_col = c - 2
                if row["best"] is not None and session_col == row["best"]:
                    item.setForeground(tc("#7ee3a5"))
                    item.setFont(tf("Sans", 10, QFont.Weight.Bold))
                if c == len(cells) - 1 and row["best"] is None and text.startswith("≈"):
                    item.setForeground(tc("#e6a65a"))
                table.setItem(r, c, item)
        table.resizeColumnsToContents()
        notes = []
        if len(sessions) < 2:
            notes.append("Tick two or more sessions to compare them.")
        else:
            notes.append("Differences are measured against the first (oldest) ticked session. "
                         "↓ marks measures where lower is better. A result counts only when "
                         "it beats the next session by more than about 2 dB (RSSI), 5 points "
                         "(Q/S) or 20% (counts).")
            if drift:
                rssi = [v for (k, m), v in drift.items() if m in ("rssi_med", "noise_med")]
                quality = [v for (k, m), v in drift.items() if m == "q_med"]
                parts = []
                if rssi:
                    parts.append(f"RSSI moved up to {max(rssi):.1f} dB")
                if quality:
                    parts.append(f"Q moved up to {max(quality):.0f} points")
                notes.append("Drift check (same label run more than once): "
                             + (", ".join(parts) if parts else "readings moved")
                             + " on their own; differences smaller than that aren't counted.")
            else:
                notes.append("No drift check yet: run the first antenna again with the same "
                             "label to see how much readings move on their own.")
        set_text(self.compare_note, " ".join(notes))
        current = self.metric_choice.currentData()
        metrics = []
        for row in rows:
            if row["metric"] not in metrics:
                metrics.append(row["metric"])
        self.metric_choice.blockSignals(True)
        self.metric_choice.clear()
        for metric in metrics:
            self.metric_choice.addItem(ANTENNA_METRICS[metric][0], metric)
        i = self.metric_choice.findData(current) if current else -1
        self.metric_choice.setCurrentIndex(i if i >= 0 else 0)
        self.metric_choice.blockSignals(False)
        self.draw_chart()
        self.fill_snapshots(sessions)

    def compare_row_selected(self):
        r = self.compare_table.currentRow()
        if 0 <= r < len(getattr(self, "compare_rows", [])):
            i = self.metric_choice.findData(self.compare_rows[r]["metric"])
            if i >= 0:
                self.metric_choice.setCurrentIndex(i)

    def draw_chart(self, *_):
        metric = self.metric_choice.currentData()
        sessions = getattr(self, "compare_sessions", [])
        groups = [(row["name"], row["values"]) for row in getattr(self, "compare_rows", [])
                  if row["metric"] == metric]
        self.chart.set_data(metric, [antenna_session_name(s) for s in sessions], groups)

    def fill_snapshots(self, sessions):
        snaps = [(s, snap) for s in sessions for snap in s.get("snapshots", [])]
        self.snapshot_rows = snaps
        table = self.snap_table
        table.setRowCount(len(snaps))
        for r, (session, snap) in enumerate(snaps):
            values = (antenna_session_name(session), snap.get("center", "—"),
                      snap.get("span", "—"), snap.get("gain", "—"),
                      f"{snap.get('floor', 0):.0f}", f"{snap.get('p90', 0):.0f}",
                      f"{snap.get('peak', 0):.0f}")
            for c, text in enumerate(values):
                table.setItem(r, c, QTableWidgetItem(str(text)))
        centers = []
        for _s, snap in snaps:
            key = (snap.get("center", "—"), snap.get("span", "—"))
            if key not in centers:
                centers.append(key)
        current = self.snap_choice.currentData()
        self.snap_choice.blockSignals(True)
        self.snap_choice.clear()
        for center, span in centers:
            self.snap_choice.addItem(f"Center {center} • span {span}", [center, span])
        i = self.snap_choice.findData(current) if current else -1
        self.snap_choice.setCurrentIndex(i if i >= 0 else 0)
        self.snap_choice.blockSignals(False)
        self.draw_traces()

    def draw_traces(self, *_):
        choice = self.snap_choice.currentData()
        traces = []
        range_text = ""
        for session, snap in getattr(self, "snapshot_rows", []):
            if choice and [snap.get("center", "—"), snap.get("span", "—")] == list(choice):
                traces.append((antenna_session_name(session), snap.get("trace", [])))
                range_text = snap.get("range", "")
        self.trace_chart.set_data([t for t in traces if t[1]], range_text)

    def rename_session(self):
        session = self.selected_session()
        if session is None:
            self.say("Select a session first.", "bad")
            return
        label, ok = QInputDialog.getText(self, "Rename session", "Label:",
                                         text=session.get("label", ""))
        if not ok:
            return
        notes, ok = QInputDialog.getText(self, "Rename session", "Notes:",
                                         text=session.get("notes", ""))
        if not ok:
            return
        session["label"], session["notes"] = label.strip(), notes.strip()
        try:
            antenna_save_session(session)
        except OSError as exc:
            self.say(f"Couldn't save: {exc}", "bad")
        self.load_sessions()

    def delete_session(self):
        session = self.selected_session()
        if session is None:
            self.say("Select a session first.", "bad")
            return
        if QMessageBox.question(self, "Delete session",
                                f"Delete {antenna_session_name(session)} and all its "
                                "readings?") != QMessageBox.StandardButton.Yes:
            return
        try:
            antenna_session_path(session["id"]).unlink()
        except OSError as exc:
            self.say(f"Couldn't delete: {exc}", "bad")
        self.load_sessions()

    def export_path(self, suggested):
        path, _ = QFileDialog.getSaveFileName(self, "Export CSV", str(Path.home() / suggested),
                                              "CSV files (*.csv)")
        return path

    def export_summary(self):
        sessions = self.checked_sessions()
        if not sessions:
            self.say("Tick the sessions to export.", "bad")
            return
        path = self.export_path("antenna_test_summary.csv")
        if not path:
            return
        try:
            with open(path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(ANTENNA_SUMMARY_HEADERS)
                for s in sessions:
                    for result in s.get("results", []):
                        ref = result.get("ref", {})
                        metrics = antenna_summary(result, s.get("poll_s", 0.5))
                        writer.writerow(
                            [s["id"], s.get("label", ""), s.get("notes", ""), s.get("started", ""),
                             ref.get("name", ""), ANTENNA_KINDS.get(result.get("kind"), ("",))[0],
                             f"{ref['mhz']:.4f}" if ref.get("mhz") else "",
                             ref.get("site_index", ""), result.get("status", ""),
                             len(result.get("samples") or [])]
                            + ["" if metrics.get(k) is None else round(metrics[k], 2)
                               for k in ANTENNA_METRICS]
                            + ["; ".join(antenna_result_notes(result, metrics))])
        except OSError as exc:
            self.say(f"Export failed: {exc}", "bad")
            return
        self.say(f"Exported {len(sessions)} session(s) to {path}.", "ok")

    def export_samples(self):
        sessions = self.checked_sessions()
        if not sessions:
            self.say("Tick the sessions to export.", "bad")
            return
        path = self.export_path("antenna_test_readings.csv")
        if not path:
            return
        try:
            with open(path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(ANTENNA_SAMPLE_HEADERS)
                for s in sessions:
                    for result in s.get("results", []):
                        name = result.get("ref", {}).get("name", "")
                        for row in result.get("samples") or []:
                            writer.writerow([s["id"], s.get("label", ""), name, result.get("kind"),
                                             "voice" if row[S_PHASE] == "v" else "main",
                                             row[S_T], "" if row[S_RSSI] is None else row[S_RSSI],
                                             "" if row[S_SIG] is None else row[S_SIG],
                                             row[S_OPEN], "" if row[S_Q] is None else row[S_Q],
                                             "" if row[S_S] is None else row[S_S], row[S_DEC]])
        except OSError as exc:
            self.say(f"Export failed: {exc}", "bad")
            return
        self.say(f"Exported the readings to {path}.", "ok")


# ---- Close Call (v1.1.37) ------------------------------------------------------
#
# Close Call Only is started with JPM,CC_MODE. Remote Command Specification
# V2.00 lists CC_MODE among the jump modes with a reserved index, so "0" is sent
# first and a blank index if the scanner refuses; if JPM is refused altogether,
# "Close Call Only" is chosen from the scanner's Close Call menu instead.
#
# The spec has no command for the Close Call mode itself (Off / Priority /
# Do Not Disturb), so it is set through the scanner's own Close Call menu
# (MNU,CC → MSI → MSV), the same commands Tools → Scanner → Scanner Menu uses. Items are
# picked by what the menu calls them, never by position, and if the menu doesn't
# look as expected the job stops there and the Scanner Menu window opens on it.
#
# Hits are the Close Call receptions already in reception history (System =
# the scanner mode, e.g. "Close Call Only"; Channel = Frequency = the hit).
# Names, notes and status per frequency are kept in close_call_frequencies.json.

CC_FREQ_FILE = DATA_DIR / "close_call_frequencies.json"
CC_MODES = [("off", "Off", r"^\W*off\b"),
            ("priority", "Priority", r"priorit"),
            ("dnd", "Do Not Disturb", r"do\s*not\s*disturb|\bdnd\b")]
CC_MODE_LABELS = {key: label for key, label, _p in CC_MODES}
CC_MODE_PATTERNS = {key: re.compile(p, re.I) for key, _l, p in CC_MODES}
CC_MODE_MENU = re.compile(r"mode", re.I)
CC_ONLY_ITEM = re.compile(r"close\s*call\s*only|\bonly\b", re.I)
CC_STATUSES = [("new", "New"), ("known", "Known"), ("watch", "Watch"), ("ignored", "Ignored")]
CC_STATUS_LABELS = dict(CC_STATUSES)
CC_STATUS_COLOURS = {"new": "#8bd6f2", "known": "#c9d6e6", "watch": "#ffcf7a",
                     "ignored": "#6c7684"}
CC_RANGES = [(0, "Today"), (7, "Last 7 days"), (30, "Last 30 days"), (None, "Everything")]
CC_STEP_TIMEOUT_S = 6.0          # a menu step the scanner doesn't answer in this time fails
CC_VERIFY_S = 6.0                # time allowed for GSI to report Close Call Only
CC_LEARN_DAYS = 3                # new-frequency alerts start after this many days of hits
CC_WATCH_COOLDOWN_MIN = 5
CC_TABLE_HEADERS = ["Frequency", "Name", "Status", "Hits", "Days", "First heard",
                    "Last heard", "Best RSSI", "Time on air (s)", "Tone / ID", "Notes"]
CC_HIT_HEADERS = ["Start", "Duration (s)", "RSSI (dBm)", "Mode", "Tone / ID"]


def is_close_call(text):
    return "close call" in str(text).casefold()


def cc_freq_key(text):
    """'154.430000' / '154.43' → '154.4300'; 6.25 kHz steps keep their fifth
    decimal ('154.00625'). '' if the text isn't a frequency."""
    try:
        mhz = float(str(text).strip().lower().removesuffix("mhz").strip())
    except ValueError:
        return ""
    if not 25 <= mhz <= 1300:
        return ""
    text = f"{mhz:.5f}"
    return text[:-1] if text.endswith("0") else text


def cc_rssi(text):
    try:
        value = int(float(text))
    except (TypeError, ValueError):
        return None
    return None if value <= -999 else value


def cc_mode_of(text):
    for key, _label, _p in CC_MODES:
        if CC_MODE_PATTERNS[key].search(str(text or "")):
            return key
    return None


def cc_find_item(menu, pattern, exclude=None):
    for item in menu["items"]:
        if pattern.search(item["name"]) and not (exclude and exclude.search(item["name"])):
            return item
    return None


def cc_is_mode_list(menu):
    """True when at least two of Off / Priority / Do Not Disturb are offered."""
    found = {cc_mode_of(item["name"]) for item in menu["items"]} - {None}
    return len(found) >= 2


class CloseCallLog(QObject):
    """Close Call hits by frequency (from reception history and live), with
    names/notes/status per frequency and the new-frequency / watch alerts."""
    changed = pyqtSignal()
    logged = pyqtSignal(str)

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        # key -> {"days": {day: [hits, seconds, best_rssi, first, last]}, "tones": set()}
        self.freqs = {}
        self.days = set()
        self.notes = self.load_notes()
        self.cooldown = {}
        self.alert_log = deque(maxlen=100)

    # ---- settings ------------------------------------------------------------------
    def setting(self, key, default):
        return self.monitor.settings.value("closecall/" + key, default)

    def flag(self, key, default=True):
        return str(self.setting(key, "true" if default else "false")).lower() == "true"

    def min_rssi(self):
        try:
            return int(self.setting("alert_min_rssi", -200))
        except (TypeError, ValueError):
            return -200

    # ---- hits ----------------------------------------------------------------------
    def add_row(self, row, live=False):
        """A reception-history row. Rows that aren't Close Call hits are ignored."""
        if len(row) < len(HEADERS) or not is_close_call(row[3]):
            return
        key = cc_freq_key(row[6]) or cc_freq_key(row[5])
        if not key:
            return
        day = row[0][:10]
        try:
            seconds = float(row[2])
        except ValueError:
            seconds = 0.0
        rssi = cc_rssi(row[8])
        entry = self.freqs.get(key)
        new = entry is None
        if new:
            entry = self.freqs[key] = {"days": {}, "tones": set()}
        d = entry["days"].get(day)
        if d is None:
            d = entry["days"][day] = [0, 0.0, None, row[0], row[0]]
        d[0] += 1
        d[1] += seconds
        if rssi is not None and (d[2] is None or rssi > d[2]):
            d[2] = rssi
        d[3] = min(d[3], row[0])
        d[4] = max(d[4], row[0])
        if row[7] not in ("", "—"):
            entry["tones"].add(row[7])
        learning_before = len(self.days) < CC_LEARN_DAYS
        self.days.add(day)
        if live:
            self.check_alert(key, new and not learning_before, rssi, row)
            self.changed.emit()

    def learning(self):
        return len(self.days) < CC_LEARN_DAYS

    def summary(self, days_back=None, today=None):
        """One dict per frequency heard within the range (None = everything)."""
        today = today or datetime.now().date()
        first_day = (None if days_back is None
                     else (today - timedelta(days=days_back)).strftime("%Y-%m-%d"))
        rows = []
        for key, entry in self.freqs.items():
            days = [(day, d) for day, d in entry["days"].items()
                    if first_day is None or day >= first_day]
            if not days:
                continue
            best = [d[2] for _day, d in days if d[2] is not None]
            note = self.notes.get(key, {})
            rows.append({
                "key": key,
                "hits": sum(d[0] for _day, d in days),
                "seconds": sum(d[1] for _day, d in days),
                "days": len(days),
                "first": min(d[3] for _day, d in days),
                "last": max(d[4] for _day, d in days),
                "best": max(best) if best else None,
                "tones": ", ".join(sorted(entry["tones"]))[:60],
                "name": note.get("name", ""),
                "status": note.get("status", "new"),
                "notes": note.get("notes", ""),
            })
        rows.sort(key=lambda r: r["last"], reverse=True)
        return rows

    def hits_for(self, key):
        """Every logged hit on one frequency, newest first (read from history)."""
        entry = self.freqs.get(key)
        if entry is None:
            return []
        hits = []
        for day in sorted(entry["days"], reverse=True):
            try:
                path = daily_log_path(datetime.strptime(day, "%Y-%m-%d"))
            except ValueError:
                continue
            paths = [path] if path.exists() else []
            if not paths and LEGACY_LOG_FILE.exists():
                paths = [LEGACY_LOG_FILE]
            for p in paths:
                try:
                    with p.open(newline="", encoding="utf-8-sig") as f:
                        for row in csv.reader(f):
                            if (len(row) == len(HEADERS) and row[0].startswith(day)
                                    and is_close_call(row[3])
                                    and (cc_freq_key(row[6]) or cc_freq_key(row[5])) == key):
                                hits.append(row)
                except (OSError, csv.Error, UnicodeDecodeError):
                    continue
        hits.sort(key=lambda r: r[0], reverse=True)
        return hits

    # ---- names, notes, status --------------------------------------------------------
    def status(self, key):
        return self.notes.get(key, {}).get("status", "new")

    def name(self, key):
        return self.notes.get(key, {}).get("name", "")

    def label(self, key):
        name = self.name(key)
        return f"{key} MHz" + (f" ({name})" if name else "")

    def load_notes(self):
        try:
            data = json.loads(CC_FREQ_FILE.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return {}
        if not isinstance(data, dict):
            return {}
        return {k: v for k, v in data.items() if isinstance(v, dict)}

    def save_notes(self):
        try:
            DATA_DIR.mkdir(parents=True, exist_ok=True)
            tmp = CC_FREQ_FILE.with_suffix(".tmp")
            tmp.write_text(json.dumps(self.notes, indent=1, sort_keys=True), encoding="utf-8")
            tmp.replace(CC_FREQ_FILE)
        except OSError as exc:
            self.monitor.statusBar().showMessage(f"Close Call notes not saved: {exc}", 10000)

    def set_note(self, key, **fields):
        entry = dict(self.notes.get(key, {}))
        for field, value in fields.items():
            value = str(value or "").strip()
            if field == "status" and value == "new":
                value = ""
            if value:
                entry[field] = value
            else:
                entry.pop(field, None)
        entry.pop("updated", None)
        if entry:
            entry["updated"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            self.notes[key] = entry
        else:
            self.notes.pop(key, None)
        self.save_notes()
        self.changed.emit()

    # ---- alerts ----------------------------------------------------------------------
    def log(self, text):
        line = f"{datetime.now():%H:%M:%S}  {text}"
        self.alert_log.appendleft(line)
        self.logged.emit(line)

    def check_alert(self, key, new, rssi, row):
        status = self.status(key)
        if status == "ignored":
            return
        floor = self.min_rssi()
        if floor > -200 and rssi is not None and rssi < floor:
            return
        detail = " • ".join(x for x in (
            row[0][11:], f"RSSI {row[8]} dBm" if rssi is not None else "",
            row[7] if row[7] not in ("", "—") else "", row[3]) if x)
        if status == "watch":
            self.alert(("watch", key), CC_WATCH_COOLDOWN_MIN,
                       f"Close Call hit: {self.label(key)}", detail)
        elif new and status == "new" and self.flag("alert_new"):
            self.alert(("new", key), 0, f"New Close Call frequency: {self.label(key)}", detail)

    def alert(self, cool_key, minutes, title, text):
        now = time.monotonic()
        if now - self.cooldown.get(cool_key, -1e9) < minutes * 60:
            return
        self.cooldown[cool_key] = now
        self.log(f"{title} — {text}")
        self.monitor.notify(title, text, "close_call")


class CloseCallControl(QObject):
    """Sets and reads the Close Call mode through the scanner's menu, and starts
    Close Call Only. One job at a time; replies are matched to the job."""
    changed = pyqtSignal()

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.job = None
        self.verify = None              # waiting for GSI to report Close Call Only
        self.message = ("", None)
        self.scanner_mode = ""          # GSI Mode attribute, e.g. "Close Call Only"
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.tick)
        self.timer.start(500)

    # ---- state -----------------------------------------------------------------------
    @property
    def busy(self):
        return self.job is not None

    @property
    def mode(self):
        mode = str(self.monitor.settings.value("closecall/mode", ""))
        return mode if mode in CC_MODE_LABELS else ""

    def remember_mode(self, key):
        self.monitor.settings.setValue("closecall/mode", key)
        self.monitor.settings.setValue("closecall/mode_time",
                                       datetime.now().strftime("%Y-%m-%d %H:%M"))
        self.changed.emit()

    def mode_text(self):
        if not self.mode:
            return "not known yet (press CHECK)"
        when = str(self.monitor.settings.value("closecall/mode_time", ""))
        return CC_MODE_LABELS[self.mode] + (f" (as of {when})" if when else "")

    def say(self, text, tone=None):
        self.message = (text, tone)
        self.monitor.statusBar().showMessage("Close Call: " + text, 10000)
        self.changed.emit()

    def rsv(self):
        return self.monitor.scanner_menu.rsv

    # ---- actions ---------------------------------------------------------------------
    def start(self, goal, target=None):
        if not self.monitor.connected:
            self.say("Not connected to the scanner.", "bad")
            return
        if self.job is not None:
            self.say("Still working on the last Close Call request…")
            return
        wx = getattr(self.monitor, "wx_priority", None)
        if wx is not None and wx.busy and goal != "only":
            self.say("The scanner's menu is busy with Weather Alert Priority; try again in a moment.")
            return
        self.verify = None
        self.job = {"goal": goal, "target": target, "level": 0, "await": None,
                    "command": "", "retry": None, "expect_xml": False,
                    "deadline": 0.0, "chosen": None, "final": None, "leaves_menu": False}
        if goal == "only":
            self.say("Starting Close Call Only…")
            self.send("JPM,CC_MODE,0", retry="JPM,CC_MODE,")
        else:
            self.say(f"Setting Close Call mode to {CC_MODE_LABELS[target]}…" if goal == "set"
                     else "Reading the Close Call mode from the scanner's menu…")
            self.send("MNU,CC,")

    def set_mode(self, key):
        self.start("set", key)

    def check_mode(self):
        self.start("check")

    def start_only(self):
        self.start("only")

    def resume_scan(self):
        command = "JPM,SCN_MODE,4294967295"
        if self.monitor.queue(command):
            self.monitor.command_reply("QUEUED: " + command)
            self.say("Resuming scan…")
        else:
            self.say("Not connected to the scanner.", "bad")

    def connection_changed(self, connected):
        if not connected:
            self.job = None
            self.verify = None
            self.scanner_mode = ""
        self.changed.emit()

    # ---- commands --------------------------------------------------------------------
    def send(self, command, retry=None):
        job = self.job
        if job is None:
            return
        if not self.monitor.queue(command):
            self.fail("Not connected — nothing was sent.", open_menu=False)
            return
        job.update({"await": command.split(",")[0], "command": command, "retry": retry,
                    "expect_xml": False, "deadline": time.monotonic() + CC_STEP_TIMEOUT_S})

    def read_menu(self):
        job = self.job
        job.update({"expect_xml": True, "deadline": time.monotonic() + CC_STEP_TIMEOUT_S})
        if not self.monitor.queue("MSI"):
            self.fail("Not connected.", open_menu=False)

    def msv(self, value):
        rsv = self.rsv()
        value = str(value).replace(",", "\t")
        self.send(f"MSV,{rsv},{value}", retry=f"MSV,0,{value}" if rsv == "" else None)

    def exit_menu(self, text, tone="ok"):
        self.job["final"] = (text, tone)
        rsv = self.rsv()
        self.send(f"MSB,{rsv},RETURN_PREVOUS_MODE",     # spelling as in the spec
                  retry="MSB,0,RETURN_PREVOUS_MODE" if rsv == "" else None)

    def fail(self, text, open_menu=True):
        self.job = None
        if open_menu and self.monitor.connected:
            text += (" The Scanner Menu window is open on the scanner's menu so you can "
                     "finish there.")
            self.monitor.scanner_menu.open()
        self.say(text, "bad")

    # ---- replies ---------------------------------------------------------------------
    def route(self, reply):
        """Replies to this job's commands. True keeps them off the status line."""
        job = self.job
        if job is None:
            return False
        if (job["expect_xml"] and not job["await"] and reply.startswith("REPLY: MSI,")
                and "<XML>" not in reply):
            self.fail("The scanner says it isn't in a menu (MSI,"
                      f"{reply[len('REPLY: MSI,'):].strip()}).")
            return False
        code = job["await"]
        if not code or not reply.startswith(f"REPLY: {code},"):
            return False
        job["await"] = None
        if not reply.rstrip().endswith(",OK"):
            if job["retry"]:
                self.send(job["retry"])
            else:
                self.refused(code, reply[len("REPLY: "):])
            return True
        if job["command"].startswith(("MSV,0", "MSB,0")) and self.rsv() == "":
            self.monitor.scanner_menu.rsv = "0"       # the scanner wanted RSV=0
            self.monitor.settings.setValue("menu/rsv", "0")
        self.step_ok(code)
        return True

    def refused(self, code, body):
        job = self.job
        if code == "JPM" and job["goal"] == "only":
            # Fall back to the scanner's Close Call menu.
            job["goal"] = "only_menu"
            self.say(f"The scanner refused JPM,CC_MODE ({body}); trying its Close Call menu…")
            self.send("MNU,CC,")
        elif code == "MNU":
            self.fail(f"The scanner refused to open its Close Call menu ({body}). It may be "
                      "busy (Analyze, a Discovery session or another menu).", open_menu=False)
        elif code == "MSB":
            self.fail(f"The change was made, but the scanner refused to leave the menu "
                      f"({body}).")
        else:
            self.fail(f"The scanner refused {job['command']} ({body}).")

    def step_ok(self, code):
        job = self.job
        if code == "JPM" or (code == "MSV" and job["leaves_menu"]):
            self.job = None
            self.verify = time.monotonic() + CC_VERIFY_S
            self.say("Accepted — waiting for the scanner to report Close Call Only…")
        elif code == "MNU":
            self.read_menu()
        elif code == "MSV" and job["chosen"] is not None:
            if job["goal"] == "set":
                self.remember_mode(job["target"])
                self.exit_menu(f"✓ Close Call mode set to {CC_MODE_LABELS[job['target']]}.")
            else:
                self.read_menu()
        elif code == "MSV":
            self.read_menu()                 # went into a submenu
        elif code == "MSB":
            text, tone = job["final"] or ("Done.", "ok")
            self.job = None
            self.say(text, tone)

    def handle_xml(self, xml):
        job = self.job
        if job is None or not job["expect_xml"] or job["await"]:
            return
        job["expect_xml"] = False
        try:
            menu = parse_menu(xml)
        except ET.ParseError:
            self.fail("The scanner's menu reply couldn't be read.")
            return
        job["level"] += 1
        if job["level"] > 3:
            self.fail("The Close Call menu didn't lead where expected.")
            return
        goal = job["goal"]
        names = ", ".join(f"“{i['name']}”" for i in menu["items"][:8]) or "no items"
        if goal == "only_menu":
            item = cc_find_item(menu, CC_ONLY_ITEM)
            if item is None:
                self.fail(f"No Close Call Only item in “{menu['name']}” ({names}).")
                return
            job["leaves_menu"] = True
            self.say(f"Choosing “{item['name']}”…")
            self.msv(item["index"])
            return
        if cc_is_mode_list(menu):
            if goal == "set":
                item = cc_find_item(menu, CC_MODE_PATTERNS[job["target"]])
                if item is None:
                    self.fail(f"“{menu['name']}” has no {CC_MODE_LABELS[job['target']]} "
                              f"choice ({names}).")
                    return
                job["chosen"] = item
                self.say(f"Choosing “{item['name']}”…")
                self.msv(item["index"])
                return
            selected = next((i for i in menu["items"] if i["selected"]), None)
            key = cc_mode_of(selected["name"]) if selected else cc_mode_of(menu["value"])
            if key is None:
                self.fail("The scanner's menu doesn't mark which Close Call mode is chosen.")
                return
            self.remember_mode(key)
            self.exit_menu(f"Close Call mode is {CC_MODE_LABELS[key]}.")
            return
        sub = cc_find_item(menu, CC_MODE_MENU, exclude=CC_ONLY_ITEM)
        if sub is None or job["level"] > 1:
            self.fail(f"Couldn't find the Close Call mode setting in “{menu['name']}” "
                      f"({names}).")
            return
        if goal == "check" and cc_mode_of(sub["value"]):
            key = cc_mode_of(sub["value"])
            self.remember_mode(key)
            self.exit_menu(f"Close Call mode is {CC_MODE_LABELS[key]}.")
            return
        self.msv(sub["index"])

    def tick(self):
        now = time.monotonic()
        job = self.job
        if job is not None and job["deadline"] and now > job["deadline"]:
            in_menu = job["level"] > 0 or job["await"] in ("MSV", "MSB") or job["expect_xml"]
            self.fail("The scanner didn't answer in time.", open_menu=in_menu)
        if self.verify is not None and now > self.verify:
            self.verify = None
            self.say("The command was accepted, but the scanner hasn't reported Close Call "
                     f"Only (it reports “{self.scanner_mode or '—'}”). Check the scanner.",
                     "bad")

    def gsi(self, mode):
        mode = str(mode or "")
        changed = mode != self.scanner_mode
        self.scanner_mode = mode
        if self.verify is not None and is_close_call(mode) and "only" in mode.casefold():
            self.verify = None
            self.say("✓ Close Call Only is running.", "ok")
        elif changed:
            self.changed.emit()


class WeatherPriorityControl(QObject):
    """1.1.83: Weather Alert Priority (on the scanner: Menu → Weather Operation → Weather
    Alert Priority). With it on, the scanner keeps checking the weather channels for an
    alert while it scans. The remote spec has no command for it, so it is set and read
    through the scanner's Weather menu (MNU,WX → MSI → MSV → MSB), like the Close Call mode."""
    changed = pyqtSignal()
    ITEM = re.compile(r"priorit", re.I)
    STEP_IN = re.compile(r"alert", re.I)        # if the item sits one menu deeper
    CHOICES = {"on": re.compile(r"^\W*on\b", re.I), "off": re.compile(r"^\W*off\b", re.I)}

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.job = None
        self.message = ("", None)
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.tick)
        self.timer.start(500)

    # ---- state -----------------------------------------------------------------------
    @property
    def busy(self):
        return self.job is not None

    @property
    def state(self):
        value = str(self.monitor.settings.value("modes/wx_priority", ""))
        return value if value in self.CHOICES else ""

    def remember(self, key):
        self.monitor.settings.setValue("modes/wx_priority", key)
        self.monitor.settings.setValue("modes/wx_priority_time",
                                       datetime.now().strftime("%Y-%m-%d %H:%M"))
        self.changed.emit()

    def state_text(self):
        if not self.state:
            return "not known yet (press CHECK)"
        when = str(self.monitor.settings.value("modes/wx_priority_time", ""))
        return self.state.title() + (f" (as of {when})" if when else "")

    @classmethod
    def value_of(cls, text):
        text = str(text or "").rsplit(":", 1)[-1]     # "Weather Alert Priority:Off" too
        for key, pattern in cls.CHOICES.items():
            if pattern.search(text):
                return key
        return None

    def say(self, text, tone=None):
        self.message = (text, tone)
        self.monitor.statusBar().showMessage("Weather Alert Priority: " + text, 10000)
        self.changed.emit()

    def rsv(self):
        return self.monitor.scanner_menu.rsv

    # ---- actions ---------------------------------------------------------------------
    def set(self, key):
        self.start("set", key)

    def check(self):
        self.start("check")

    def toggle(self):
        self.set("off" if self.state == "on" else "on")

    def start(self, goal, target=None):
        if not self.monitor.connected:
            self.say("Not connected to the scanner.", "bad")
            return
        if self.job is not None or self.monitor.close_call.busy:
            self.say("The scanner's menu is busy with another request; try again in a moment.")
            return
        self.job = {"goal": goal, "target": target, "level": 0, "await": None,
                    "command": "", "retry": None, "expect_xml": False,
                    "deadline": 0.0, "chosen": None, "final": None}
        self.say(f"Turning it {target}…" if goal == "set" else "Reading it from the scanner's menu…")
        self.send("MNU,WX,")

    # ---- commands --------------------------------------------------------------------
    def send(self, command, retry=None):
        job = self.job
        if job is None:
            return
        if not self.monitor.queue(command):
            self.fail("Not connected — nothing was sent.", open_menu=False)
            return
        job.update({"await": command.split(",")[0], "command": command, "retry": retry,
                    "expect_xml": False, "deadline": time.monotonic() + CC_STEP_TIMEOUT_S})

    def read_menu(self):
        self.job.update({"expect_xml": True, "deadline": time.monotonic() + CC_STEP_TIMEOUT_S})
        if not self.monitor.queue("MSI"):
            self.fail("Not connected.", open_menu=False)

    def msv(self, value):
        rsv = self.rsv()
        value = str(value).replace(",", "\t")
        self.send(f"MSV,{rsv},{value}", retry=f"MSV,0,{value}" if rsv == "" else None)

    def exit_menu(self, text, tone="ok"):
        self.job["final"] = (text, tone)
        rsv = self.rsv()
        self.send(f"MSB,{rsv},RETURN_PREVOUS_MODE",     # spelling as in the spec
                  retry="MSB,0,RETURN_PREVOUS_MODE" if rsv == "" else None)

    def fail(self, text, open_menu=True):
        self.job = None
        if open_menu and self.monitor.connected:
            text += (" The Scanner Menu window is open on the scanner's menu so you can "
                     "finish there.")
            self.monitor.scanner_menu.open()
        self.say(text, "bad")

    # ---- replies ---------------------------------------------------------------------
    def route(self, reply):
        job = self.job
        if job is None:
            return False
        if (job["expect_xml"] and not job["await"] and reply.startswith("REPLY: MSI,")
                and "<XML>" not in reply):
            self.fail("The scanner says it isn't in a menu (MSI,"
                      f"{reply[len('REPLY: MSI,'):].strip()}).")
            return False
        code = job["await"]
        if not code or not reply.startswith(f"REPLY: {code},"):
            return False
        job["await"] = None
        if not reply.rstrip().endswith(",OK"):
            if job["retry"]:
                self.send(job["retry"])
            elif code == "MNU":
                self.fail(f"The scanner refused to open its Weather menu "
                          f"({reply[len('REPLY: '):]}). It may be busy (another menu, "
                          "Analyze or a Discovery session).", open_menu=False)
            elif code == "MSB":
                self.fail("The change was made, but the scanner refused to leave the menu.")
            else:
                self.fail(f"The scanner refused {job['command']} ({reply[len('REPLY: '):]}).")
            return True
        if job["command"].startswith(("MSV,0", "MSB,0")) and self.rsv() == "":
            self.monitor.scanner_menu.rsv = "0"
            self.monitor.settings.setValue("menu/rsv", "0")
        if code == "MNU":
            self.read_menu()
        elif code == "MSV" and job["chosen"] is not None:
            self.remember(job["target"])
            self.exit_menu(f"✓ Weather Alert Priority turned {job['target'].title()}.")
        elif code == "MSV":
            self.read_menu()
        elif code == "MSB":
            text, tone = job["final"] or ("Done.", "ok")
            self.job = None
            self.say(text, tone)
        return True

    def handle_xml(self, xml):
        job = self.job
        if job is None or not job["expect_xml"] or job["await"]:
            return
        job["expect_xml"] = False
        try:
            menu = parse_menu(xml)
        except ET.ParseError:
            self.fail("The scanner's menu reply couldn't be read.")
            return
        job["level"] += 1
        if job["level"] > 3:
            self.fail("The Weather menu didn't lead where expected.")
            return
        names = ", ".join(f"“{i['name']}”" for i in menu["items"][:8]) or "no items"
        offered = {self.value_of(i["name"]) for i in menu["items"]} - {None}
        if offered == {"on", "off"}:                    # the On / Off choice
            if job["goal"] == "set":
                item = cc_find_item(menu, self.CHOICES[job["target"]])
                job["chosen"] = item
                self.say(f"Choosing “{item['name']}”…")
                self.msv(item["index"])
                return
            selected = next((i for i in menu["items"] if i["selected"]), None)
            key = self.value_of(selected["name"]) if selected else self.value_of(menu["value"])
            if key is None:
                self.fail("The scanner's menu doesn't mark whether it's on or off.")
                return
            self.remember(key)
            self.exit_menu(f"Weather Alert Priority is {key.title()}.")
            return
        item = cc_find_item(menu, self.ITEM)
        if item is not None:
            if job["goal"] == "check" and self.value_of(item["value"]):
                key = self.value_of(item["value"])
                self.remember(key)
                self.exit_menu(f"Weather Alert Priority is {key.title()}.")
                return
            self.msv(item["index"])
            return
        deeper = cc_find_item(menu, self.STEP_IN, exclude=re.compile(r"only|same|fips", re.I))
        if deeper is None or job["level"] > 1:
            self.fail(f"Couldn't find Weather Alert Priority in “{menu['name']}” ({names}).")
            return
        self.msv(deeper["index"])

    def tick(self):
        job = self.job
        if job is not None and job["deadline"] and time.monotonic() > job["deadline"]:
            in_menu = job["level"] > 0 or job["await"] in ("MSV", "MSB") or job["expect_xml"]
            self.fail("The scanner didn't answer in time.", open_menu=in_menu)


class CloseCallNoteDialog(QDialog):
    def __init__(self, log, key, parent=None):
        super().__init__(parent)
        self.setWindowTitle(f"Close Call frequency {key} MHz")
        note = log.notes.get(key, {})
        form = QFormLayout(self)
        self.name = QLineEdit(note.get("name", ""))
        self.name.setPlaceholderText("e.g. Fireground 1, Stadium ops, Store security")
        form.addRow("Name", self.name)
        self.status = QComboBox()
        for value, label in CC_STATUSES:
            self.status.addItem(label, value)
        self.status.setCurrentIndex(max(0, self.status.findData(note.get("status", "new"))))
        self.status.setToolTip("Watch: alert every time it's heard (at most every "
                               f"{CC_WATCH_COOLDOWN_MIN} minutes). Ignored: no alerts, and "
                               "hidden unless Show ignored is ticked.")
        form.addRow("Status", self.status)
        self.notes = QTextEdit(note.get("notes", ""))
        self.notes.setMinimumHeight(90)
        form.addRow("Notes", self.notes)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Save
                                   | QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        form.addRow(buttons)
        self.resize(460, 280)

    def values(self):
        return {"name": self.name.text(), "status": self.status.currentData(),
                "notes": self.notes.toPlainText().replace("\n", " ")}


class CloseCallFreqItem(QTableWidgetItem):
    """A frequency cell that sorts by value, not as text."""

    def __lt__(self, other):
        try:
            return float(self.text()) < float(other.text())
        except (TypeError, ValueError):
            return super().__lt__(other)


