class UpdateChecker(QObject):
    """Looks for a newer version: in ~/Downloads, and on GitHub when a repository is set."""
    found = pyqtSignal(object)            # {"version", "source", "path" or "url", "notes", "name"} or None
    github_done = pyqtSignal(object)

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.latest = None
        self.github_done.connect(self._github_result)
        if str(monitor.settings.value("updates/at_startup", "true")) == "true":
            QTimer.singleShot(20000, lambda: self.check(quiet=True))

    def setting(self, key, default=""):
        return str(self.monitor.settings.value(f"updates/{key}", default) or "")

    def check(self, quiet=False):
        self.quiet = quiet
        local = local_updates()
        self.latest = ({"version": local[0][0], "source": "Downloads", "path": local[0][1],
                        "notes": deb_notes(local[0][1]), "name": local[0][1].name} if local else None)
        repo = self.setting("github_repo", DEFAULT_GITHUB_REPO)
        if repo:
            threading.Thread(target=self._github, args=(repo,), daemon=True).start()
        else:
            self._announce()

    def _github(self, repo):
        try:
            result = github_latest(repo)
        except Exception as exc:              # offline, rate-limited, no release yet…
            result = {"error": str(exc)}
        self.github_done.emit(result)

    def _github_result(self, result):
        self.github_error = result.get("error") if isinstance(result, dict) else ""
        if isinstance(result, tuple) and version_key(result[0]) > version_key(VERSION):
            if self.latest is None or version_key(result[0]) > version_key(self.latest["version"]):
                self.latest = {"version": result[0], "source": "GitHub", "url": result[1], "notes": result[2],
                               "name": result[3]}
        self._announce()

    def _announce(self):
        latest = self.latest
        if latest and getattr(self, "quiet", False) and latest["version"] == self.setting("skip_version"):
            latest = None
        self.found.emit(latest)


class UpdateDialog(QDialog):
    """Help → Check for Updates…"""

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.checker = monitor.updates
        self.latest = None
        self.setWindowTitle("Check for Updates")
        self.resize(640, 520)
        layout = QVBoxLayout(self)
        how = ("installed from a .deb package" if installed_from_deb()
               else "run from a folder (installing an update adds the .deb version alongside)")
        intro = make_label(f"SDS100 Monitor v{VERSION} ({PACKAGE_NAME}), {how}.")
        intro.setWordWrap(True)
        layout.addWidget(intro)
        self.result = make_label("Checking…")
        self.result.setWordWrap(True)
        set_css(self.result, "font-weight:700;color:#8bd6f2;")
        layout.addWidget(self.result)
        self.notes = QTextEdit()
        self.notes.setReadOnly(True)
        self.notes.setPlaceholderText("What's new appears here.")
        layout.addWidget(self.notes, 1)
        form = QFormLayout()
        self.startup = QCheckBox("Check when the Monitor starts")
        self.startup.setChecked(self.checker.setting("at_startup", "true") == "true")
        self.startup.toggled.connect(lambda on: monitor.settings.setValue("updates/at_startup",
                                                                          "true" if on else "false"))
        form.addRow("", self.startup)
        self.repo = QLineEdit(self.checker.setting("github_repo", DEFAULT_GITHUB_REPO))
        self.repo.setPlaceholderText("owner/repository (leave empty until the project is on GitHub)")
        self.repo.editingFinished.connect(lambda: monitor.settings.setValue("updates/github_repo",
                                                                            self.repo.text().strip()))
        form.addRow("GitHub", self.repo)
        layout.addLayout(form)
        self.startup.hide()                          # v1.2.0: in Settings → Updates
        self.repo.hide()
        form.labelForField(self.repo).hide()
        where = make_label(f"Also looks in {Path.home() / 'Downloads'} for {PACKAGE_NAME}_<version>_all.deb.")
        where.setWordWrap(True)
        set_css(where, "color:#a5bdd2;")
        layout.addWidget(where)
        buttons = QHBoxLayout()
        self.check_btn = QPushButton("CHECK NOW")
        self.check_btn.clicked.connect(self.check)
        self.install_btn = QPushButton("INSTALL")
        set_css(self.install_btn, "QPushButton{background:#1b8a5a;color:white;font-weight:700;padding:6px 14px;}")
        self.install_btn.clicked.connect(self.install)
        self.skip_btn = QPushButton("SKIP THIS VERSION")
        self.skip_btn.clicked.connect(self.skip)
        self.close_btn = QPushButton("CLOSE")
        self.close_btn.clicked.connect(self.accept)
        for b in (self.check_btn, self.install_btn, self.skip_btn):
            buttons.addWidget(b)
        buttons.addStretch(1)
        buttons.addWidget(self.close_btn)
        layout.addLayout(buttons)
        self.checker.found.connect(self.show_result)
        self.finished.connect(lambda *_: self._disconnect())
        self.process = None
        self.show_result(None, checking=True)
        QTimer.singleShot(0, self.check)

    def _disconnect(self):
        try:
            self.checker.found.disconnect(self.show_result)
        except (TypeError, RuntimeError):
            pass

    def check(self):
        self.monitor.settings.setValue("updates/github_repo", self.repo.text().strip())
        set_text(self.result, "Checking…")
        self.install_btn.setEnabled(False)
        self.skip_btn.setEnabled(False)
        self.checker.check(quiet=False)

    def show_result(self, latest, checking=False):
        self.latest = latest
        if checking:
            return
        error = getattr(self.checker, "github_error", "")
        if latest is None:
            set_text(self.result, f"You have the newest version (v{VERSION})."
                     + (f" GitHub couldn't be checked: {error}" if error else ""))
            self.notes.clear()
        else:
            set_text(self.result, f"Version {latest['version']} is available ({latest['source']}: {latest['name']}).")
            self.notes.setPlainText(latest.get("notes") or "")
        self.install_btn.setEnabled(latest is not None)
        self.skip_btn.setEnabled(latest is not None)

    def skip(self):
        if self.latest:
            self.monitor.settings.setValue("updates/skip_version", self.latest["version"])
            set_text(self.result, f"Version {self.latest['version']} won't be offered at startup again.")
            self.monitor.update_label.setVisible(False)

    def install(self):
        latest = self.latest
        if not latest:
            return
        if "url" in latest:
            target = Path.home() / "Downloads" / latest["name"]
            set_text(self.result, f"Downloading {latest['name']}…")
            self.install_btn.setEnabled(False)

            def download():
                try:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    tmp = target.with_name(target.name + ".part")
                    with urllib.request.urlopen(latest["url"], timeout=60) as response, tmp.open("wb") as out:
                        shutil.copyfileobj(response, out)
                    os.replace(tmp, target)
                    QTimer.singleShot(0, lambda: self.run_install(target))
                except Exception as exc:
                    QTimer.singleShot(0, lambda: set_text(self.result, f"Download failed: {exc}"))
            threading.Thread(target=download, daemon=True).start()
        else:
            self.run_install(latest["path"])

    def run_install(self, path):
        if shutil.which("pkexec") is None:
            QMessageBox.information(self, "Install", "Install it from a terminal with:\n\n"
                                    f"sudo apt install {Path(path).resolve()}")
            return
        set_text(self.result, f"Installing {Path(path).name}… (KDE asks for your password)")
        self.install_btn.setEnabled(False)
        try:
            path = staged_copy(path)
        except OSError as exc:
            QMessageBox.warning(self, "Install", f"Couldn't prepare the package: {exc}")
            return
        argv = install_command(path)
        self.close_btn.setEnabled(False)
        self.process = QProcess(self)
        self.process.setProcessChannelMode(QProcess.ProcessChannelMode.MergedChannels)
        self.process.finished.connect(lambda code, _status: self.installed(code))
        self.process.start(argv[0], argv[1:])

    def installed(self, code):
        output = bytes(self.process.readAll()).decode(errors="replace") if self.process else ""
        self.process = None
        self.close_btn.setEnabled(True)
        if code != 0:
            set_text(self.result, "Not installed" + (" (cancelled)." if code in (126, 127) else f" (apt-get exit {code})."))
            self.notes.setPlainText(output[-4000:])
            self.install_btn.setEnabled(True)
            return
        set_text(self.result, "Installed. Restart the Monitor to use the new version.")
        self.monitor.update_label.setVisible(False)
        if QMessageBox.question(self, "Update installed", "Restart SDS100 Monitor now?") \
                == QMessageBox.StandardButton.Yes:
            # Started a few seconds later, once this copy has closed and let go of the scanner port.
            QProcess.startDetached("/bin/sh", ["-c", f"sleep 3; exec {PROGRAM_COMMAND}"])
            self.accept()
            self.monitor.close()

    def reject(self):
        if self.process is not None:
            return                              # never leave apt-get half-way by closing
        super().reject()


# ---- Aircraft: ADS-B from readsb (v1.1.58) -----------------------------------------------------
#
# Reads the aircraft list that readsb (or dump1090) writes on this computer, usually
# /run/readsb/aircraft.json, or tar1090's copy over HTTP. With it the Monitor:
#   * alerts on emergency squawks (7500, 7600, 7700) and on aircraft in your watch list;
#   * matches the callsigns heard in airband transcripts ("Delta twelve thirty-four",
#     "November one two three alpha bravo", "Cessna four five alpha") to the aircraft that were in
#     range at the time, and shows them under the transcript.
# Only files on this computer (or the address you set) are read; nothing is sent anywhere.

ADSB_DIR = DATA_DIR / "adsb"
ADSB_SOURCES = ["/run/readsb/aircraft.json", "/run/adsb/aircraft.json", "/run/dump1090-fa/aircraft.json",
                "/run/dump1090/aircraft.json", "/run/dump1090-mutability/aircraft.json",
                "/run/skyaware978/aircraft.json"]
ADSB_URL = "http://127.0.0.1/tar1090/data/aircraft.json"
ADSB_HISTORY_S = 3600                 # how long positions are kept for matching late transcripts
ADSB_MATCH_WINDOW_S = 120             # aircraft seen this close to a call can be the one heard
EMERGENCY_SQUAWKS = {"7500": "hijack", "7600": "radio failure", "7700": "emergency"}
EMERGENCY_FIELD = {"general": "emergency", "lifeguard": "medical (lifeguard)", "minfuel": "minimum fuel",
                   "nordo": "radio failure", "unlawful": "unlawful interference", "downed": "aircraft down"}
ADSB_ALERT_HEADERS = ["Time", "Kind", "Hex", "Callsign", "Registration", "Type", "Squawk", "Altitude (ft)",
                      "Speed (kt)", "Latitude", "Longitude", "Distance (mi)", "Details"]
ADSB_HEARD_HEADERS = ["Time", "Channel", "Frequency", "Audio File", "Said", "Callsign", "Hex", "Registration",
                      "Type", "Altitude (ft)", "Speed (kt)", "Latitude", "Longitude", "Distance (mi)", "Match"]
AIRBAND_RANGES_MHZ = ((108.0, 137.0), (225.0, 400.0))

# Radio names (telephony) of airlines and operators often heard in North America → ICAO prefix.
AIRLINE_TELEPHONY = {
    "delta": "DAL", "american": "AAL", "united": "UAL", "southwest": "SWA", "jetblue": "JBU",
    "jet blue": "JBU", "alaska": "ASA", "spirit wings": "NKS", "spirit": "NKS", "frontier flight": "FFT",
    "frontier": "FFT", "allegiant": "AAY", "hawaiian": "HAL", "sun country": "SCX", "moxy": "MXY",
    "fedex": "FDX", "fed ex": "FDX", "ups": "UPS", "giant": "GTI", "kalitta": "CKS", "connie": "CKS",
    "endeavor": "EDV", "envoy": "ENY", "brickyard": "RPA", "skywest": "SKW", "sky west": "SKW",
    "piedmont": "PDT", "blue streak": "JIA", "air shuttle": "ASH", "lindbergh": "GJS", "horizon": "QXE",
    "commutair": "UCA", "commute air": "UCA", "execjet": "EJA", "exec jet": "EJA", "flexjet": "LXJ",
    "flex jet": "LXJ", "air canada": "ACA", "jazz": "JZA", "westjet": "WJA", "west jet": "WJA",
    "reach": "RCH", "speedbird": "BAW", "lufthansa": "DLH", "air france": "AFR", "silver wings": "SIL",
    "cactus": "AWE", "state express": "ABX", "abex": "ABX", "polar": "PAC", "atlas": "GTI",
    "contour": "VTE", "mountain air": "MTN", "ameriflight": "AMF", "wheels up": "UPJ",
}
GA_PREFIXES = ("cessna", "piper", "cirrus", "beech", "beechcraft", "bonanza", "baron", "mooney", "diamond",
               "citation", "king air", "lear", "learjet", "gulfstream", "challenger", "falcon", "pilatus",
               "helicopter", "robinson", "bell", "airbus", "lifeguard", "medevac", "experimental", "skyhawk",
               "cherokee", "archer", "warrior", "seminole", "november")
PHONETIC = {"alpha": "A", "alfa": "A", "bravo": "B", "charlie": "C", "delta": "D", "echo": "E", "foxtrot": "F",
            "golf": "G", "hotel": "H", "india": "I", "juliet": "J", "juliett": "J", "kilo": "K", "lima": "L",
            "mike": "M", "november": "N", "oscar": "O", "papa": "P", "quebec": "Q", "romeo": "R",
            "sierra": "S", "tango": "T", "uniform": "U", "victor": "V", "whiskey": "W", "xray": "X",
            "x-ray": "X", "yankee": "Y", "zulu": "Z"}
SPOKEN_DIGITS = {"zero": 0, "oh": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6,
                 "seven": 7, "eight": 8, "nine": 9, "niner": 9, "ten": 10, "eleven": 11, "twelve": 12,
                 "thirteen": 13, "fourteen": 14, "fifteen": 15, "sixteen": 16, "seventeen": 17,
                 "eighteen": 18, "nineteen": 19}
SPOKEN_TENS = {"twenty": 20, "thirty": 30, "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70,
               "eighty": 80, "ninety": 90}


def is_airband(freq_text):
    mhz = parse_mhz(str(freq_text or ""))
    return mhz is not None and any(lo <= mhz <= hi for lo, hi in AIRBAND_RANGES_MHZ)


def compass(lat1, lon1, lat2, lon2):
    """8-point direction from point 1 to point 2."""
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dl = math.radians(lon2 - lon1)
    angle = math.degrees(math.atan2(math.sin(dl) * math.cos(p2),
                                    math.cos(p1) * math.sin(p2) - math.sin(p1) * math.cos(p2) * math.cos(dl)))
    return ("N", "NE", "E", "SE", "S", "SW", "W", "NW")[round((angle % 360) / 45) % 8]


def _air_tokens(text):
    return re.findall(r"[a-z0-9]+", str(text).lower().replace("x-ray", "xray"))


def _spoken_number(tokens, i, limit=4):
    """A flight number spoken from tokens[i]: ('1234', next index) or (None, i).
    Handles digits (1234, 12 34), word digits (one two three four), pairs (twelve thirty-four),
    'four seventy' (470) and 'four hundred' (400)."""
    parts, j = [], i
    while j < len(tokens) and len(parts) < limit:
        t = tokens[j]
        if t.isdigit() and len(t) <= 4:
            parts.append(t)
            j += 1
        elif t in SPOKEN_TENS:
            value = SPOKEN_TENS[t]
            if j + 1 < len(tokens) and tokens[j + 1] in SPOKEN_DIGITS and SPOKEN_DIGITS[tokens[j + 1]] < 10:
                value += SPOKEN_DIGITS[tokens[j + 1]]
                j += 1
            parts.append(str(value))
            j += 1
        elif t in SPOKEN_DIGITS:
            parts.append(str(SPOKEN_DIGITS[t]))
            j += 1
        elif t == "hundred" and parts:
            parts[-1] += "00"
            j += 1
        elif t == "thousand" and parts:
            parts[-1] += "000"
            j += 1
        else:
            break
    number = "".join(parts)
    return (number[:5], j) if number else (None, i)


def spoken_callsigns(text):
    """Callsigns said in a transcript: [{'said', 'kind': 'airline'|'registration'|'suffix', 'value'}].
    airline → 'DAL1234'; registration → 'N123AB'; suffix → '45A' (the end of an N-number)."""
    tokens = _air_tokens(text)
    found, seen, i = [], set(), 0
    names = sorted(AIRLINE_TELEPHONY, key=lambda n: -len(n.split()))
    while i < len(tokens):
        hit = None
        for name in names:
            words = name.split()
            if tokens[i:i + len(words)] == words:
                number, j = _spoken_number(tokens, i + len(words))
                if number:
                    hit = ({"said": " ".join(tokens[i:j]), "kind": "airline",
                            "value": AIRLINE_TELEPHONY[name] + number.lstrip("0")}, j)
                break
        if hit is None and re.fullmatch(r"n[1-9][0-9a-z]{1,4}", tokens[i]):            # written "N123AB"
            hit = ({"said": tokens[i], "kind": "registration", "value": tokens[i].upper()}, i + 1)
        if hit is None:
            for prefix in GA_PREFIXES:
                words = prefix.split()
                if tokens[i:i + len(words)] != words:
                    continue
                chars, j = [], i + len(words)
                while j < len(tokens) and len(chars) < 6:
                    t = tokens[j]
                    if re.fullmatch(r"[0-9][0-9a-z]{0,4}", t):          # "4", "123", "123ab"
                        chars.append(t.upper())
                    elif t in SPOKEN_DIGITS and SPOKEN_DIGITS[t] < 10:
                        chars.append(str(SPOKEN_DIGITS[t]))
                    elif t in PHONETIC:
                        chars.append(PHONETIC[t])
                    elif len(t) == 1 and t.isalpha() and chars:
                        chars.append(t.upper())
                    else:
                        break
                    j += 1
                code = "".join(chars)
                if prefix == "november" and re.fullmatch(r"[1-9][0-9A-Z]{0,4}", code or ""):
                    hit = ({"said": " ".join(tokens[i:j]), "kind": "registration", "value": "N" + code}, j)
                elif len(code) >= 3 and re.fullmatch(r"[0-9A-Z]+", code) and any(c.isdigit() for c in code):
                    hit = ({"said": " ".join(tokens[i:j]), "kind": "suffix", "value": code[-5:]}, j)
                break
        if hit:
            entry, i = hit
            key = (entry["kind"], entry["value"])
            if key not in seen:
                seen.add(key)
                found.append(entry)
        else:
            i += 1
    return found


def aircraft_name(a):
    """'DAL1234 N123DL A321' (whatever is known)."""
    return " ".join(p for p in (a.get("flight", ""), a.get("r", ""), a.get("t", "")) if p) or a.get("hex", "?").upper()


def parse_aircraft_json(data, received=None):
    """[(time, aircraft dict)] from readsb/dump1090 aircraft.json (bytes or str)."""
    doc = json.loads(data)
    now = float(doc.get("now") or received or time.time())
    out = []
    for a in doc.get("aircraft") or []:
        if not isinstance(a, dict) or not a.get("hex"):
            continue
        a = dict(a)
        a["hex"] = str(a["hex"]).lower().lstrip("~")
        a["flight"] = str(a.get("flight") or "").strip().upper()
        a["r"] = str(a.get("r") or "").strip().upper()
        a["t"] = str(a.get("t") or "").strip().upper()
        a["squawk"] = str(a.get("squawk") or "")
        seen = float(a.get("seen") or 0)
        out.append((now - seen, a))
    return out


def match_callsigns(said, candidates):
    """For each spoken callsign, the aircraft it is: [(spoken, aircraft or None, confidence)].
    `candidates` are aircraft in range around the time of the call."""
    results = []
    for s in said:
        if s["kind"] == "airline":
            hits = [a for a in candidates if a.get("flight", "").replace(" ", "") == s["value"]
                    or re.sub(r"^([A-Z]{3})0+", r"\1", a.get("flight", "")) == s["value"]]
            results.append((s, hits[0] if hits else None, "callsign" if hits else "not seen by ADS-B"))
        elif s["kind"] == "registration":
            hits = [a for a in candidates if s["value"] in (a.get("r", ""), a.get("flight", ""))]
            results.append((s, hits[0] if hits else None, "registration" if hits else "not seen by ADS-B"))
        else:
            hits = [a for a in candidates
                    if any(x.startswith("N") and x.endswith(s["value"]) for x in (a.get("r", ""), a.get("flight", "")))]
            if len(hits) == 1:
                results.append((s, hits[0], "end of registration (only match in range)"))
            elif hits:
                results.append((s, None, f"{len(hits)} aircraft in range end in {s['value']}"))
    return results


def csv_append(path, headers, row):
    path.parent.mkdir(parents=True, exist_ok=True)
    fresh = not path.exists() or path.stat().st_size == 0
    with path.open("a", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        if fresh:
            w.writerow(headers)
        w.writerow(row)


def read_csv_rows(path, headers):
    try:
        with path.open(newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            if next(reader, None) != headers:
                return []
            return [r for r in reader if len(r) == len(headers)]
    except (OSError, csv.Error, UnicodeDecodeError):
        return []


def adsb_alert_path(day):
    return ADSB_DIR / f"adsb_alerts_{day}.csv"


def adsb_heard_path(day):
    return ADSB_DIR / f"aircraft_heard_{day}.csv"


def heard_by_file(day):
    """{audio file: [rows]} of the aircraft matched in that day's transcripts."""
    out = defaultdict(list)
    for r in read_csv_rows(adsb_heard_path(day), ADSB_HEARD_HEADERS):
        out[r[3]].append(r)
    return out


def heard_line(r):
    """One line for a matched callsign under a transcript."""
    said, callsign, reg, typ, alt, speed, dist, how = r[4], r[5], r[7], r[8], r[9], r[10], r[13], r[14]
    if not r[6]:
        return f"✈ “{said}” = {callsign or '?'} ({how})"
    bits = [p for p in (callsign, reg, typ) if p]
    if alt:
        bits.append("on the ground" if alt == "ground" else f"{int(float(alt)):,} ft")
    if speed:
        bits.append(f"{float(speed):.0f} kt")
    if dist:
        bits.append(dist)
    return f"✈ “{said}” = " + " • ".join(bits)


class AdsbFeed(QObject):
    """Reads aircraft.json every few seconds; alerts; keeps an hour of positions for matching."""
    updated = pyqtSignal()
    alerted = pyqtSignal(str)
    fetched = pyqtSignal(object)            # from the HTTP worker thread

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.tracks = {}                     # hex → deque[(time, aircraft)]
        self.current = {}                    # hex → (time, aircraft) of the latest read
        self.receiver = None                 # (lat, lon) from receiver.json
        self.status, self.error, self.last_read = "off", "", 0.0
        self.source_used = ""
        self.alerted_at = {}                 # (hex, kind) → time of the last alert
        self.busy = False
        self.fetched.connect(self._ingest_result)
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.poll)
        self.apply_settings()

    # -- settings ----------------------------------------------------------------
    def setting(self, key, default=""):
        return str(self.monitor.settings.value(f"adsb/{key}", default) or "")

    def flag(self, key, default=True):
        return self.setting(key, "true" if default else "false") == "true"

    def source(self):
        """('file', path) or ('url', address) or (None, '')."""
        chosen = self.setting("source", "auto").strip()
        if chosen and chosen != "auto":
            return ("url", chosen) if chosen.startswith(("http://", "https://")) else ("file", chosen)
        for path in ADSB_SOURCES:
            if Path(path).is_file():
                return "file", path
        return ("url", ADSB_URL) if self.setting("enabled", "auto") == "true" else (None, "")

    def enabled(self):
        value = self.setting("enabled", "auto")
        if value == "auto":
            return any(Path(p).is_file() for p in ADSB_SOURCES)
        return value == "true"

    def apply_settings(self):
        if self.enabled():
            self.timer.start(max(2, int(self.setting("interval", "5") or 5)) * 1000)
            QTimer.singleShot(0, self.poll)
        else:
            self.timer.stop()
            self.status = "off"
            self.updated.emit()

    # -- reading ---------------------------------------------------------------------
    def poll(self):
        kind, where = self.source()
        if kind is None:
            self.status, self.error = "no source", "No aircraft.json found (is readsb running?)"
            self.updated.emit()
            return
        self.source_used = where
        if kind == "file":
            try:
                data = Path(where).read_bytes()
                receiver = Path(where).with_name("receiver.json")
                rec = receiver.read_bytes() if self.receiver is None and receiver.is_file() else None
            except OSError as exc:
                self._ingest_result({"error": str(exc)})
                return
            self._ingest_result({"data": data, "receiver": rec})
        elif not self.busy:
            self.busy = True
            threading.Thread(target=self._fetch, args=(where,), daemon=True).start()

    def _fetch(self, url):
        try:
            with urllib.request.urlopen(url, timeout=4) as r:
                data = r.read(20_000_000)
            rec = None
            if self.receiver is None:
                try:
                    with urllib.request.urlopen(url.rsplit("/", 1)[0] + "/receiver.json", timeout=4) as r:
                        rec = r.read(100_000)
                except Exception:
                    rec = None
            self.fetched.emit({"data": data, "receiver": rec})
        except Exception as exc:
            self.fetched.emit({"error": str(exc)})

    def _ingest_result(self, result):
        self.busy = False
        if "error" in result:
            self.status, self.error = "error", result["error"]
            self.updated.emit()
            return
        try:
            self.ingest(result["data"], result.get("receiver"))
        except (ValueError, TypeError, KeyError) as exc:
            self.status, self.error = "error", f"Unreadable aircraft.json: {exc}"
            self.updated.emit()

    def ingest(self, data, receiver=None, now=None):
        now = now or time.time()
        if receiver:
            try:
                doc = json.loads(receiver)
                if doc.get("lat") is not None and doc.get("lon") is not None:
                    self.receiver = (float(doc["lat"]), float(doc["lon"]))
            except (ValueError, TypeError):
                pass
        aircraft = parse_aircraft_json(data, now)
        self.current = {}
        for seen, a in aircraft:
            if now - seen > 60:
                continue                     # gone: readsb keeps aircraft for a while after the last message
            self.current[a["hex"]] = (seen, a)
            track = self.tracks.setdefault(a["hex"], deque(maxlen=800))
            if not track or seen > track[-1][0]:
                track.append((seen, a))
        cutoff = now - ADSB_HISTORY_S
        for hex_id in [h for h, t in self.tracks.items() if not t or t[-1][0] < cutoff]:
            del self.tracks[hex_id]
        self.status, self.error, self.last_read = "ok", "", now
        self.check_alerts(now)
        self.updated.emit()

    # -- position helpers ---------------------------------------------------------------
    def home(self):
        if self.receiver:
            return self.receiver
        gps = getattr(self.monitor, "gps", None)
        if gps is not None:
            return gps.position() or gps.scanner_location
        return None

    def where(self, a):
        """'12 mi NE' from the receiver, or ''."""
        home = self.home()
        if home is None or a.get("lat") is None or a.get("lon") is None:
            return ""
        miles = miles_between(home[0], home[1], float(a["lat"]), float(a["lon"]))
        return f"{miles:.0f} mi {compass(home[0], home[1], float(a['lat']), float(a['lon']))}"

    def distance(self, a):
        home = self.home()
        if home is None or a.get("lat") is None or a.get("lon") is None:
            return None
        return miles_between(home[0], home[1], float(a["lat"]), float(a["lon"]))

    # -- alerts ---------------------------------------------------------------------------------
    def watch_list(self):
        return [w.strip().upper() for w in self.setting("watch").replace(",", "\n").splitlines() if w.strip()]

    def watched(self, a, entries):
        names = {a["hex"].upper(), a.get("flight", ""), a.get("r", "")}
        for e in entries:
            if e.endswith("*") and any(n.startswith(e[:-1]) for n in names if n):
                return e
            if e in names:
                return e
        return None

    def check_alerts(self, now):
        emergencies = self.flag("emergency_alerts", True)
        within = float(self.setting("alert_miles", "0") or 0)
        entries = self.watch_list()
        for hex_id, (_seen, a) in self.current.items():
            reasons = []
            if emergencies:
                if a["squawk"] in EMERGENCY_SQUAWKS:
                    reasons.append(("squawk " + a["squawk"], f"Squawk {a['squawk']} ({EMERGENCY_SQUAWKS[a['squawk']]})", 1800))
                elif str(a.get("emergency") or "none") in EMERGENCY_FIELD:
                    what = EMERGENCY_FIELD[str(a["emergency"])]
                    reasons.append(("emergency " + str(a["emergency"]), f"Emergency: {what}", 1800))
            entry = self.watched(a, entries) if entries else None
            if entry:
                reasons.append(("watch " + entry, f"Watched aircraft ({entry})", 7200))
            if not reasons:
                continue
            dist = self.distance(a)
            if within and dist is not None and dist > within and not entry:
                continue
            for key, title, cooldown in reasons:
                if now - self.alerted_at.get((hex_id, key), -1e12) < cooldown:
                    continue
                self.alerted_at[(hex_id, key)] = now
                alt = a.get("alt_baro")
                bits = [aircraft_name(a)]
                if alt not in (None, ""):
                    bits.append("on the ground" if alt == "ground" else f"{int(alt):,} ft")
                if a.get("gs") is not None:
                    bits.append(f"{float(a['gs']):.0f} kt")
                if self.where(a):
                    bits.append(self.where(a))
                text = " • ".join(bits)
                self.monitor.notify(title, text, "aircraft")
                self.alerted.emit(f"{title}: {text}")
                stamp = datetime.fromtimestamp(now)
                try:
                    csv_append(adsb_alert_path(stamp.strftime("%Y-%m-%d")), ADSB_ALERT_HEADERS, [
                        stamp.strftime("%Y-%m-%d %H:%M:%S"), title, hex_id, a.get("flight", ""), a.get("r", ""),
                        a.get("t", ""), a["squawk"], "" if alt is None else alt, a.get("gs", ""),
                        a.get("lat", ""), a.get("lon", ""), "" if dist is None else f"{dist:.1f}", key])
                except OSError:
                    pass

    # -- transcripts ------------------------------------------------------------------------------
    def candidates(self, when, length=0.0):
        """Aircraft seen within the match window of a call starting at `when` (epoch seconds):
        the position nearest the call for each."""
        lo, hi = when - ADSB_MATCH_WINDOW_S, when + length + ADSB_MATCH_WINDOW_S
        out = []
        for track in self.tracks.values():
            near = [(abs(t - when), a) for t, a in track if lo <= t <= hi]
            if near:
                out.append(min(near, key=lambda x: x[0])[1])
        return out

    def transcript_added(self, row):
        """Match the callsigns in a new transcript (live only: positions are kept for an hour)."""
        if not self.enabled() or not self.flag("match", True) or not row[8]:
            return []
        frequency = ""
        for audio in read_audio_index(audio_index_path(datetime.strptime(row[0][:10], "%Y-%m-%d"))):
            if audio[-1] == row[7]:
                frequency = audio[6]
                break
        if self.flag("airband_only", True) and not is_airband(frequency):
            return []
        said = spoken_callsigns(row[8])
        if not said:
            return []
        try:
            when = datetime.strptime(row[0], "%Y-%m-%d %H:%M:%S").timestamp()
            length = float(row[6] or 0)
        except ValueError:
            return []
        if time.time() - when > ADSB_HISTORY_S - ADSB_MATCH_WINDOW_S:
            return []                         # too long ago: positions from then are gone
        rows = []
        for s, a, how in match_callsigns(said, self.candidates(when, length)):
            a = a or {}
            dist = self.distance(a) if a else None
            rows.append([row[0], row[3], frequency, row[7], s["said"], a.get("flight") or s["value"],
                         a.get("hex", ""), a.get("r", ""), a.get("t", ""),
                         "" if a.get("alt_baro") is None else a.get("alt_baro"), a.get("gs", ""),
                         a.get("lat", ""), a.get("lon", ""), self.where(a) if a else "", how])
        for r in rows:
            try:
                csv_append(adsb_heard_path(row[0][:10]), ADSB_HEARD_HEADERS, r)
            except OSError:
                pass
        return rows


class AircraftWindow(QWidget):
    """Tools → Maps → Aircraft (ADS-B)…"""
    NOW_COLUMNS = ["Callsign", "Registration", "Type", "Squawk", "Altitude (ft)", "Speed (kt)", "Where", "Seen"]

    def __init__(self, monitor):
        super().__init__(monitor)
        analysis_window(self, monitor, "Aircraft (ADS-B)", "adsb/geometry", (1000, 720))
        self.monitor = monitor
        self.feed = monitor.adsb
        s = monitor.settings
        layout = QVBoxLayout(self)
        intro = make_label("Aircraft from readsb (or dump1090) on this computer: alerts on emergency squawks and "
                           "watched aircraft, and the aircraft matched to callsigns heard in airband transcripts.")
        intro.setWordWrap(True)
        layout.addWidget(intro)
        self.status = make_label("")
        self.status.setWordWrap(True)
        set_css(self.status, "font-weight:600;color:#8bd6f2;")
        layout.addWidget(self.status)
        row = QHBoxLayout()
        settings_row = QWidget()                     # v1.2.0: in Settings → Aircraft (ADS-B), hidden here
        self.enabled = QComboBox()
        for label, value in (("On when readsb is found", "auto"), ("On", "true"), ("Off", "false")):
            self.enabled.addItem(label, value)
        self.enabled.setCurrentIndex(max(0, self.enabled.findData(self.feed.setting("enabled", "auto"))))
        self.enabled.currentIndexChanged.connect(self.save)
        row.addWidget(make_label("ADS-B"))
        row.addWidget(self.enabled)
        row.addWidget(make_label("Source"))
        self.source = QLineEdit(self.feed.setting("source", "auto"))
        self.source.setPlaceholderText("auto, a path to aircraft.json, or http://…/tar1090/data/aircraft.json")
        self.source.setToolTip("auto finds /run/readsb/aircraft.json (and the dump1090 locations). "
                               f"tar1090 over the network: {ADSB_URL}")
        self.source.editingFinished.connect(self.save)
        row.addWidget(self.source, 1)
        row.addWidget(make_label("every"))
        self.interval = QSpinBox()
        self.interval.setRange(2, 60)
        self.interval.setSuffix(" s")
        self.interval.setValue(int(self.feed.setting("interval", "5") or 5))
        self.interval.valueChanged.connect(self.save)
        row.addWidget(self.interval)
        settings_row.setLayout(row)
        layout.addWidget(settings_row)
        settings_row.hide()
        opts_row = QWidget()
        opts = QHBoxLayout()
        self.emergency = QCheckBox("Alert on emergency squawks (7500, 7600, 7700)")
        self.emergency.setChecked(self.feed.flag("emergency_alerts", True))
        self.emergency.toggled.connect(self.save)
        opts.addWidget(self.emergency)
        opts.addWidget(make_label("only within"))
        self.miles = QSpinBox()
        self.miles.setRange(0, 500)
        self.miles.setSuffix(" mi")
        self.miles.setSpecialValueText("any distance")
        self.miles.setValue(int(float(self.feed.setting("alert_miles", "0") or 0)))
        self.miles.valueChanged.connect(self.save)
        opts.addWidget(self.miles)
        self.match = QCheckBox("Match callsigns in transcripts")
        self.match.setChecked(self.feed.flag("match", True))
        self.match.toggled.connect(self.save)
        opts.addWidget(self.match)
        self.airband = QCheckBox("airband channels only")
        self.airband.setToolTip("Only calls on 108–137 MHz and 225–400 MHz")
        self.airband.setChecked(self.feed.flag("airband_only", True))
        self.airband.toggled.connect(self.save)
        opts.addWidget(self.airband)
        opts.addStretch(1)
        opts_row.setLayout(opts)
        layout.addWidget(opts_row)
        opts_row.hide()
        quick = QHBoxLayout()
        adsb_settings = QPushButton("SETTINGS…")
        adsb_settings.setToolTip("The ADS-B source, emergency squawk alerts and callsign matching")
        adsb_settings.clicked.connect(lambda: self.monitor.open_settings("aircraft"))
        quick.addWidget(adsb_settings)
        quick.addStretch(1)
        layout.addLayout(quick)
        self.tabs = QTabWidget()
        self.now_table = unit_table(self.NOW_COLUMNS)
        self.tabs.addTab(self.now_table, "Aircraft now")
        self.heard_table = unit_table(["Time", "Channel", "Said", "Callsign", "Registration", "Type",
                                       "Altitude (ft)", "Speed (kt)", "Where", "Match"])
        stretch_last(self.heard_table)
        self.tabs.addTab(self.heard_table, "Heard on the radio today")
        self.alerts_table = unit_table(["Time", "Alert", "Callsign", "Registration", "Type", "Squawk",
                                        "Altitude (ft)", "Distance (mi)"])
        self.tabs.addTab(self.alerts_table, "Alerts today")
        watch = QWidget()
        wl = QVBoxLayout(watch)
        note = make_label("One per line: a callsign (DAL1234), a registration (N123AB), an ICAO hex code (a1b2c3), "
                          "or a start with * (N911*, RCH*). You get an alert when one is seen, at most every two hours.")
        note.setWordWrap(True)
        wl.addWidget(note)
        self.watch = QTextEdit()
        self.watch.setAcceptRichText(False)
        self.watch.setPlainText(self.feed.setting("watch"))
        wl.addWidget(self.watch, 1)
        save = QPushButton("SAVE WATCH LIST")
        save.clicked.connect(self.save_watch)
        wl.addWidget(save)
        self.tabs.addTab(watch, "Watch list")
        layout.addWidget(self.tabs, 1)
        hint = make_label("Callsigns are matched while the positions from the time of the call are still kept "
                          "(one hour). Airband speech is fast, so check matches against what you hear.")
        hint.setWordWrap(True)
        set_css(hint, "color:#a5bdd2;")
        layout.addWidget(hint)
        self.feed.updated.connect(self.refresh)

    def open(self):
        self.refresh()
        restore_window(self, self.monitor)

    def save_settings(self, settings):
        if self.geometry_restored:
            settings.setValue(self.geometry_key, self.saveGeometry())

    def save(self, *_):
        s = self.monitor.settings
        s.setValue("adsb/enabled", self.enabled.currentData() or "auto")
        s.setValue("adsb/source", self.source.text().strip() or "auto")
        s.setValue("adsb/interval", self.interval.value())
        s.setValue("adsb/emergency_alerts", "true" if self.emergency.isChecked() else "false")
        s.setValue("adsb/alert_miles", self.miles.value())
        s.setValue("adsb/match", "true" if self.match.isChecked() else "false")
        s.setValue("adsb/airband_only", "true" if self.airband.isChecked() else "false")
        self.feed.apply_settings()

    def save_watch(self):
        self.monitor.settings.setValue("adsb/watch", self.watch.toPlainText().strip())
        set_text(self.status, f"Watch list saved ({len(self.feed.watch_list())} entries).")

    def refresh(self, *_):
        f = self.feed
        if f.status == "ok":
            age = time.time() - f.last_read
            home = "receiver position from readsb" if f.receiver else ("distances from GPS/scanner location"
                                                                        if f.home() else "no position for distances")
            set_text(self.status, f"Reading {f.source_used} • {len(f.current)} aircraft • "
                     f"updated {age:.0f} s ago • {home}")
        elif f.status == "off":
            set_text(self.status, "ADS-B is off.")
        else:
            set_text(self.status, f"ADS-B: {f.error}")
        rows = []
        for _hex, (seen, a) in sorted(f.current.items(), key=lambda kv: (f.distance(kv[1][1]) or 1e9)):
            alt = a.get("alt_baro")
            rows.append([a.get("flight", "") or a["hex"].upper(), a.get("r", ""), a.get("t", ""), a["squawk"],
                         "ground" if alt == "ground" else ("" if alt is None else f"{int(alt):,}"),
                         "" if a.get("gs") is None else f"{float(a['gs']):.0f}", f.where(a),
                         f"{max(0, time.time() - seen):.0f} s"])
        fill_table(self.now_table, rows)
        day = datetime.now().strftime("%Y-%m-%d")
        heard = read_csv_rows(adsb_heard_path(day), ADSB_HEARD_HEADERS)
        fill_table(self.heard_table, [[r[0][11:], r[1], r[4], r[5], r[7], r[8], r[9], r[10], r[13], r[14]]
                                      for r in reversed(heard)])
        alerts = read_csv_rows(adsb_alert_path(day), ADSB_ALERT_HEADERS)
        fill_table(self.alerts_table, [[r[0][11:], r[1], r[3], r[4], r[5], r[6], r[7], r[11]]
                                       for r in reversed(alerts)])


# ---- Rdio Scanner (v1.1.63) ------------------------------------------------------------------
#
# Sends each recorded call (PC audio capture) to an Rdio Scanner server
# (https://github.com/chuot/rdio-scanner, GPL v3), which plays them on a phone or any browser with
# their system, talkgroup and units. Calls go to <server>/api/call-upload as a multipart form
# (Rdio Scanner's docs/api.md). Calls that can't be sent are kept and tried again, also after a
# restart. Rdio Scanner needs whole-number IDs: talkgroups use their TGID, conventional channels
# their frequency in kHz, and each scanner system gets a number of its own (editable).

RDIO_QUEUE_FILE = DATA_DIR / "rdio_queue.json"
RDIO_QUEUE_MAX = 500
RDIO_RETRY_MS = 60_000


def rdio_talkgroup(row):
    """Rdio Scanner talkgroup number: the TGID, or the frequency in kHz for a conventional channel."""
    m = re.search(r"TGID[:\s]*(\d+)", str(row[7] or ""), re.I)
    if m:
        return int(m.group(1))
    mhz = parse_mhz(row[6])
    return int(round(mhz * 1000)) if mhz else None


def rdio_units(text):
    return [int(u) for u in re.findall(r"UID:\s*(\d+)", str(text or ""))]


def rdio_fields(row, key, system_id):
    """The form fields for one call (an audio index row, AUDIO_HEADERS)."""
    start = datetime.strptime(row[0], "%Y-%m-%d %H:%M:%S").astimezone()
    fields = {"key": key, "dateTime": start.isoformat(timespec="seconds"),
              "system": str(system_id), "systemLabel": row[3],
              "talkgroup": str(rdio_talkgroup(row)), "talkgroupLabel": row[5] or row[7],
              "talkgroupGroup": row[4]}
    mhz = parse_mhz(row[6])
    if mhz:
        fields["frequency"] = str(int(round(mhz * 1_000_000)))
    units = rdio_units(row[9])
    if units:
        fields["unit"] = str(units[0])
        fields["units"] = json.dumps([{"id": u, "offset": 0} for u in units])
    return fields


def multipart_body(fields, file_field, file_name, data, mime="audio/mpeg"):
    """(body bytes, Content-Type) of a multipart/form-data request."""
    boundary = "----SDS100Monitor" + os.urandom(12).hex()
    parts = []
    for name, value in fields.items():
        parts.append(f'--{boundary}\r\nContent-Disposition: form-data; name="{name}"\r\n\r\n'
                     .encode() + str(value).encode("utf-8") + b"\r\n")
    safe_name = file_name.replace('"', "_").replace("\r", "").replace("\n", "")
    parts.append(f'--{boundary}\r\nContent-Disposition: form-data; name="{file_field}"; '
                 f'filename="{safe_name}"\r\nContent-Type: {mime}\r\n\r\n'.encode("utf-8") + data + b"\r\n")
    parts.append(f"--{boundary}--\r\n".encode())
    return b"".join(parts), f"multipart/form-data; boundary={boundary}"


def rdio_post(url, body, content_type, timeout=30):
    """(HTTP status, reply text). Raises OSError when the server can't be reached."""
    request = urllib.request.Request(url, data=body, method="POST", headers={
        "Content-Type": content_type, "User-Agent": f"SDS100-Monitor/{VERSION}"})
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.status, response.read(4000).decode(errors="replace")
    except urllib.error.HTTPError as exc:
        return exc.code, exc.read(4000).decode(errors="replace")


def rdio_upload_url(server):
    server = str(server or "").strip().rstrip("/")
    if server and not re.match(r"https?://", server):
        server = "http://" + server
    return server + ("" if server.endswith("/api/call-upload") else "/api/call-upload")


class RdioUploader(QObject):
    """Sends recorded calls to Rdio Scanner in the background, keeping the ones not yet sent."""
    status = pyqtSignal(str, bool)            # text, ok (from the worker thread)

    def __init__(self, monitor, post=rdio_post):
        super().__init__(monitor)
        self.monitor = monitor
        self.post = post
        self.lock = threading.Lock()
        self.queue = self.load_queue()
        self.sent_today = 0
        self.last_text, self.last_ok = "Nothing sent yet.", True
        self.paused = False                   # the server refused the key: wait for new settings
        self.busy = False
        self.status.connect(self.show_status)
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.kick)
        self.timer.start(RDIO_RETRY_MS)
        if self.queue and self.enabled():
            QTimer.singleShot(5000, self.kick)

    # -- settings --
    def setting(self, key, default=""):
        return str(self.monitor.settings.value(f"rdio/{key}", default) or "")

    def enabled(self):
        return self.setting("enabled", "false") == "true" and bool(self.setting("url")) and bool(self.setting("key"))

    def systems(self):
        try:
            data = json.loads(self.setting("systems", "{}") or "{}")
        except ValueError:
            data = {}
        return {str(k): int(v) for k, v in data.items() if str(v).isdigit()}

    def system_id(self, name):
        """A lasting whole number for a scanner system name (new names get the next free one)."""
        systems = self.systems()
        if name not in systems:
            systems[name] = max(systems.values(), default=0) + 1
            self.monitor.settings.setValue("rdio/systems", json.dumps(systems))
        return systems[name]

    # -- queue --
    def load_queue(self):
        try:
            data = json.loads(RDIO_QUEUE_FILE.read_text(encoding="utf-8"))
            return [(str(p), list(r)) for p, r in data][-RDIO_QUEUE_MAX:]
        except (OSError, ValueError, TypeError):
            return []

    def save_queue(self):
        try:
            if self.queue:
                RDIO_QUEUE_FILE.parent.mkdir(parents=True, exist_ok=True)
                tmp = RDIO_QUEUE_FILE.with_suffix(".tmp")
                tmp.write_text(json.dumps(self.queue), encoding="utf-8")
                os.replace(tmp, RDIO_QUEUE_FILE)
            else:
                RDIO_QUEUE_FILE.unlink(missing_ok=True)
        except OSError:
            pass

    def call_saved(self, path, row):
        """A call was recorded: queue it and send it (in the background)."""
        if not self.enabled():
            return
        with self.lock:
            self.queue.append((str(path), list(row)))
            del self.queue[:-RDIO_QUEUE_MAX]
            self.save_queue()
        self.kick()

    def settings_changed(self):
        self.paused = False
        self.kick()

    def kick(self):
        if self.busy or self.paused or not self.queue or not self.enabled():
            return
        self.busy = True
        threading.Thread(target=self._work, daemon=True).start()

    def _work(self):
        try:
            self.send_pending()
        finally:
            self.busy = False

    # -- sending (worker thread; tests call it directly) --
    def send_one(self, path, row):
        """'sent', 'skip' (can never be sent), 'retry' (try later) or 'refused' (key or server)."""
        path = Path(path)
        talkgroup = rdio_talkgroup(row)
        if not path.exists() or talkgroup is None:
            return "skip", f"{path.name}: no audio file or no talkgroup/frequency; not sent."
        fields = rdio_fields(row, self.setting("key"), self.system_id(row[3] or "Scanner"))
        try:
            body, ctype = multipart_body(fields, "audio", path.name, path.read_bytes())
            code, text = self.post(rdio_upload_url(self.setting("url")), body, ctype)
        except (OSError, ValueError) as exc:
            return "retry", f"Rdio Scanner not reachable ({exc}); calls are kept and sent later."
        low = text.lower()
        if code == 200 and ("success" in low or "imported" in low):
            return "sent", f"Sent {row[5] or row[7]} ({row[0][11:]})."
        if "duplicate" in low:
            return "sent", f"{row[5] or row[7]} ({row[0][11:]}) was already on the server."
        if code in (401, 403) or "key" in low:
            return "refused", f"Rdio Scanner refused the API key: {text.strip()[:200]}"
        if code >= 500 or code == 0:
            return "retry", f"Rdio Scanner error {code}: {text.strip()[:200]}"
        return "skip", f"Rdio Scanner didn't take {path.name} ({code}): {text.strip()[:200]}"

    def send_pending(self):
        while True:
            with self.lock:
                if not self.queue or self.paused:
                    return
                path, row = self.queue[0]
            result, text = self.send_one(path, row)
            if result in ("sent", "skip"):
                with self.lock:
                    if self.queue and self.queue[0][0] == path:
                        self.queue.pop(0)
                    self.save_queue()
                if result == "sent":
                    self.sent_today += 1
                self.status.emit(text, result == "sent")
                continue
            if result == "refused":
                self.paused = True
            self.status.emit(text, False)
            return

    def show_status(self, text, ok):
        self.last_text, self.last_ok = text, ok
        if not ok:
            self.monitor.statusBar().showMessage(text, 10000)

    def test(self):
        """(ok, text): can the server be reached? The key is checked by the first call."""
        url = rdio_upload_url(self.setting("url")).removesuffix("/api/call-upload") + "/"
        try:
            request = urllib.request.Request(url, headers={"User-Agent": f"SDS100-Monitor/{VERSION}"})
            with urllib.request.urlopen(request, timeout=10) as response:
                page = response.read(20000).decode(errors="replace")
            found = "rdio" in page.lower()
            return True, ("Rdio Scanner found at " if found else "A web server answered at ") + url + \
                ("." if found else ", but it doesn't look like Rdio Scanner.")
        except urllib.error.HTTPError as exc:
            return False, f"{url} answered with error {exc.code}."
        except (OSError, ValueError) as exc:
            return False, f"Can't reach {url}: {exc}"


# ---- Starting Rdio Scanner with the Monitor (v1.1.90) ----------------------------------------------
#
# With rdio/autostart on, the Monitor checks a few seconds after it starts whether the server in rdio/url
# answers. If it doesn't, and the server is on this PC, it starts Rdio Scanner the way it is installed here:
# a systemd user service (systemctl --user start), a system service (pkexec systemctl start, which asks
# for the password), or the rdio-scanner program itself (started detached, in its own folder, where it
# keeps its database). With rdio/stop_on_exit, a program the Monitor started is stopped when it closes;
# services and a server that was already running are never stopped.

RDIO_PROGRAM_NAMES = ("rdio-scanner",)
RDIO_SERVICE_PATTERN = "rdio-scanner*.service"


def rdio_server_is_local(url):
    """True when the server address in the settings is this PC."""
    import socket
    url = str(url or "").strip()
    if not url:
        return True                              # the default, http://127.0.0.1:3000
    if not re.match(r"https?://", url):
        url = "http://" + url
    host = (urlparse(url).hostname or "").lower()
    if host in ("localhost", "127.0.0.1", "::1", "0.0.0.0", "") or host.startswith("127."):
        return True
    try:
        names = {socket.gethostname().lower(), socket.getfqdn().lower()}
    except OSError:
        names = set()
    if host in names or host.split(".")[0] in {n.split(".")[0] for n in names if n}:
        return True
    try:
        return any(info[4][0].startswith("127.") for info in socket.getaddrinfo(host, None))
    except OSError:
        return False


def rdio_program_candidates(home=None, which=shutil.which):
    """rdio-scanner programs found on this PC: on the PATH and in the usual unpacked-release folders."""
    home = Path(home) if home else Path.home()
    found = []
    for name in RDIO_PROGRAM_NAMES:
        hit = which(name)
        if hit:
            found.append(Path(hit))
    import glob
    patterns = [home / "rdio-scanner*" / "rdio-scanner", home / "rdio-scanner*" / "*" / "rdio-scanner",
                home / "Downloads" / "rdio-scanner*" / "rdio-scanner",
                home / ".local" / "bin" / "rdio-scanner", home / "bin" / "rdio-scanner",
                Path("/opt") / "rdio-scanner*" / "rdio-scanner",
                Path("/usr/local/bin/rdio-scanner"), Path("/usr/bin/rdio-scanner")]
    for pattern in patterns:
        for hit in sorted(glob.glob(str(pattern))):
            path = Path(hit)
            if path.is_file() and os.access(path, os.X_OK):
                found.append(path)
    unique = []
    for path in found:
        try:
            real = path.resolve()
        except OSError:
            real = path
        if real not in [u.resolve() for u in unique]:
            unique.append(path)
    return unique


def rdio_service_candidates(run=None):
    """systemd services named rdio-scanner…: [(scope "user"/"system", unit name)]."""
    def default_run(args):
        try:
            return subprocess.run(args, capture_output=True, text=True, timeout=5).stdout
        except (OSError, subprocess.SubprocessError):
            return ""
    run = run or default_run
    if run is default_run and shutil.which("systemctl") is None:
        return []
    found = []
    for scope, extra in (("user", ["--user"]), ("system", [])):
        out = run(["systemctl", *extra, "list-unit-files", "--no-legend", "--no-pager", RDIO_SERVICE_PATTERN])
        for line in out.splitlines():
            unit = line.split()[0] if line.split() else ""
            if unit.endswith(".service") and (scope, unit) not in found:
                found.append((scope, unit))
    return found


def rdio_detect(home=None, which=shutil.which, run=None):
    """Every way Rdio Scanner can be started here, best first: services, then programs.
    Each is {"kind": "user"/"system"/"program", "target": unit or path, "label": text}."""
    ways = []
    for scope, unit in sorted(rdio_service_candidates(run), key=lambda s: s[0] != "user"):
        ways.append({"kind": scope, "target": unit,
                     "label": f"{'User' if scope == 'user' else 'System'} service {unit}"
                              + ("" if scope == "user" else " (asks for your password)")})
    for path in rdio_program_candidates(home, which):
        ways.append({"kind": "program", "target": str(path), "label": f"Program {path}"})
    return ways


def rdio_start_command(way):
    """(program, arguments) that start Rdio Scanner the given way (services only)."""
    if way["kind"] == "user":
        return "systemctl", ["--user", "start", way["target"]]
    if way["kind"] == "system":
        return "pkexec", ["systemctl", "start", way["target"]]
    raise ValueError(way["kind"])


class RdioServer(QObject):
    """Starts Rdio Scanner when the Monitor starts (if asked), and stops a program it started."""
    status = pyqtSignal(str, bool)               # text, ok (from a worker thread)

    def __init__(self, monitor, reachable=None, launch=None, detect=None):
        super().__init__(monitor)
        self.monitor = monitor
        self.reachable = reachable or self.check_reachable
        self.launch = launch or self.launch_way
        self.detect = detect or rdio_detect
        self.started_pid = None                  # a program this Monitor started
        self.started_path = None
        self.children = []                       # Popen objects, so ended programs are reaped
        self.last_text, self.last_ok = "", True
        self.busy = False
        self.status.connect(self.show_status)

    def setting(self, key, default=""):
        return str(self.monitor.settings.value(f"rdio/{key}", default) or "")

    def autostart_on(self):
        return self.setting("autostart", "false") == "true"

    def chosen_way(self):
        """The way chosen in the settings, or the first one found (automatic)."""
        kind, target = self.setting("start_kind", "auto"), self.setting("start_target")
        if kind in ("user", "system", "program") and target:
            label = f"{'Program' if kind == 'program' else kind.title() + ' service'} {target}"
            return {"kind": kind, "target": target, "label": label}
        ways = self.detect()
        return ways[0] if ways else None

    def check_reachable(self, timeout=3):
        url = rdio_upload_url(self.setting("url") or "127.0.0.1:3000").removesuffix("/api/call-upload") + "/"
        try:
            request = urllib.request.Request(url, headers={"User-Agent": f"SDS100-Monitor/{VERSION}"})
            with urllib.request.urlopen(request, timeout=timeout):
                return True
        except urllib.error.HTTPError:
            return True                          # something answers
        except (OSError, ValueError):
            return False

    def launch_way(self, way):
        """Start it. Returns (ok, pid or None, text)."""
        if way["kind"] == "program":
            path = Path(way["target"])
            if not (path.is_file() and os.access(path, os.X_OK)):
                return False, None, f"{path} isn't there or can't be run."
            args = self.setting("start_args").split()
            log = DATA_DIR / "rdio-scanner.log"
            try:
                DATA_DIR.mkdir(parents=True, exist_ok=True)
                with open(log, "ab") as out:
                    proc = subprocess.Popen([str(path), *args], cwd=str(path.parent), stdin=subprocess.DEVNULL,
                                            stdout=out, stderr=subprocess.STDOUT, start_new_session=True)
            except OSError as exc:
                return False, None, f"Couldn't start {path}: {exc}"
            self.children.append(proc)
            return True, proc.pid, f"Started {path} (its messages go to {log})."
        program, args = rdio_start_command(way)
        if shutil.which(program) is None:
            return False, None, f"{program} isn't installed, so {way['target']} can't be started."
        try:
            result = subprocess.run([program, *args], capture_output=True, text=True, timeout=120)
        except (OSError, subprocess.SubprocessError) as exc:
            return False, None, f"Couldn't start {way['target']}: {exc}"
        if result.returncode != 0:
            why = (result.stderr or result.stdout).strip().splitlines()
            return False, None, (f"Couldn't start {way['target']}: " + (why[-1] if why else
                                                                        f"exit code {result.returncode}"))
        return True, None, f"Started {way['label']}."

    def start_if_needed(self, wait=20.0, sleep=time.sleep):
        """Worker thread: start Rdio Scanner if it doesn't answer. Returns (ok, text) and emits it."""
        def done(ok, text):
            self.status.emit(text, ok)
            return ok, text
        if self.reachable():
            return done(True, "Rdio Scanner is already running.")
        if not rdio_server_is_local(self.setting("url")):
            return done(False, "Rdio Scanner doesn't answer, and its server address is another computer, "
                               "so the Monitor can't start it.")
        way = self.chosen_way()
        if way is None:
            return done(False, "Rdio Scanner doesn't answer, and it wasn't found on this PC. Choose its "
                               "program in Tools → Settings… → Rdio Scanner.")
        ok, pid, text = self.launch(way)
        if not ok:
            return done(False, text)
        if pid:
            self.started_pid, self.started_path = pid, way["target"]
        waited = 0.0
        while waited < wait:
            sleep(1.0)
            waited += 1.0
            if self.reachable():
                self.monitor.rdio.settings_changed()          # send the calls that waited
                return done(True, text + f" It answered after {waited:.0f} s.")
        return done(False, text + f" It didn't answer within {wait:.0f} s; check its address and port.")

    def start_in_background(self):
        if self.busy:
            return
        self.busy = True

        def work():
            try:
                self.start_if_needed()
            finally:
                self.busy = False
        threading.Thread(target=work, daemon=True).start()

    def startup(self):
        """Called once the Monitor is up."""
        if self.autostart_on():
            QTimer.singleShot(3000, self.start_in_background)

    def show_status(self, text, ok):
        self.last_text, self.last_ok = text, ok
        self.monitor.statusBar().showMessage(text, 10000 if ok else 20000)

    def shutdown(self):
        """When the Monitor closes: stop a program it started, if asked to."""
        pid = self.started_pid
        if not pid or self.setting("stop_on_exit", "false") != "true":
            return False
        try:
            exe = os.readlink(f"/proc/{pid}/exe")
        except OSError:
            exe = ""
        if not exe or Path(exe).name.replace(" (deleted)", "") != Path(self.started_path or "").name:
            return False                               # it ended, or the number now belongs to another program
        try:
            os.kill(pid, 15)                           # SIGTERM: Rdio Scanner closes its database cleanly
        except OSError:
            return False
        for proc in self.children:
            if proc.pid == pid:
                try:
                    proc.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    pass
        self.started_pid = None
        return True


class RdioDialog(QDialog):
    """Tools → Alerts → Send Calls to Rdio Scanner…"""

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.rdio = monitor.rdio
        self.setWindowTitle("Send Calls to Rdio Scanner")
        self.resize(720, 760)
        layout = QVBoxLayout(self)
        intro = make_label(
            "Each recorded call (PC audio capture) is sent to your <b>Rdio Scanner</b> server, which plays "
            "them on your phone or any browser with their system, talkgroup and units. Set up Rdio Scanner "
            "(free, GPL v3) on this PC or another one, then in its admin page: <b>Options → Auto Populate</b> "
            "on, and <b>API Keys → new key</b> for all systems. Away from home, reach it through a VPN such "
            "as Tailscale or WireGuard rather than opening it to the internet.")
        intro.setWordWrap(True)
        layout.addWidget(intro)
        self.enabled = QCheckBox("Send recorded calls to Rdio Scanner")
        self.enabled.setChecked(self.rdio.setting("enabled", "false") == "true")
        set_css(self.enabled, "font-weight:700;")
        layout.addWidget(self.enabled)
        form = QFormLayout()
        self.url = QLineEdit(self.rdio.setting("url"))
        self.url.setPlaceholderText("http://127.0.0.1:3000")
        form.addRow("Server", self.url)
        self.key = QLineEdit(self.rdio.setting("key"))
        self.key.setEchoMode(QLineEdit.EchoMode.Password)
        self.key.setPlaceholderText("API key from Rdio Scanner's admin page")
        form.addRow("API key", self.key)
        layout.addLayout(form)
        layout.addWidget(make_label("System numbers (one per line, <i>name = number</i>). New systems are "
                                    "numbered as they are heard; with Auto Populate on, Rdio Scanner "
                                    "creates them. Talkgroups use their TGID, conventional channels "
                                    "their frequency in kHz."))
        self.systems = QTextEdit()
        self.systems.setAcceptRichText(False)
        self.systems.setPlainText("\n".join(f"{n} = {i}" for n, i in sorted(self.rdio.systems().items(),
                                                                             key=lambda x: x[1])))
        layout.addWidget(self.systems, 1)
        self.build_start_box(layout)
        self.state = make_label("")
        self.state.setWordWrap(True)
        layout.addWidget(self.state)
        buttons = QHBoxLayout()
        test = QPushButton("TEST CONNECTION")
        test.clicked.connect(self.test)
        save = QPushButton("SAVE")
        save.clicked.connect(self.save)
        close = QPushButton("CLOSE")
        close.clicked.connect(self.accept)
        buttons.addWidget(test)
        buttons.addStretch(1)
        buttons.addWidget(save)
        buttons.addWidget(close)
        layout.addLayout(buttons)
        self.show_state()

    # -- v1.1.90: start Rdio Scanner with the Monitor --
    def build_start_box(self, layout):
        server = self.monitor.rdio_server
        box = QGroupBox("START RDIO SCANNER WITH THE MONITOR")
        grid = QGridLayout(box)
        self.autostart = QCheckBox("Start Rdio Scanner when the Monitor starts, if it isn't running")
        self.autostart.setChecked(server.autostart_on())
        self.autostart.setToolTip("A few seconds after the Monitor starts, it checks whether the server above "
                                  "answers. If not, and the server is on this PC, it starts Rdio Scanner the "
                                  "way chosen below.")
        grid.addWidget(self.autostart, 0, 0, 1, 3)
        grid.addWidget(make_label("Start it with"), 1, 0)
        self.way = QComboBox()
        self.way.setToolTip("Automatic uses the first one found: a user service, then a system service, "
                            "then the rdio-scanner program.")
        grid.addWidget(self.way, 1, 1)
        detect = QPushButton("DETECT")
        detect.setToolTip("Look for Rdio Scanner on this PC again")
        detect.clicked.connect(lambda: self.fill_ways(announce=True))
        grid.addWidget(detect, 1, 2)
        grid.addWidget(make_label("Program"), 2, 0)
        self.program = QLineEdit(server.setting("start_target") if server.setting("start_kind") == "program" else "")
        self.program.setPlaceholderText("Only for Program: the rdio-scanner file, if it wasn't found")
        grid.addWidget(self.program, 2, 1)
        browse = QPushButton("BROWSE…")
        browse.clicked.connect(self.browse_program)
        grid.addWidget(browse, 2, 2)
        grid.addWidget(make_label("Arguments"), 3, 0)
        self.args = QLineEdit(server.setting("start_args"))
        self.args.setPlaceholderText("Optional, for the program, e.g. -listen :3000")
        grid.addWidget(self.args, 3, 1, 1, 2)
        self.stop_on_exit = QCheckBox("Stop it when the Monitor closes (only if the Monitor started the program)")
        self.stop_on_exit.setChecked(server.setting("stop_on_exit", "false") == "true")
        grid.addWidget(self.stop_on_exit, 4, 0, 1, 3)
        start_now = QPushButton("START NOW")
        start_now.setToolTip("Start Rdio Scanner now if it doesn't answer")
        start_now.clicked.connect(self.start_now)
        grid.addWidget(start_now, 5, 0)
        note = make_label("Tip: if Rdio Scanner runs as a system service, it can start with the PC instead "
                          "(sudo systemctl enable rdio-scanner); then this isn't needed.")
        note.setWordWrap(True)
        set_css(note, "color:#a5bdd2;")
        grid.addWidget(note, 6, 0, 1, 3)
        grid.setColumnStretch(1, 1)
        layout.addWidget(box)
        self.fill_ways()
        server.status.connect(self.server_status)
        self.finished.connect(lambda *_a: self.disconnect_server())

    def server_status(self, text, ok):
        self.show_state(("✓ " if ok else "✗ ") + text)

    def disconnect_server(self):
        try:
            self.monitor.rdio_server.status.disconnect(self.server_status)
        except (TypeError, RuntimeError):
            pass

    def fill_ways(self, announce=False):
        server = self.monitor.rdio_server
        self.ways = rdio_detect()
        kind, target = server.setting("start_kind", "auto"), server.setting("start_target")
        self.way.clear()
        self.way.addItem("Automatic" + (f" ({self.ways[0]['label']})" if self.ways else " (nothing found yet)"),
                         {"kind": "auto", "target": ""})
        for way in self.ways:
            self.way.addItem(way["label"], way)
        if kind == "program" and target and target not in [w["target"] for w in self.ways]:
            self.way.addItem(f"Program {target}", {"kind": "program", "target": target})
        self.way.addItem("Program… (choose the file below)", {"kind": "program", "target": ""})
        for i in range(self.way.count()):
            data = self.way.itemData(i) or {}
            if data.get("kind") == kind and (data.get("target") == target or (kind == "auto")):
                self.way.setCurrentIndex(i)
                break
        if announce:
            self.show_state(("✓ Found: " + "; ".join(w["label"] for w in self.ways)) if self.ways else
                            "✗ Rdio Scanner wasn't found on this PC. Choose its program with BROWSE….")

    def browse_program(self):
        path, _ = QFileDialog.getOpenFileName(self, "The rdio-scanner program", str(Path.home()))
        if path:
            self.program.setText(path)
            self.way.setCurrentIndex(self.way.count() - 1)

    def save_start(self):
        s = self.monitor.settings
        data = self.way.currentData() or {"kind": "auto", "target": ""}
        kind, target = data.get("kind", "auto"), data.get("target", "")
        if kind == "program" and not target:
            target = self.program.text().strip()
            if not target:
                kind = "auto"
        s.setValue("rdio/autostart", "true" if self.autostart.isChecked() else "false")
        s.setValue("rdio/start_kind", kind)
        s.setValue("rdio/start_target", target)
        s.setValue("rdio/start_args", self.args.text().strip())
        s.setValue("rdio/stop_on_exit", "true" if self.stop_on_exit.isChecked() else "false")

    def start_now(self):
        self.save()
        server = self.monitor.rdio_server
        if server.busy:
            self.show_state("Already starting Rdio Scanner…")
            return
        self.show_state("Starting Rdio Scanner if it isn't running… (the status bar says how it went)")
        server.start_in_background()

    def show_state(self, extra=""):
        r = self.rdio
        text = (f"{r.sent_today} call(s) sent since the Monitor started • {len(r.queue)} waiting"
                + (" • paused until the API key is changed" if r.paused else "") + f"<br>{r.last_text}")
        set_text(self.state, (extra + "<br>" if extra else "") + text)
        set_css(self.state, "color:#7ee3a5;" if r.last_ok and not extra.startswith("✗") else "color:#ffb3a7;")

    def parse_systems(self):
        systems = {}
        for line in self.systems.toPlainText().splitlines():
            name, sep, number = line.rpartition("=")
            if sep and name.strip() and number.strip().isdigit():
                systems[name.strip()] = int(number.strip())
        return systems

    def save(self):
        s = self.monitor.settings
        s.setValue("rdio/enabled", "true" if self.enabled.isChecked() else "false")
        s.setValue("rdio/url", self.url.text().strip())
        s.setValue("rdio/key", self.key.text().strip())
        s.setValue("rdio/systems", json.dumps(self.parse_systems()))
        self.save_start()
        self.rdio.settings_changed()
        self.show_state("✓ Saved.")

    def test(self):
        self.save()
        ok, text = self.rdio.test()
        self.show_state(("✓ " if ok else "✗ ") + text)


# ---- Second receiver: SDRTrunk (v1.1.94) ------------------------------------------------------------
#
# SDRTrunk (https://github.com/DSheirer/sdrtrunk) sends each call it decodes to an Rdio Scanner server as
# a multipart form (POST …/api/call-upload: key, system, talkgroup, source, frequency, dateTime, labels and
# the MP3 in "audio"). The Monitor listens for the same uploads, so SDRTrunk can feed it as a second
# receiver: add one more Rdio Scanner stream in SDRTrunk that points here. SDRTrunk first sends a test
# upload with no talkgroup and only accepts the server when the reply says "no talkgroup", as Rdio
# Scanner 6 does.
#
# "Record what arrives" only logs each upload (sdrtrunk/arrivals.jsonl, its MP3 in sdrtrunk/test/), to see
# what a given SDRTrunk version sends. "Add calls" puts each call in the history, unit ID log and
# recordings like a scanner reception. When the scanner logged the same talkgroup at the same time, the
# SDRTrunk call is merged into the scanner's call instead: its recording is kept with it (and becomes the
# recording when the scanner call has none) and radio IDs the scanner missed are added. Where each call
# came from is kept beside the history, in sources/call_sources_<day>.csv, so the history files keep
# their format. SDRTrunk calls are not sent on to Rdio Scanner unless asked (SDRTrunk can send there
# itself, and that would make every call twice).

SDRTRUNK_DIR = DATA_DIR / "sdrtrunk"
SDRTRUNK_ARRIVALS = SDRTRUNK_DIR / "arrivals.jsonl"
SDRTRUNK_TEST_DIR = SDRTRUNK_DIR / "test"
SDRTRUNK_ARRIVALS_KEEP = 300
SDRTRUNK_TEST_KEEP = 20
SDRTRUNK_DEFAULT_PORT = 3011
SDRTRUNK_MAX_BODY = 25 * 1024 * 1024
SDRTRUNK_WAIT_SECONDS = 10           # how long a call waits for the scanner's copy before it is added
SDRTRUNK_WAIT_LIMIT = 120            # ... at most, while the scanner is still on that talkgroup
SDRTRUNK_MODES = (("record", "Record what arrives (test; calls are not added)"),
                  ("add", "Add calls to the Monitor"))
SDRTRUNK_DUPLICATES = (("merge", "Merge with the scanner's call (recommended)"),
                       ("keep", "Keep both as separate calls"))
SDRTRUNK_REPLY_OK = "Call imported successfully."
SDRTRUNK_REPLY_TEST = "Incomplete call data: no talkgroup"

SOURCE_DIR = DATA_DIR / "sources"
SOURCE_HEADERS = ["Start", "Channel", "Source", "Recording", "Received", "Radio IDs", "Note"]
SOURCE_SCANNER = "Scanner"
SOURCE_SDRTRUNK = "SDRTrunk"
SOURCE_BOTH = "Scanner + SDRTrunk"
_SOURCE_CACHE = {}


def source_path(day):
    """day: datetime or 'YYYY-MM-DD'."""
    text = day if isinstance(day, str) else f"{day:%Y-%m-%d}"
    return SOURCE_DIR / f"call_sources_{text}.csv"


def read_sources(day):
    """{(start, channel): [source rows]} for one day, cached until the file changes."""
    path = source_path(day)
    try:
        stamp = path.stat().st_mtime_ns
    except OSError:
        return {}
    cached = _SOURCE_CACHE.get(path)
    if cached and cached[0] == stamp:
        return cached[1]
    found = defaultdict(list)
    try:
        with path.open(newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            if next(reader, None) == SOURCE_HEADERS:
                for r in reader:
                    if len(r) == len(SOURCE_HEADERS):
                        found[(r[0], r[1])].append(r)
    except (OSError, csv.Error, UnicodeDecodeError):
        return {}
    found = dict(found)
    _SOURCE_CACHE[path] = (stamp, found)
    return found


def write_source(row):
    """Add one SOURCE_HEADERS row (its day comes from its start)."""
    path = source_path(row[0][:10])
    SOURCE_DIR.mkdir(parents=True, exist_ok=True)
    with AUDIO_CSV_LOCK:
        fresh = not path.exists() or path.stat().st_size == 0
        with path.open("a", newline="", encoding="utf-8") as f:
            writer = csv.writer(f)
            if fresh:
                writer.writerow(SOURCE_HEADERS)
            writer.writerow(row)


def source_rows(row):
    """The source rows of a reception history row (empty for a scanner-only call)."""
    if len(row) < 6 or len(str(row[0])) < 10:
        return []
    return read_sources(str(row[0])[:10]).get((row[0], row[5]), [])


def call_source(row):
    """Scanner, SDRTrunk, Scanner + SDRTrunk or GQRX (1.1.95), for a reception history row."""
    kinds = {r[2] for r in source_rows(row)}
    if SOURCE_BOTH in kinds:
        return SOURCE_BOTH
    for kind in (SOURCE_SDRTRUNK, SOURCE_GQRX):
        if kind in kinds:
            return kind
    return sorted(kinds)[0] if kinds else SOURCE_SCANNER


def second_recordings(row):
    """SDRTrunk recordings kept with a scanner call (paths that exist), besides its own recording."""
    out = []
    try:
        folder = audio_day_dir(datetime.strptime(str(row[0])[:10], "%Y-%m-%d"))
    except ValueError:
        return out
    for r in source_rows(row):
        if r[2] == SOURCE_BOTH and r[3] and r[6] == "second recording":
            path = folder / r[3]
            if path.exists():
                out.append(path)
    return out


def parse_upload(content_type, body):
    """(fields {name: text}, files {name: (file name, type, bytes)}) of a multipart or urlencoded form."""
    import email.parser
    import email.policy
    fields, files = {}, {}
    ctype = str(content_type or "")
    if ctype.lower().startswith("multipart/"):
        head = f"Content-Type: {ctype}\r\nMIME-Version: 1.0\r\n\r\n".encode("latin-1", "replace")
        msg = email.parser.BytesParser(policy=email.policy.HTTP).parsebytes(head + body)
        if not msg.is_multipart():
            return fields, files
        for part in msg.iter_parts():
            name = part.get_param("name", header="content-disposition")
            if not name:
                continue
            data = part.get_payload(decode=True) or b""
            filename = part.get_filename()
            if filename is not None:
                files[name] = (filename, part.get_content_type(), data)
            else:
                charset = part.get_content_charset() or "utf-8"
                fields[name] = data.decode(charset, errors="replace")
    elif "x-www-form-urlencoded" in ctype.lower() or not ctype:
        for name, values in parse_qs(body.decode("utf-8", errors="replace"), keep_blank_values=True).items():
            fields[name] = values[-1]
    return fields, files


def _int_or_none(text):
    try:
        return int(float(str(text).strip()))
    except (TypeError, ValueError):
        return None


def upload_time(text, received=None):
    """A local datetime (no zone) from Unix seconds, milliseconds or an ISO time."""
    received = received or datetime.now()
    t = str(text or "").strip()
    if not t:
        return received
    if re.fullmatch(r"\d+(\.\d+)?", t):
        n = float(t)
        if n > 1e12:
            n /= 1000.0
        try:
            return datetime.fromtimestamp(n)
        except (OverflowError, OSError, ValueError):
            return received
    try:
        when = datetime.fromisoformat(t.replace("Z", "+00:00"))
    except ValueError:
        return received
    return when.astimezone().replace(tzinfo=None) if when.tzinfo else when


_MP3_BITRATES = {
    (1, 1): (0, 32, 64, 96, 128, 160, 192, 224, 256, 288, 320, 352, 384, 416, 448),
    (1, 2): (0, 32, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384),
    (1, 3): (0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320),
    (2, 1): (0, 32, 48, 56, 64, 80, 96, 112, 128, 144, 160, 176, 192, 224, 256),
    (2, 2): (0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160),
    (2, 3): (0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160),
}
_MP3_RATES = {1: (44100, 48000, 32000), 2: (22050, 24000, 16000), 25: (11025, 12000, 8000)}


def mp3_seconds(data):
    """Length of an MP3 in seconds, by walking its frames (0.0 when it isn't one)."""
    i, n = 0, len(data)
    if data[:3] == b"ID3" and n >= 10:
        size = (data[6] & 0x7F) << 21 | (data[7] & 0x7F) << 14 | (data[8] & 0x7F) << 7 | (data[9] & 0x7F)
        i = 10 + size + (10 if data[5] & 0x10 else 0)
    seconds, frames, misses = 0.0, 0, 0
    while i + 4 <= n:
        b1, b2, b3 = data[i + 1], data[i + 2], data[i + 3]
        if data[i] != 0xFF or (b1 & 0xE0) != 0xE0:
            i += 1
            misses += 1
            if misses > 65536:
                break
            continue
        ver_bits, layer_bits = (b1 >> 3) & 3, (b1 >> 1) & 3
        bitrate_i, rate_i, padding = (b2 >> 4) & 15, (b2 >> 2) & 3, (b2 >> 1) & 1
        if ver_bits == 1 or layer_bits == 0 or bitrate_i in (0, 15) or rate_i == 3:
            i += 1
            continue
        version = {3: 1, 2: 2, 0: 25}[ver_bits]
        layer = 4 - layer_bits
        kbps = _MP3_BITRATES[(1 if version == 1 else 2, layer)][bitrate_i]
        rate = _MP3_RATES[version][rate_i]
        if layer == 1:
            samples, length = 384, (12 * kbps * 1000 // rate + padding) * 4
        else:
            samples = 1152 if (layer == 2 or version == 1) else 576
            length = samples // 8 * kbps * 1000 // rate + padding
        if length <= 4:
            i += 1
            continue
        seconds += samples / rate
        frames += 1
        i += length
    return round(seconds, 1) if frames else 0.0


def upload_reply(fields, files, key):
    """(HTTP code, reply text, ok) for an upload, as Rdio Scanner 6 answers SDRTrunk."""
    given = str(fields.get("key", ""))
    if not key or not hmac.compare_digest(given.encode(), str(key).encode()):
        return 401, "Invalid API key", False
    if str(fields.get("test", "")).strip() not in ("", "0", "false") or _int_or_none(fields.get("talkgroup")) is None:
        return 417, SDRTRUNK_REPLY_TEST, False
    audio = files.get("audio")
    if not audio or len(audio[2]) < 100:
        return 417, "Incomplete call data: no audio", False
    return 200, SDRTRUNK_REPLY_OK, True


def upload_call(fields, files, received=None):
    """One SDRTrunk call as plain data, from an accepted upload."""
    received = received or datetime.now()
    filename, ctype, data = files["audio"]
    start = upload_time(fields.get("dateTime"), received)
    seconds = mp3_seconds(data)
    radio = _int_or_none(fields.get("source"))
    hz = _int_or_none(fields.get("frequency"))
    return {
        "received": received, "start": start, "seconds": seconds,
        "system": str(fields.get("system", "")).strip(),
        "system_label": str(fields.get("systemLabel", "")).strip(),
        "talkgroup": _int_or_none(fields.get("talkgroup")),
        "talkgroup_label": str(fields.get("talkgroupLabel", "")).strip(),
        "talkgroup_group": str(fields.get("talkgroupGroup", "")).strip(),
        "talkgroup_tag": str(fields.get("talkgroupTag", "")).strip(),
        "radio": radio if radio else None,
        "talker_alias": str(fields.get("talkerAlias", "")).strip(),
        "frequency": hz if hz else None,
        "patches": str(fields.get("patches", "")).strip(),
        "audio": data, "audio_name": str(fields.get("audioName", "") or filename or "call.mp3"),
        "audio_type": str(fields.get("audioType", "") or ctype or "audio/mpeg"),
    }


def arrival_record(fields, files, code, text, received=None, saved=""):
    """What the arrivals log keeps of one upload: every field (the key hidden) and the file's details."""
    shown = {k: ("•" * min(len(v), 8) if k == "key" else v[:300]) for k, v in sorted(fields.items())}
    return {"received": (received or datetime.now()).strftime("%Y-%m-%d %H:%M:%S"), "reply": code,
            "reply_text": text, "fields": shown,
            "files": {k: {"name": f[0], "type": f[1], "bytes": len(f[2]),
                          "seconds": mp3_seconds(f[2])} for k, f in files.items()},
            "saved": saved}


def read_arrivals(limit=50):
    """The newest arrival records, newest first."""
    try:
        lines = SDRTRUNK_ARRIVALS.read_text(encoding="utf-8").splitlines()
    except OSError:
        return []
    out = []
    for line in reversed(lines[-limit:]):
        try:
            out.append(json.loads(line))
        except ValueError:
            pass
    return out


def arrivals_text(records):
    """The arrivals as plain text, to read or paste."""
    out = []
    for a in records:
        out.append(f"{a.get('received', '')}  reply {a.get('reply', '')} — {a.get('reply_text', '')}")
        for k, v in (a.get("fields") or {}).items():
            out.append(f"    {k} = {v}")
        for k, f in (a.get("files") or {}).items():
            out.append(f"    {k}: file {f.get('name')} ({f.get('type')}, {f.get('bytes', 0):,} bytes, "
                       f"{f.get('seconds', 0)} s)")
        if a.get("saved"):
            out.append(f"    saved as {a['saved']}")
        out.append("")
    return "\n".join(out).rstrip() or "Nothing has arrived yet."


def tgid_of(text):
    m = re.search(r"TGID[:\s]*(\d+)", str(text or ""), re.I) or re.fullmatch(r"\s*(\d+)\s*", str(text or ""))
    return int(m.group(1)) if m else None


def match_scanner_call(call, scanner_calls, window=4.0, system=None):
    """The scanner call (from scanner_calls: [(history row, units)]) that is the same call as an SDRTrunk
    call: same talkgroup, its time inside the scanner's (give or take `window` seconds), and the same
    system when the SDRTrunk system is named after a scanner system. Nearest start wins."""
    if call.get("talkgroup") is None:
        return None
    start = call["start"]
    end = start + timedelta(seconds=max(call.get("seconds") or 0.0, 0.0))
    slack = timedelta(seconds=window)
    best, best_gap = None, None
    for item in scanner_calls:
        row = item[0]
        if tgid_of(row[7]) != call["talkgroup"]:
            continue
        if system and row[3] != system:
            continue
        s, e = parse_stamp(row[0]), parse_stamp(row[1])
        if s is None:
            continue
        e = e or s
        if start > e + slack or end < s - slack:
            continue
        gap = abs((start - s).total_seconds())
        if best is None or gap < best_gap:
            best, best_gap = item, gap
    return best


class SdrTrunkReceiver(QObject):
    """Tools → SDRTrunk Receiver…: takes SDRTrunk's call uploads (Rdio Scanner format)."""
    arrived = pyqtSignal(object)            # a call dict (from the server thread)
    changed = pyqtSignal()

    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.httpd = None
        self.problem = ""
        self.pending = []
        self.counts = Counter()
        self.count_day = datetime.now().date()
        self.last_text = "Nothing received yet."
        self.lock = threading.Lock()
        self.arrived.connect(self.take)
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.process)
        self.timer.start(2000)

    # -- settings --
    def setting(self, key, default=""):
        return str(self.monitor.settings.value(f"sdrtrunk/{key}", default) or default)

    def set_setting(self, key, value):
        self.monitor.settings.setValue(f"sdrtrunk/{key}", value)

    def enabled(self):
        return self.setting("enabled", "false") == "true"

    def port(self):
        return _int_or_none(self.setting("port", str(SDRTRUNK_DEFAULT_PORT))) or SDRTRUNK_DEFAULT_PORT

    def key(self):
        key = self.setting("key")
        if not key:
            key = os.urandom(12).hex()
            self.set_setting("key", key)
        return key

    def mode(self):
        return self.setting("mode", "record")

    def duplicates(self):
        return self.setting("duplicates", "merge")

    def window(self):
        try:
            return max(0.0, float(self.setting("window", "4")))
        except ValueError:
            return 4.0

    def systems(self):
        """{SDRTrunk system number: name}."""
        try:
            data = json.loads(self.setting("systems", "{}"))
        except ValueError:
            data = {}
        return {str(k): str(v) for k, v in data.items() if str(v).strip()}

    def seen_systems(self):
        try:
            data = json.loads(self.setting("seen", "{}"))
        except ValueError:
            data = {}
        return {str(k): str(v) for k, v in data.items()}

    def note_system(self, number, label):
        seen = self.seen_systems()
        if number and (number not in seen or (label and seen[number] != label)):
            seen[number] = label or seen.get(number, "")
            self.set_setting("seen", json.dumps(seen))

    def system_name(self, call):
        return (self.systems().get(call["system"]) or call["system_label"]
                or (f"SDRTrunk system {call['system']}" if call["system"] else "SDRTrunk"))

    def address(self):
        host = "127.0.0.1" if self.setting("listen", "local") != "network" else (local_ip_address() or "this-pc")
        return f"http://{host}:{self.port()}/api/call-upload"

    # -- server --
    def start(self):
        self.shutdown()
        self.problem = ""
        if not self.enabled():
            self.changed.emit()
            return
        recv = self
        self.key()                              # made here, not on a server thread

        class H(BaseHTTPRequestHandler):
            def log_message(self, *a):
                pass

            def reply(self, code, text):
                data = (text + "\n").encode()
                self.send_response(code)
                self.send_header("Content-Type", "text/plain; charset=utf-8")
                self.send_header("Content-Length", str(len(data)))
                self.end_headers()
                self.wfile.write(data)

            def do_GET(self):
                self.reply(200, f"SDS100 Monitor {VERSION}: SDRTrunk receiver. Send calls to POST "
                                "/api/call-upload.")

            def do_POST(self):
                try:
                    length = int(self.headers.get("Content-Length") or 0)
                except ValueError:
                    length = 0
                if length <= 0 or length > SDRTRUNK_MAX_BODY:
                    return self.reply(413 if length > 0 else 411, "Upload too large" if length > 0
                                      else "Content-Length needed")
                body = self.rfile.read(length)
                try:
                    code, text = recv.handle_upload(self.headers.get("Content-Type", ""), body)
                except Exception as exc:          # the Monitor must never fail over one upload
                    code, text = 500, f"Monitor error: {exc}"
                self.reply(code, text)

        host = "0.0.0.0" if self.setting("listen", "local") == "network" else "127.0.0.1"
        try:
            self.httpd = ThreadingHTTPServer((host, self.port()), H)
        except OSError as exc:
            self.httpd = None
            self.problem = f"Can't listen on port {self.port()}: {exc}"
            self.changed.emit()
            return
        threading.Thread(target=self.httpd.serve_forever, daemon=True).start()
        self.changed.emit()

    def shutdown(self):
        if self.httpd is not None:
            self.httpd.shutdown()
            self.httpd.server_close()
            self.httpd = None

    def listening(self):
        return self.httpd is not None

    def handle_upload(self, content_type, body):
        """(code, reply text). Runs on a server thread."""
        received = datetime.now()
        fields, files = parse_upload(content_type, body)
        code, text, ok = upload_reply(fields, files, self.key())
        saved = ""
        call = upload_call(fields, files, received) if ok else None
        if ok and self.mode() == "record":
            saved = self.save_test_audio(call)
        self.log_arrival(arrival_record(fields, files, code, text, received, saved))
        if ok:
            self.arrived.emit(call)
        elif code == 417 and text == SDRTRUNK_REPLY_TEST:
            self.arrived.emit({"test": True, "received": received})
        return code, text

    def save_test_audio(self, call):
        try:
            SDRTRUNK_TEST_DIR.mkdir(parents=True, exist_ok=True)
            name = f"{call['received']:%Y%m%d_%H%M%S}_TG{call['talkgroup']}.mp3"
            path, n = SDRTRUNK_TEST_DIR / name, 2
            while path.exists():
                path, n = SDRTRUNK_TEST_DIR / name.replace(".mp3", f"_{n}.mp3"), n + 1
            path.write_bytes(call["audio"])
            for old in sorted(SDRTRUNK_TEST_DIR.glob("*.mp3"))[:-SDRTRUNK_TEST_KEEP]:
                old.unlink(missing_ok=True)
            return str(path)
        except OSError:
            return ""

    def log_arrival(self, record):
        with self.lock:
            try:
                SDRTRUNK_DIR.mkdir(parents=True, exist_ok=True)
                try:
                    lines = SDRTRUNK_ARRIVALS.read_text(encoding="utf-8").splitlines()
                except OSError:
                    lines = []
                lines.append(json.dumps(record))
                tmp = SDRTRUNK_ARRIVALS.with_suffix(".tmp")
                tmp.write_text("\n".join(lines[-SDRTRUNK_ARRIVALS_KEEP:]) + "\n", encoding="utf-8")
                os.replace(tmp, SDRTRUNK_ARRIVALS)
            except OSError:
                pass

    # -- calls (main thread) --
    def count(self, what):
        today = datetime.now().date()
        if today != self.count_day:
            self.counts.clear()
            self.count_day = today
        self.counts[what] += 1

    def take(self, call):
        if call.get("test"):
            self.count("tests")
            self.last_text = f"{call['received']:%H:%M:%S} SDRTrunk tested the connection: answered as Rdio Scanner."
            self.changed.emit()
            return
        self.count("received")
        self.note_system(call["system"], call["system_label"])
        label = call["talkgroup_label"] or f"TG {call['talkgroup']}"
        if self.mode() != "add":
            self.last_text = (f"{call['received']:%H:%M:%S} recorded {label} ({call['seconds']:.1f} s); "
                              "not added (Record what arrives).")
            self.changed.emit()
            return
        self.pending.append(call)
        self.process()

    def process(self):
        if not self.pending:
            return
        now = datetime.now()
        keep = []
        for call in self.pending:
            try:
                done = self.decide(call, now)
            except Exception as exc:          # one bad call must not stop the others
                self.last_text = f"SDRTrunk call not added: {exc}"
                done = True
            if not done:
                keep.append(call)
        self.pending = keep
        self.changed.emit()

    def scanner_busy_on(self, talkgroup):
        rec = getattr(self.monitor, "reception", None)
        return bool(rec) and tgid_of(rec.get("info", {}).get("Talkgroup")) == talkgroup

    def decide(self, call, now):
        """True when the call was merged or added; False to wait for the scanner's copy."""
        if self.duplicates() == "merge":
            scanner_calls = list(getattr(self.monitor, "scanner_calls", ()))
            mapped = self.systems().get(call["system"])
            known = {item[0][3] for item in scanner_calls} | {r[3] for r in getattr(self.monitor, "history_rows", [])}
            match = match_scanner_call(call, scanner_calls, self.window(), mapped if mapped in known else None)
            if match is not None:
                self.merge(call, match)
                return True
            age = (now - call["received"]).total_seconds()
            if getattr(self.monitor, "connected", False):
                if self.scanner_busy_on(call["talkgroup"]) and age < SDRTRUNK_WAIT_LIMIT:
                    return False
                if age < SDRTRUNK_WAIT_SECONDS:
                    return False
        self.add(call)
        return True

    def names_for(self, call):
        """(system, department, channel) for a call: SDRTrunk's labels, else the scanner's names for it."""
        system = self.system_name(call)
        department, channel = call["talkgroup_group"], call["talkgroup_label"]
        if not channel or not department:
            for row in getattr(self.monitor, "history_rows", []):
                if tgid_of(row[7]) == call["talkgroup"] and (row[3] == system or not self.systems().get(call["system"])):
                    channel = channel or row[5]
                    department = department or row[4]
                    break
        return system, department or "—", channel or f"TG {call['talkgroup']}"

    def unit_text(self, call):
        if not call["radio"]:
            return ""
        return f"{call['talker_alias']} (UID:{call['radio']})" if call["talker_alias"] else f"UID:{call['radio']}"

    def save_audio(self, call, start, channel, suffix="_sdrtrunk"):
        folder = audio_day_dir(start)
        folder.mkdir(parents=True, exist_ok=True)
        base = f"{start:%H%M%S}_{safe_file_part(channel)}{suffix}"
        path, n = folder / f"{base}.mp3", 2
        while path.exists():
            path, n = folder / f"{base}_{n}.mp3", n + 1
        path.write_bytes(call["audio"])
        return path

    def index_audio(self, row):
        index_recording(row)

    def add(self, call):
        """A call the scanner didn't log: into the history like a reception."""
        m = self.monitor
        start = call["start"].replace(microsecond=0)
        end = start + timedelta(seconds=round(call["seconds"]))
        system, department, channel = self.names_for(call)
        frequency = f"{call['frequency'] / 1e6:.6f}MHz" if call["frequency"] else "—"
        talkgroup = f"TGID:{call['talkgroup']}"
        row = [start.strftime("%Y-%m-%d %H:%M:%S"), end.strftime("%Y-%m-%d %H:%M:%S"), f"{call['seconds']:.1f}",
               system, department, channel, frequency, talkgroup, "—"]
        unit = self.unit_text(call)
        values = dict(zip(HEADERS, row))
        values.update({"Site": "—", "Unit ID": unit or "—", "Mode": "—", "RSSI": "—"})
        if unit:
            m.log_unit(values, f"UID:{call['radio']}", call["talker_alias"] or "—", when=start)
        m.add_row(row)
        m.add_stat(row)
        try:
            m.activity_watch.reception(row, [str(call["radio"])] if call["radio"] else [])
        except Exception as exc:          # analysis must never stop logging
            m.statusBar().showMessage(f"Activity Watch: {exc}", 5000)
        m.check_alerts(values)
        m.write_history_row(row)
        name = ""
        try:
            path = self.save_audio(call, start, channel)
            name = path.name
            audio_row = row[:8] + ["—", unit or "—", "—", "—", f"{call['seconds']:.1f}", name]
            self.index_audio(audio_row)
        except OSError as exc:
            m.statusBar().showMessage(f"SDRTrunk recording not saved: {exc}", 10000)
            audio_row = None
        write_source([row[0], row[5], SOURCE_SDRTRUNK, name, f"{call['received']:%Y-%m-%d %H:%M:%S}",
                      str(call["radio"] or ""), ""])
        if audio_row is not None:
            m.external_audio_saved(path, audio_row, self.setting("forward_rdio", "false") == "true")
        self.count("added")
        self.last_text = f"{call['received']:%H:%M:%S} added {channel} ({call['seconds']:.1f} s), heard only by SDRTrunk."

    def merge(self, call, match):
        """The scanner logged the same call: keep SDRTrunk's recording and radio ID with it."""
        m = self.monitor
        row, units = match[0], list(match[1])
        start = parse_stamp(row[0])
        own = find_recording(row)
        note = "second recording" if own is not None else "recording"
        name = ""
        try:
            path = self.save_audio(call, start, row[5])
            name = path.name
        except OSError as exc:
            m.statusBar().showMessage(f"SDRTrunk recording not saved: {exc}", 10000)
            path = None
        added = ""
        if call["radio"] and str(call["radio"]) not in [uid_key(u) for u in units]:
            values = dict(zip(HEADERS, row))
            values["Site"] = "—"
            m.log_unit(values, f"UID:{call['radio']}", call["talker_alias"] or "—", when=start)
            match[1].append(self.unit_text(call))
            added = str(call["radio"])
        write_source([row[0], row[5], SOURCE_BOTH, name, f"{call['received']:%Y-%m-%d %H:%M:%S}",
                      str(call["radio"] or ""), note])
        if path is not None and own is None:
            unit_list = "; ".join(u for u in match[1] if u) or "—"
            audio_row = row[:8] + ["—", unit_list, "—", row[8], f"{call['seconds']:.1f}", name]
            self.index_audio(audio_row)
            m.external_audio_saved(path, audio_row, self.setting("forward_rdio", "false") == "true")
        self.count("merged")
        self.last_text = (f"{call['received']:%H:%M:%S} merged with the scanner's {row[5]} at {row[0][11:]}"
                          + (f"; added radio ID {added}" if added else "") + ".")

    def status_text(self):
        if not self.enabled():
            return "Off."
        if self.problem:
            return self.problem
        c = self.counts
        mode = "recording what arrives (test)" if self.mode() != "add" else "adding calls"
        return (f"Listening at {self.address()} — {mode}. Today: {c['received']:,} calls received, "
                f"{c['added']:,} added, {c['merged']:,} merged with the scanner"
                + (f", {len(self.pending)} waiting for the scanner's copy" if self.pending else "")
                + (f", {c['tests']:,} connection tests" if c["tests"] else "") + ".\nLast: " + self.last_text)


def local_ip_address():
    """This PC's address on the local network (the one used to reach other machines), or ''."""
    import socket
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(("192.0.2.1", 9))           # no packet is sent: this only picks the outgoing interface
        return s.getsockname()[0]
    except OSError:
        return ""
    finally:
        s.close()


